INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('822e8e5b-145e-57f1-ad79-a7c94bfbd593', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 32, 32, 'So Jephthah passed over to the children of Ammon to fight against them; and Yahweh delivered them into his hand.'),
  ('d3b9519f-4177-562c-a268-328087b4a165', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 33, 33, 'He struck them from Aroer until you come to Minnith, even twenty cities, and to Abelcheramim, with a very great slaughter. So the children of Ammon were subdued before the children of Israel.'),
  ('64a93f4b-95b8-5ebc-a5a7-973208f36a27', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 34, 34, 'Jephthah came to Mizpah to his house; and behold, his daughter came out to meet him with tambourines and with dances: and she was his only child; besides her he had neither son nor daughter.'),
  ('a410d27b-7dd9-5792-aa73-a69cb18f768d', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 35, 35, 'It happened, when he saw her, that he tore his clothes, and said, "Alas, my daughter! You have brought me very low, and you are one of those who trouble me; for I have opened my mouth to Yahweh, and I can''t go back."'),
  ('fee781c8-4e4f-5bed-ab25-ebceb86f4444', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 36, 36, 'She said to him, "My father, you have opened your mouth to Yahweh; do to me according to that which has proceeded out of your mouth, because Yahweh has taken vengeance for you on your enemies, even on the children of Ammon."'),
  ('03a78b7a-eb58-551e-aa7e-4e1e20c6c00c', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 37, 37, 'She said to her father, "Let this thing be done for me: let me alone two months, that I may depart and go down on the mountains, and bewail my virginity, I and my companions."'),
  ('46160fb6-b840-5c5c-aeee-4e406023a480', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 38, 38, 'He said, "Go." He sent her away for two months: and she departed, she and her companions, and mourned her virginity on the mountains.'),
  ('3c030882-998a-5c08-a9a7-f2356d482b97', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 39, 39, 'It happened at the end of two months, that she returned to her father, who did with her according to his vow which he had vowed: and she was a virgin. It was a custom in Israel,'),
  ('de408eda-4fd1-5f52-abf5-ee08f86ba271', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 40, 40, 'that the daughters of Israel went yearly to celebrate the daughter of Jephthah the Gileadite four days in a year.'),
  ('2543929c-8191-5070-a67b-6a811dfa1e76', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 1, 1, 'The men of Ephraim were gathered together, and passed northward; and they said to Jephthah, "Why did you pass over to fight against the children of Ammon, and didn''t call us to go with you? We will burn your house around you with fire!"'),
  ('a79f44b7-f118-502f-a32f-09e401c6e7a3', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 2, 2, 'Jephthah said to them, "I and my people were at great strife with the children of Ammon; and when I called you, you didn''t save me out of their hand.'),
  ('e2ad2bcf-9c29-5048-a8ff-30a8d6033b19', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 3, 3, 'When I saw that you didn''t save me, I put my life in my hand, and passed over against the children of Ammon, and Yahweh delivered them into my hand. Why then have you come up to me this day, to fight against me?"'),
  ('286863ee-687f-503f-ad4c-9f23626b6459', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 4, 4, 'Then Jephthah gathered together all the men of Gilead, and fought with Ephraim; and the men of Gilead struck Ephraim, because they said, "You are fugitives of Ephraim, you Gileadites, in the midst of Ephraim, [and] in the midst of Manasseh."'),
  ('d99e1041-738a-5b2f-a171-9b73e6f4d182', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 5, 5, 'The Gileadites took the fords of the Jordan against the Ephraimites. It was so, that when [any of] the fugitives of Ephraim said, Let me go over, the men of Gilead said to him, "Are you an Ephraimite?" If he said, "No;"'),
  ('0395b6e2-b23a-5fad-a002-fc18f26a6557', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 6, 6, 'then they said to him, "Now say ''Shibboleth;''" and he said "Sibboleth;" for he couldn''t manage to pronounce it right: then they laid hold of him, and killed him at the fords of the Jordan. At that time, forty-two thousand of Ephraim fell.'),
  ('6d6a9c43-d781-576c-a636-5ef9b4d141c7', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 7, 7, 'Jephthah judged Israel six years. Then died Jephthah the Gileadite, and was buried in [one of] the cities of Gilead.'),
  ('7f24c470-bd54-59bd-a9af-8a1c893fb4ae', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 8, 8, 'After him Ibzan of Bethlehem judged Israel.'),
  ('2e02ceb4-3dc0-5680-acaa-61c6f1762a87', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 9, 9, 'He had thirty sons; and thirty daughters he sent abroad, and thirty daughters he brought in from abroad for his sons. He judged Israel seven years.'),
  ('59936416-68db-5dd6-a651-2f714e15549b', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 10, 10, 'Ibzan died, and was buried at Bethlehem.'),
  ('30754a27-1d85-5b3e-ac9a-d05320f921e7', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 11, 11, 'After him Elon the Zebulunite judged Israel; and he judged Israel ten years.'),
  ('ff566ce9-bd69-563a-a4ac-7d618b98b5f7', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 12, 12, 'Elon the Zebulunite died, and was buried in Aijalon in the land of Zebulun.'),
  ('09491d65-f171-5fea-ad38-65ad744c9434', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 13, 13, 'After him Abdon the son of Hillel the Pirathonite judged Israel.'),
  ('4096d22f-b5b2-51d4-af49-b3cb7d732e48', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 14, 14, 'He had forty sons and thirty sons'' sons, who rode on seventy donkey colts: and he judged Israel eight years.'),
  ('a624bb23-8fe6-58bb-a604-46f668844e56', '01a3a5c7-1c93-5745-ab39-d7d8f323804d', NULL, 15, 15, 'Abdon the son of Hillel the Pirathonite died, and was buried in Pirathon in the land of Ephraim, in the hill country of the Amalekites.'),
  ('e3721af9-7966-5432-af21-0539d7d659a4', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 1, 1, 'The children of Israel again did that which was evil in the sight of Yahweh; and Yahweh delivered them into the hand of the Philistines forty years.'),
  ('4d88a85b-5439-59d8-ae98-dcf1340c29d1', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 2, 2, 'There was a certain man of Zorah, of the family of the Danites, whose name was Manoah; and his wife was barren, and didn''t bear.'),
  ('dd7ea3d0-fbad-5650-a0df-a18866917997', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 3, 3, 'The angel of Yahweh appeared to the woman, and said to her, "See now, you are barren, and don''t bear; but you shall conceive, and bear a son.'),
  ('4d8b01fd-3491-54a0-a789-b5ecacf6eb10', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 4, 4, 'Now therefore please beware and drink no wine nor strong drink, and don''t eat any unclean thing:'),
  ('c77274f0-4d9b-572b-a862-07125024e512', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 5, 5, 'for, behold, you shall conceive, and bear a son; and no razor shall come on his head; for the child shall be a Nazirite to God from the womb: and he shall begin to save Israel out of the hand of the Philistines."'),
  ('d48ae924-b90c-5703-a7ad-4a91f9231e19', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 6, 6, 'Then the woman came and told her husband, saying, "A man of God came to me, and his face was like the face of the angel of God, very awesome; and I didn''t ask him where he was from, neither did he tell me his name:'),
  ('40c0fb1d-026b-5af6-a600-5e084db223e1', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 7, 7, 'but he said to me, ''Behold, you shall conceive, and bear a son; and now drink no wine nor strong drink, and eat not any unclean thing; for the child shall be a Nazirite to God from the womb to the day of his death.''"'),
  ('0bef7d49-f77d-5e81-a876-eeee86232001', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 8, 8, 'Then Manoah entreated Yahweh, and said, "Oh, Lord, please let the man of God whom you did send come again to us, and teach us what we shall do to the child who shall be born."'),
  ('789ca834-0c92-57f7-ae2e-5cf9150efa09', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 9, 9, 'God listened to the voice of Manoah; and the angel of God came again to the woman as she sat in the field: but Manoah, her husband, wasn''t with her.'),
  ('69925f74-b6aa-560a-a6c2-35eefdfb5306', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 10, 10, 'The woman made haste, and ran, and told her husband, and said to him, "Behold, the man has appeared to me, who came to me the [other] day."'),
  ('b9e3a093-4e19-54b8-a31a-4ffed04598a5', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 11, 11, 'Manoah arose, and went after his wife, and came to the man, and said to him, "Are you the man who spoke to the woman?" He said, "I am."'),
  ('2e53fd1a-2ceb-57af-aff2-9819d865be7c', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 12, 12, 'Manoah said, "Now let your words happen. What shall be the ordering of the child, and [how] shall we do to him?"'),
  ('44721990-197b-5a7f-af69-29f630c619a5', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 13, 13, 'The angel of Yahweh said to Manoah, "Of all that I said to the woman let her beware.'),
  ('deb1a6b9-dbe0-555b-a904-cf17c114b8b4', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 14, 14, 'She may not eat of anything that comes of the vine, neither let her drink wine or strong drink, nor eat any unclean thing; all that I commanded her let her observe."'),
  ('662d8be0-fb90-5eca-a847-af40fba12c32', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 15, 15, 'Manoah said to the angel of Yahweh, "Please, let us detain you, that we may make a young goat ready for you."'),
  ('28f399dd-b376-5f5e-a111-586f33c4d422', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 16, 16, 'The angel of Yahweh said to Manoah, "Though you detain me, I won''t eat of your bread; and if you will prepare a burnt offering, you must offer it to Yahweh." For Manoah didn''t know that he was the angel of Yahweh.'),
  ('e4f31e24-162c-57df-adaf-81640bf6b410', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 17, 17, 'Manoah said to the angel of Yahweh, "What is your name, that when your words happen, we may honor you?"'),
  ('faf77672-9623-578f-abb5-22a79b398a5a', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 18, 18, 'The angel of Yahweh said to him, "Why do you ask about my name, since it is wonderful?"'),
  ('c4c844ea-f433-5ad1-a324-4962b068cc1d', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 19, 19, 'So Manoah took the young goat with the meal offering, and offered it on the rock to Yahweh: and [the angel] did wondrously, and Manoah and his wife looked on.'),
  ('7be49619-dfef-564e-aa4b-aa344d954fa8', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 20, 20, 'For it happened, when the flame went up toward the sky from off the altar, that the angel of Yahweh ascended in the flame of the altar: and Manoah and his wife looked on; and they fell on their faces to the ground.'),
  ('c402a082-9246-5a8a-a25f-31bf660e44ba', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 21, 21, 'But the angel of Yahweh did no more appear to Manoah or to his wife. Then Manoah knew that he was the angel of Yahweh.'),
  ('e87ff64c-512e-5ae8-a103-0dcc880b09fb', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 22, 22, 'Manoah said to his wife, "We shall surely die, because we have seen God."'),
  ('259d128f-cae5-5a19-a3a5-480276827692', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 23, 23, 'But his wife said to him, "If Yahweh were pleased to kill us, he wouldn''t have received a burnt offering and a meal offering at our hand, neither would he have shown us all these things, nor would at this time have told such things as these."'),
  ('74969544-1319-5cd3-a5c7-b7ea21cad3a0', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 24, 24, 'The woman bore a son, and named him Samson: and the child grew, and Yahweh blessed him.'),
  ('d47904a5-cab7-5c82-a51c-37049d40c398', '7b418e08-5f1d-5ab8-a6a2-cb05bd549780', NULL, 25, 25, 'The Spirit of Yahweh began to move him in Mahaneh Dan, between Zorah and Eshtaol.'),
  ('9bcd679c-97bb-52bd-a77e-31eeb3b8d575', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 1, 1, 'Samson went down to Timnah, and saw a woman in Timnah of the daughters of the Philistines.'),
  ('8436d24c-a418-51c6-ad65-97d4d338d153', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 2, 2, 'He came up, and told his father and his mother, and said, "I have seen a woman in Timnah of the daughters of the Philistines: now therefore get her for me as wife."'),
  ('3082afc4-0423-5b85-ac13-11b4245e740b', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 3, 3, 'Then his father and his mother said to him, "Is there never a woman among the daughters of your brothers, or among all my people, that you go to take a wife of the uncircumcised Philistines?" Samson said to his father, "Get her for me; for she pleases me well."'),
  ('20c502cb-39ff-5928-ae88-0eff23fcdd4f', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 4, 4, 'But his father and his mother didn''t know that it was of Yahweh; for he sought an occasion against the Philistines. Now at that time the Philistines had rule over Israel.'),
  ('57d9bfb3-167c-5a0f-a424-dbe8a84c02f0', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 5, 5, 'Then went Samson down, and his father and his mother, to Timnah, and came to the vineyards of Timnah: and behold, a young lion roared against him.'),
  ('5584a785-4859-59fd-a12c-eadb9fe383f9', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 6, 6, 'The Spirit of Yahweh came mightily on him, and he tore him as he would have torn a young goat; and he had nothing in his hand: but he didn''t tell his father or his mother what he had done.'),
  ('b06068e2-0956-5a67-a95b-716e293fe3e8', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 7, 7, 'He went down, and talked with the woman, and she pleased Samson well.'),
  ('5fd03e8c-d94e-55be-a915-02e90ce3324d', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 8, 8, 'After a while he returned to take her; and he turned aside to see the carcass of the lion: and behold, there was a swarm of bees in the body of the lion, and honey.'),
  ('483f2b61-ed15-52b1-aa1b-96dcab179a00', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 9, 9, 'He took it into his hands, and went on, eating as he went; and he came to his father and mother, and gave to them, and they ate: but he didn''t tell them that he had taken the honey out of the body of the lion.'),
  ('1d647373-6cdc-5618-a867-7c57efc3cb1f', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 10, 10, 'His father went down to the woman: and Samson made there a feast; for so used the young men to do.'),
  ('3bf9f8c9-574b-51a5-a7bb-90f5f11c8f3f', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 11, 11, 'It happened, when they saw him, that they brought thirty companions to be with him.'),
  ('54de7ce4-4008-5e9f-a743-9d5f1b068981', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 12, 12, 'Samson said to them, "Let me tell you a riddle now. If you can declare it to me within the seven days of the feast, and find it out, then I will give you thirty linen garments and thirty changes of clothing;'),
  ('49fd72a5-05a2-51ff-a928-dabfcca8a807', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 13, 13, 'but if you can''t declare it to me, then you shall give me thirty linen garments and thirty changes of clothing." They said to him, "Put forth your riddle, that we may hear it."'),
  ('e494c110-3fd6-5e66-a2c2-b7a2fd438a48', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 14, 14, 'He said to them, "Out of the eater came forth food. Out of the strong came forth sweetness." They couldn''t in three days declare the riddle.'),
  ('65957d05-dfa8-58d3-acb3-a97e47f33e20', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 15, 15, 'It happened on the seventh day, that they said to Samson''s wife, "Entice your husband, that he may declare to us the riddle, lest we burn you and your father''s house with fire. Have you called us to impoverish us? Is it not [so]?"'),
  ('c3a89236-9685-5496-a2b7-b7e8704f76f0', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 16, 16, 'Samson''s wife wept before him, and said, "You just hate me, and don''t love me. You have put forth a riddle to the children of my people, and haven''t told it me." He said to her, "Behold, I haven''t told it my father nor my mother, and shall I tell you?"'),
  ('460cd4b2-8b4f-5bd4-aa24-67a99c319c61', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 17, 17, 'She wept before him the seven days, while their feast lasted: and it happened on the seventh day, that he told her, because she pressed him severely; and she told the riddle to the children of her people.'),
  ('8324817d-05cf-5742-aafa-8cf753b07058', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 18, 18, 'The men of the city said to him on the seventh day before the sun went down, "What is sweeter than honey? What is stronger than a lion?" He said to them, "If you hadn''t plowed with my heifer, you wouldn''t have found out my riddle."'),
  ('6a742dc0-716d-5659-a0f6-80b5a2bceb19', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 19, 19, 'The Spirit of Yahweh came mightily on him, and he went down to Ashkelon, and struck thirty men of them, and took their spoil, and gave the changes [of clothing] to those who declared the riddle. His anger was kindled, and he went up to his father''s house.'),
  ('50e88312-c933-5582-a930-67e316046703', '15c389d8-d7ec-5eff-ac4f-37dca3f3b879', NULL, 20, 20, 'But Samson''s wife was [given] to his companion, whom he had used as his friend.'),
  ('f8798b30-b37b-58b8-aeb0-983fa244021f', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 1, 1, 'But it happened after a while, in the time of wheat harvest, that Samson visited his wife with a young goat; and he said, "I will go in to my wife into the room." But her father wouldn''t allow him to go in.'),
  ('e67d4aa1-f350-5eda-a1ea-fa0e60ac49f0', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 2, 2, 'Her father said, "I most certainly thought that you had utterly hated her; therefore I gave her to your companion. Isn''t her younger sister more beautiful than she? Please take her, instead."'),
  ('807649c4-158d-5d7e-a4c8-e7eb2da1de69', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 3, 3, 'Samson said to them, "This time I will be blameless in regard of the Philistines, when I harm them."'),
  ('40187164-03a4-5b0c-a268-7678d7ede521', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 4, 4, 'Samson went and caught three hundred foxes, and took torches, and turned tail to tail, and put a torch in the midst between every two tails.'),
  ('e5c8750f-475a-5741-af67-5383dd68a40f', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 5, 5, 'When he had set the brands on fire, he let them go into the standing grain of the Philistines, and burnt up both the shocks and the standing grain, and also the olive groves.'),
  ('e2daa20c-e830-59d6-ac08-384928933968', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 6, 6, 'Then the Philistines said, "Who has done this?" They said, "Samson, the son-in-law of the Timnite, because he has taken his wife, and given her to his companion." The Philistines came up, and burnt her and her father with fire.'),
  ('91af0a37-2c70-52fd-a89f-957721d1c7b2', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 7, 7, 'Samson said to them, "If you behave like this, surely I will be avenged of you, and after that I will cease."'),
  ('14ecf677-4b81-5460-a49c-11a06c4b057b', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 8, 8, 'He struck them hip and thigh with a great slaughter: and he went down and lived in the cleft of the rock of Etam.'),
  ('45f42565-fede-5ca5-ae50-596c25c1fd02', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 9, 9, 'Then the Philistines went up, and encamped in Judah, and spread themselves in Lehi.'),
  ('73dd8612-cd6c-5df9-ad81-c60e0d24904f', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 10, 10, 'The men of Judah said, "Why have you come up against us?" They said, "We have come up to bind Samson, to do to him as he has done to us."'),
  ('38e0c0fd-fb9d-58d1-a59f-b06f04d6cf47', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 11, 11, 'Then three thousand men of Judah went down to the cleft of the rock of Etam, and said to Samson, "Don''t you know that the Philistines are rulers over us? What then is this that you have done to us?" He said to them, "As they did to me, so have I done to them."'),
  ('66457bee-1be4-52bc-a3c0-af39e0ee720c', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 12, 12, 'They said to him, "We have come down to bind you, that we may deliver you into the hand of the Philistines." Samson said to them, "Swear to me that you will not fall on me yourselves."'),
  ('7d18cd7c-5d93-5640-ab89-900f3877f86c', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 13, 13, 'They spoke to him, saying, "No; but we will bind you fast, and deliver you into their hand; but surely we will not kill you." They bound him with two new ropes, and brought him up from the rock.'),
  ('b171d24b-af17-58f8-a62f-c2c18652517c', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 14, 14, 'When he came to Lehi, the Philistines shouted as they met him: and the Spirit of Yahweh came mightily on him, and the ropes that were on his arms became as flax that was burnt with fire, and his bands dropped from off his hands.'),
  ('a10558f6-1074-5df6-af83-b51ed0cf015e', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 15, 15, 'He found a fresh jawbone of a donkey, and put forth his hand, and took it, and struck a thousand men therewith.'),
  ('233b4b03-1e99-58ae-a0cb-44eefb8d197c', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 16, 16, 'Samson said, "With the jawbone of a donkey, heaps on heaps; with the jawbone of a donkey I have struck a thousand men."'),
  ('a9775e65-aa5a-5801-a1e1-9cdc44368118', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 17, 17, 'It happened, when he had made an end of speaking, that he cast away the jawbone out of his hand; and that place was called Ramath Lehi.'),
  ('352493d4-1917-50ca-abe5-982bb25cb125', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 18, 18, 'He was very thirsty, and called on Yahweh, and said, "You have given this great deliverance by the hand of your servant; and now shall I die for thirst, and fall into the hand of the uncircumcised?"'),
  ('3915e64d-ab28-58db-a40e-7cfa1dd5ca92', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 19, 19, 'But God split the hollow place that is in Lehi, and water came out of it. When he had drunk, his spirit came again, and he revived: therefore its name was called En Hakkore, which is in Lehi, to this day.'),
  ('49c54db0-35bd-5582-a5ef-8c8be1983983', '49e688c1-2644-50e7-a6e5-697abd235588', NULL, 20, 20, 'He judged Israel in the days of the Philistines twenty years.'),
  ('480d883f-f168-5de4-aa91-a7c430fa9f3e', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 1, 1, 'Samson went to Gaza, and saw there a prostitute, and went in to her.'),
  ('0d3e686d-1eb4-5cc0-a121-b8439d2feee6', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 2, 2, '[It was told] the Gazites, saying, "Samson is here!" They surrounded him, and laid wait for him all night in the gate of the city, and were quiet all the night, saying, [Let be] until morning light, then we will kill him.'),
  ('f902a22d-31fb-572e-a59c-1b4bf77d1fa6', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 3, 3, 'Samson lay until midnight, and arose at midnight, and laid hold of the doors of the gate of the city, and the two posts, and plucked them up, bar and all, and put them on his shoulders, and carried them up to the top of the mountain that is before Hebron.'),
  ('84f65df4-0a8a-5f36-a51e-33d6bf715b65', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 4, 4, 'It came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah.'),
  ('8b52d49b-0d0c-5986-a863-910d2ddd2033', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 5, 5, 'The lords of the Philistines came up to her, and said to her, "Entice him, and see in which his great strength lies, and by what means we may prevail against him, that we may bind him to afflict him; and we will each give you eleven hundred [pieces] of silver."'),
  ('608a4c13-1dc9-56e0-a848-4077ddd93895', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 6, 6, 'Delilah said to Samson, "Please tell me where your great strength lies, and what you might be bound to afflict you."'),
  ('99db2383-c2dd-5a01-af47-0b40c8c5c079', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 7, 7, 'Samson said to her, "If they bind me with seven green cords that were never dried, then shall I become weak, and be as another man."'),
  ('e912c95a-f72f-5634-a6fb-97a810ac28d8', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 8, 8, 'Then the lords of the Philistines brought up to her seven green cords which had not been dried, and she bound him with them.'),
  ('24446e1f-05f2-5dc0-adb9-f7122e22f7a9', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 9, 9, 'Now she had an ambush waiting in the inner room. She said to him, "The Philistines are on you, Samson!" He broke the cords, as a string of tow is broken when it touches the fire. So his strength was not known.'),
  ('bbd51024-e4b6-5a31-a92c-ee30ff571f18', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 10, 10, 'Delilah said to Samson, "Behold, you have mocked me, and told me lies: now please tell me with which you might be bound."'),
  ('918121b8-fc4b-5fe2-a04c-dac285ad6ba5', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 11, 11, 'He said to her, "If they only bind me with new ropes with which no work has been done, then shall I become weak, and be as another man."'),
  ('0a25b861-ac6c-5a17-a304-cc4383352adb', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 12, 12, 'So Delilah took new ropes, and bound him therewith, and said to him, "The Philistines are on you, Samson!" The ambush was waiting in the inner room. He broke them off his arms like a thread.'),
  ('6fcaeaab-8201-564e-a8f4-01b5eb631168', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 13, 13, 'Delilah said to Samson, "Until now, you have mocked me and told me lies. Tell me with what you might be bound." He said to her, "If you weave the seven locks of my head with the web."'),
  ('e6dde935-392a-544a-afc9-5c1050fb414a', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 14, 14, 'She fastened it with the pin, and said to him, "The Philistines are on you, Samson!" He awakened out of his sleep, and plucked away the pin of the beam, and the web.'),
  ('b14771a8-258a-5f1f-a1c4-6d75bb5a06ef', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 15, 15, 'She said to him, "How can you say, ''I love you,'' when your heart is not with me? You have mocked me these three times, and have not told me where your great strength lies."'),
  ('e1f5d2c1-6c5a-54e3-a1f9-2951d1cd9eb6', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 16, 16, 'It happened, when she pressed him daily with her words, and urged him, that his soul was troubled to death.'),
  ('92a8b6a6-c38c-5ec8-a09e-eb1889575635', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 17, 17, 'He told her all his heart, and said to her, "No razor has ever come on my head; for I have been a Nazirite to God from my mother''s womb. If I am shaved, then my strength will go from me, and I will become weak, and be like any other man."'),
  ('32865f45-c509-5b8b-ae0f-2e3e7e011172', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 18, 18, 'When Delilah saw that he had told her all his heart, she sent and called for the lords of the Philistines, saying, "Come up this once, for he has told me all his heart." Then the lords of the Philistines came up to her, and brought the money in their hand.'),
  ('ee28fab6-290d-5903-a5c0-e77cbc637679', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 19, 19, 'She made him sleep on her knees; and she called for a man, and shaved off the seven locks of his head; and she began to afflict him, and his strength went from him.'),
  ('365accc2-974e-5cbd-aabc-0ff2d60cff2f', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 20, 20, 'She said, "The Philistines are upon you, Samson!" He awoke out of his sleep, and said, "I will go out as at other times, and shake myself free." But he didn''t know that Yahweh had departed from him.'),
  ('4ea5583c-8458-515b-a23d-e0a119e72636', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 21, 21, 'The Philistines laid hold on him, and put out his eyes; and they brought him down to Gaza, and bound him with fetters of brass; and he ground at the mill in the prison.'),
  ('bee4011a-c73e-5207-adce-372c418500e4', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 22, 22, 'However the hair of his head began to grow again after he was shaved.'),
  ('5611d140-2d8f-5af9-a8bf-3e1003b4c4f0', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 23, 23, 'The lords of the Philistines gathered them together to offer a great sacrifice to Dagon their god, and to rejoice; for they said, "Our god has delivered Samson our enemy into our hand."'),
  ('08b53868-0d04-5d5e-ae3c-46f36e4a9e66', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 24, 24, 'When the people saw him, they praised their god; for they said, "Our god has delivered our enemy and the destroyer of our country, who has slain many of us, into our hand."'),
  ('ebf90be9-545e-5fb5-afba-974e306808ef', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 25, 25, 'It happened, when their hearts were merry, that they said, "Call for Samson, that he may entertain us." They called for Samson out of the prison; and he performed before them. They set him between the pillars;'),
  ('a72128dc-d597-53a7-a574-8ce9bc380561', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 26, 26, 'and Samson said to the boy who held him by the hand, "Allow me to feel the pillars whereupon the house rests, that I may lean on them."'),
  ('576d198c-ca9f-5620-af2a-c095e0ae12df', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 27, 27, 'Now the house was full of men and women; and all the lords of the Philistines were there; and there were on the roof about three thousand men and women, who saw while Samson performed.'),
  ('a2eb5414-3ac4-59d1-ac39-6f853db7a561', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 28, 28, 'Samson called to Yahweh, and said, "Lord Yahweh, remember me, please, and strengthen me, please, only this once, God, that I may be at once avenged of the Philistines for my two eyes."'),
  ('2a0c45fa-ae57-5276-af94-27134336f202', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 29, 29, 'Samson took hold of the two middle pillars on which the house rested, and leaned on them, the one with his right hand, and the other with his left.'),
  ('51161357-2258-5c4e-a5f6-4a2d0e3fc471', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 30, 30, 'Samson said, "Let me die with the Philistines!" He bowed himself with all his might; and the house fell on the lords, and on all the people who were therein. So the dead that he killed at his death were more than those who he killed in his life.'),
  ('fde16bb6-383e-5792-a489-9e60e3892abb', '6589c84f-4072-5a17-ab97-48d6c149858a', NULL, 31, 31, 'Then his brothers and all the house of his father came down, and took him, and brought him up, and buried him between Zorah and Eshtaol in the burial site of Manoah his father. He judged Israel twenty years.'),
  ('1727aca9-f28e-5c91-aba7-85ea088f44a3', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 1, 1, 'There was a man of the hill country of Ephraim, whose name was Micah.'),
  ('72bfaead-0076-5e0b-a7e4-8166c070e04e', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 2, 2, 'He said to his mother, "The eleven hundred [pieces] of silver that were taken from you, about which you uttered a curse, and also spoke it in my ears, behold, the silver is with me; I took it." His mother said, "Blessed be my son of Yahweh."'),
  ('47a64e38-5841-5d20-adee-1db875739957', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 3, 3, 'He restored the eleven hundred [pieces] of silver to his mother; and his mother said, "I most certainly dedicate the silver to Yahweh from my hand for my son, to make an engraved image and a molten image. Now therefore I will restore it to you."'),
  ('e69afde7-add6-5973-a69c-5b64f3090ead', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 4, 4, 'When he restored the money to his mother, his mother took two hundred [pieces] of silver, and gave them to the founder, who made of it an engraved image and a molten image: and it was in the house of Micah.'),
  ('2c8d7d00-2920-5228-a89b-53b853d4c9f4', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 5, 5, 'The man Micah had a house of gods, and he made an ephod, and teraphim, and consecrated one of his sons, who became his priest.'),
  ('7d722ab9-11f0-54d4-a57b-2aefd68545f3', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 6, 6, 'In those days there was no king in Israel: every man did that which was right in his own eyes.'),
  ('fd75b17e-3055-53a2-a415-df7b784fa77e', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 7, 7, 'There was a young man out of Bethlehem Judah, of the family of Judah, who was a Levite; and he lived there.'),
  ('0c82d399-22ca-5b28-a1c4-30377c0ab8b4', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 8, 8, 'The man departed out of the city, out of Bethlehem Judah, to live where he could find [a place], and he came to the hill country of Ephraim to the house of Micah, as he traveled.'),
  ('100e30a5-b1e5-5d04-ac41-e0eba5185392', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 9, 9, 'Micah said to him, "Where did you come from?" He said to him, "I am a Levite of Bethlehem Judah, and I am looking for a place to live."'),
  ('e64876ce-ca82-528c-a474-f10372381b6b', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 10, 10, 'Micah said to him, "Dwell with me, and be to me a father and a priest, and I will give you ten [pieces] of silver per year, a suit of clothing, and your food." So the Levite went in.'),
  ('3e351212-c2e2-568d-acbd-6070e7c0c294', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 11, 11, 'The Levite was content to dwell with the man; and the young man was to him as one of his sons.'),
  ('8d030224-90e2-5786-a760-6041d98fc366', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 12, 12, 'Micah consecrated the Levite, and the young man became his priest, and was in the house of Micah.'),
  ('a213ac39-2228-5c71-a529-d85d2a1e0c7e', 'f916b4cd-9fad-5bd3-a9b9-90482ea103b2', NULL, 13, 13, 'Then Micah said, "Now know I that Yahweh will do good to me, since I have a Levite to my priest."'),
  ('f2512e5b-c3a9-5e6a-aa93-623462e0654b', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 1, 1, 'In those days there was no king in Israel: and in those days the tribe of the Danites sought them an inheritance to dwell in; for to that day [their] inheritance had not fallen to them among the tribes of Israel.'),
  ('723caefe-8384-5c8c-a28d-c2d4b7f8030d', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 2, 2, 'The children of Dan sent of their family five men from their whole number, men of valor, from Zorah, and from Eshtaol, to spy out the land, and to search it; and they said to them, "Go, explore the land!" They came to the hill country of Ephraim, to the house of Micah, and lodged there.'),
  ('a05b4387-bfe5-5804-af99-a1272337b06d', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 3, 3, 'When they were by the house of Micah, they knew the voice of the young man the Levite; and they turned aside there, and said to him, "Who brought you here? What do you do in this place? What do you have here?"'),
  ('0e2c1ab6-4728-5a54-ad86-884f7f850f57', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 4, 4, 'He said to them, "Thus and thus has Micah dealt with me, and he has hired me, and I am become his priest."'),
  ('403fbd36-c8da-5cd5-ab4c-fd77ef2c3c18', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 5, 5, 'They said to him, "Please ask counsel of God, that we may know whether our way which we go shall be prosperous."'),
  ('b32bc97c-0e16-5e0d-a54f-33214d641fbe', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 6, 6, 'The priest said to them, "Go in peace. Your way in which you go is before Yahweh."'),
  ('4be46100-4533-51f8-aa15-abc41c431ed5', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 7, 7, 'Then the five men departed, and came to Laish, and saw the people who were therein, how they lived in security, in the way of the Sidonians, quiet and secure; for there was none in the land, possessing authority, that might put [them] to shame in anything, and they were far from the Sidonians, and had no dealings with any man.'),
  ('867d6d1c-9eb1-58cb-a142-a92e7dd2ba48', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 8, 8, 'They came to their brothers to Zorah and Eshtaol: and their brothers said to them, "What do you say?"'),
  ('38fa156c-0ce9-5dcf-a9e2-159ba79bb2cd', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 9, 9, 'They said, "Arise, and let us go up against them; for we have seen the land, and behold, it is very good. Do you stand still? Don''t be slothful to go and to enter in to possess the land.'),
  ('6e87ce7e-3360-5aca-ac54-7d21db399240', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 10, 10, 'When you go, you shall come to a secure people, and the land is large; for God has given it into your hand, a place where there is no want of anything that is in the earth."'),
  ('fce61542-1c7a-54ac-a5b2-78a757f36ab1', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 11, 11, 'There set forth from there of the family of the Danites, out of Zorah and out of Eshtaol, six hundred men girt with weapons of war.'),
  ('fe257416-a154-5ca9-a40f-cc7882e0a930', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 12, 12, 'They went up, and encamped in Kiriath Jearim, in Judah: therefore they called that place Mahaneh Dan, to this day; behold, it is behind Kiriath Jearim.'),
  ('67618c29-abc8-5cbe-a951-1c189b1b3a31', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 13, 13, 'They passed there to the hill country of Ephraim, and came to the house of Micah.'),
  ('13a97b0c-9246-55f0-afb0-d7da55186fde', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 14, 14, 'Then the five men who went to spy out the country of Laish answered, and said to their brothers, "Do you know that there is in these houses an ephod, and teraphim, and an engraved image, and a molten image? Now therefore consider what you have to do."'),
  ('4fe08e48-1af0-5103-a5d8-49011f273d20', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 15, 15, 'They turned aside there, and came to the house of the young man the Levite, even to the house of Micah, and asked him of his welfare.'),
  ('e094f033-468b-5aa2-a58e-287dff5da43c', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 16, 16, 'The six hundred men girt with their weapons of war, who were of the children of Dan, stood by the entrance of the gate.'),
  ('f7b539fc-3b64-59c5-a853-b7c0d2073db8', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 17, 17, 'The five men who went to spy out the land went up, and came in there, and took the engraved image, and the ephod, and the teraphim, and the molten image: and the priest stood by the entrance of the gate with the six hundred men girt with weapons of war.'),
  ('70466d36-08a5-5d8f-a01b-bb2b2ba3785e', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 18, 18, 'When these went into Micah''s house, and fetched the engraved image, the ephod, and the teraphim, and the molten image, the priest said to them, "What are you doing?"'),
  ('1addf25f-b635-53f4-a32d-bde328550e5a', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 19, 19, 'They said to him, "Hold your peace, put your hand on your mouth, and go with us, and be to us a father and a priest. Is it better for you to be priest to the house of one man, or to be priest to a tribe and a family in Israel?"'),
  ('9ebde2eb-b32b-5df2-a89a-e9c3db1a1630', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 20, 20, 'The priest''s heart was glad, and he took the ephod, and the teraphim, and the engraved image, and went in the midst of the people.'),
  ('3ac2f18e-1b80-577b-a015-676823a79a55', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 21, 21, 'So they turned and departed, and put the little ones and the livestock and the goods before them.'),
  ('32873820-0712-590b-aa31-0a676e21a1c4', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 22, 22, 'When they were a good way from the house of Micah, the men who were in the houses near to Micah''s house were gathered together, and overtook the children of Dan.'),
  ('d3327912-f881-5319-a397-f283780942c7', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 23, 23, 'They cried to the children of Dan. They turned their faces, and said to Micah, "What ails you, that you come with such a company?"'),
  ('d66b713a-bc88-5431-ab6d-f0f58e677bcf', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 24, 24, 'He said, "You have taken away my gods which I made, and the priest, and have gone away, and what more do I have? How then do you say to me, ''What ails you?''"'),
  ('9de231b4-b906-5004-ada3-9afbe0cad66a', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 25, 25, 'The children of Dan said to him, "Don''t let your voice be heard among us, lest angry fellows fall on you, and you lose your life, with the lives of your household."'),
  ('3efe6107-cf89-52d0-ae9a-77b93159c1d1', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 26, 26, 'The children of Dan went their way: and when Micah saw that they were too strong for him, he turned and went back to his house.'),
  ('1d671676-ead8-5d94-af24-31df3c72255c', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 27, 27, 'They took that which Micah had made, and the priest whom he had, and came to Laish, to a people quiet and secure, and struck them with the edge of the sword; and they burnt the city with fire.'),
  ('477aef20-12d2-5a44-a3f3-dac99b0ff00d', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 28, 28, 'There was no deliverer, because it was far from Sidon, and they had no dealings with any man; and it was in the valley that lies by Beth Rehob. They built the city, and lived therein.'),
  ('0926e160-e428-534b-aedb-4b55867d5dcb', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 29, 29, 'They called the name of the city Dan, after the name of Dan their father, who was born to Israel: however the name of the city was Laish at the first.'),
  ('9b4d4937-6ade-5c71-ab40-0f78c4c43e64', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 30, 30, 'The children of Dan set up for themselves the engraved image: and Jonathan, the son of Gershom, the son of Moses, he and his sons were priests to the tribe of the Danites until the day of the captivity of the land.'),
  ('89fa8f2b-81ac-558d-ac94-981618988123', '2840a76c-f99f-5591-ad6f-724633000fa9', NULL, 31, 31, 'So they set them up Micah''s engraved image which he made, all the time that the house of God was in Shiloh.'),
  ('46388baf-71a7-552f-a6d9-100870692af1', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 1, 1, 'It happened in those days, when there was no king in Israel, that there was a certain Levite living on the farther side of the hill country of Ephraim, who took to him a concubine out of Bethlehem Judah.'),
  ('a27a7e08-16a3-5a08-a366-4788542ab8ed', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 2, 2, 'His concubine played the prostitute against him, and went away from him to her father''s house to Bethlehem Judah, and was there the space of four months.'),
  ('70c653c4-111f-53f5-ab08-1a628cf61607', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 3, 3, 'Her husband arose, and went after her, to speak kindly to her, to bring her again, having his servant with him, and a couple of donkeys: and she brought him into her father''s house; and when the father of the young lady saw him, he rejoiced to meet him.'),
  ('552bda7b-44e2-530f-a879-de19ac1b9d13', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 4, 4, 'His father-in-law, the young lady''s father, retained him; and he stayed with him three days: so they ate and drink, and lodged there.'),
  ('a28c7ebd-e320-5679-a965-82769ab641da', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 5, 5, 'It happened on the fourth day, that they arose early in the morning, and he rose up to depart: and the young lady''s father said to his son-in-law, "Strengthen your heart with a morsel of bread, and afterward you shall go your way."'),
  ('1216a124-0205-5d60-ab7c-d157e8474fe9', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 6, 6, 'So they sat down, ate, and drank, both of them together: and the young lady''s father said to the man, "Please be pleased to stay all night, and let your heart be merry."'),
  ('8b296919-32a6-5082-a701-3d2734ec4690', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 7, 7, 'The man rose up to depart; but his father-in-law urged him, and he lodged there again.'),
  ('9133f745-0751-507e-ae5b-a2add82124dd', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 8, 8, 'He arose early in the morning on the fifth day to depart; and the young lady''s father said, "Please strengthen your heart and stay until the day declines;" and they both ate.'),
  ('a5060e8d-ccb6-5ed6-a8b4-06ee83bd9fb7', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 9, 9, 'When the man rose up to depart, he, and his concubine, and his servant, his father-in-law, the young lady''s father, said to him, "Behold, now the day draws toward evening, please stay all night: behold, the day grows to an end, lodge here, that your heart may be merry; and tomorrow go on your way early, that you may go home."'),
  ('0f95ba28-fa56-5381-a842-b7a0b90e7aa2', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 10, 10, 'But the man wouldn''t stay that night, but he rose up and departed, and came over against Jebus (the same is Jerusalem): and there were with him a couple of donkeys saddled; his concubine also was with him.'),
  ('ab93194a-350e-5727-a415-e1c7e6bf4526', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 11, 11, 'When they were by Jebus, the day was far spent; and the servant said to his master, "Please come and let us turn aside into this city of the Jebusites, and lodge in it."'),
  ('0a23da7a-ccc4-5c87-af79-f1afd6b39cb6', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 12, 12, 'His master said to him, "We won''t turn aside into the city of a foreigner, that is not of the children of Israel; but we will pass over to Gibeah."'),
  ('ad9d8495-62f6-5717-ad9a-7de240be94c7', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 13, 13, 'He said to his servant, "Come and let us draw near to one of these places; and we will lodge in Gibeah, or in Ramah."'),
  ('18cf6c0f-83c2-5a25-a391-6f271719ca00', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 14, 14, 'So they passed on and went their way; and the sun went down on them near to Gibeah, which belongs to Benjamin.'),
  ('b2c23bda-0297-53ef-a5e4-a31b080d27c9', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 15, 15, 'They turned aside there, to go in to lodge in Gibeah: and he went in, and sat him down in the street of the city; for there was no man who took them into his house to lodge.'),
  ('e0c9b513-bcf6-58c4-aba6-5afc5bccc9b6', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 16, 16, 'Behold, there came an old man from his work out of the field at evening: now the man was of the hill country of Ephraim, and he lived in Gibeah; but the men of the place were Benjamites.'),
  ('340f50ac-8a07-56ea-a879-d5c9ff69f173', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 17, 17, 'He lifted up his eyes, and saw the wayfaring man in the street of the city; and the old man said, "Where are you going? Where did you come from?"'),
  ('669991d0-d835-5ef5-a5c6-e5fb35f093bc', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 18, 18, 'He said to him, "We are passing from Bethlehem Judah to the farther side of the hill country of Ephraim. I am from there, and I went to Bethlehem Judah. I am going to the house of Yahweh; and there is no man who takes me into his house.'),
  ('6a16eb5e-73ae-5c66-af8b-2099d3523455', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 19, 19, 'Yet there is both straw and provender for our donkeys; and there is bread and wine also for me, and for your handmaid, and for the young man who is with your servants: there is no want of anything."'),
  ('d08bc3c6-eecd-5054-a67a-4cf87ee7e59d', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 20, 20, 'The old man said, "Peace be to you; howsoever let all your wants lie on me; only don''t lodge in the street."'),
  ('6a876135-4332-50f8-ae79-8e5f22a55d4e', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 21, 21, 'So he brought him into his house, and gave the donkeys fodder; and they washed their feet, and ate and drink.'),
  ('b8708561-dd27-5ad4-ad13-795e24b8b020', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 22, 22, 'As they were making their hearts merry, behold, the men of the city, certain base fellows, surrounded the house, beating at the door; and they spoke to the master of the house, the old man, saying, "Bring out the man who came into your house, that we may have sex with him!"'),
  ('4582f15e-55c5-5681-a4b8-53ad1d2eca13', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 23, 23, 'The man, the master of the house, went out to them, and said to them, "No, my brothers, please don''t act so wickedly; since this man is come into my house, don''t do this folly.'),
  ('41edb654-3985-537d-a3b3-f21eb1c679d3', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 24, 24, 'Behold, here is my virgin daughter and his concubine. I will bring them out now. Humble them, and do with them what seems good to you; but to this man don''t do any such folly."'),
  ('b8efed52-df76-59c2-a4a1-4994a7bb51f4', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 25, 25, 'But the men wouldn''t listen to him: so the man laid hold of his concubine, and brought her out to them; and they had sex with her, and abused her all night until the morning: and when the day began to dawn, they let her go.'),
  ('32f0fb10-9fa2-5fb6-a713-4c5c9a2d704d', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 26, 26, 'Then came the woman in the dawning of the day, and fell down at the door of the man''s house where her lord was, until it was light.'),
  ('1737f337-91c4-545a-a5e4-69da7f654513', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 27, 27, 'Her lord rose up in the morning, and opened the doors of the house, and went out to go his way; and behold, the woman his concubine was fallen down at the door of the house, with her hands on the threshold.'),
  ('572a0838-50ec-5e2f-a6ec-10a8e06de184', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 28, 28, 'He said to her, "Get up, and let us be going!" but no one answered. Then he took her up on the donkey; and the man rose up, and went to his place.'),
  ('89f1ac90-c267-53a6-a864-55171945022a', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 29, 29, 'When he was come into his house, he took a knife, and laid hold on his concubine, and divided her, limb by limb, into twelve pieces, and sent her throughout all the borders of Israel.'),
  ('44804600-0e4e-51ce-a227-e1ebe789b3bc', '9270c5ad-4bf3-5383-a6d1-1266b4c6ce7b', NULL, 30, 30, 'It was so, that all who saw it said, "There was no such deed done nor seen from the day that the children of Israel came up out of the land of Egypt to this day! Consider it, take counsel, and speak."'),
  ('e8952301-aff6-512b-a8d3-19505c6f1d1d', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 1, 1, 'Then all the children of Israel went out, and the congregation was assembled as one man, from Dan even to Beersheba, with the land of Gilead, to Yahweh at Mizpah.'),
  ('eec825cb-9b4b-5471-a479-8994fbdcc802', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 2, 2, 'The chiefs of all the people, even of all the tribes of Israel, presented themselves in the assembly of the people of God, four hundred thousand footmen who drew sword.'),
  ('77043d8e-e929-5d7c-a3a8-5c16b4da4c7e', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 3, 3, '(Now the children of Benjamin heard that the children of Israel had gone up to Mizpah.) The children of Israel said, "Tell us, how did this wickedness happen?"'),
  ('0a730473-122e-5e4f-a723-99837bfd8a67', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 4, 4, 'The Levite, the husband of the woman who was murdered, answered, "I came into Gibeah that belongs to Benjamin, I and my concubine, to lodge.'),
  ('8a7906c0-a808-5fcc-a006-a4cf6c5fbf32', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 5, 5, 'The men of Gibeah rose against me, and surrounded the house by night. They thought to have slain me, and they forced my concubine, and she is dead.'),
  ('2e391e10-b768-5a36-a6e8-d3e26b5e5571', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 6, 6, 'I took my concubine, and cut her in pieces, and sent her throughout all the country of the inheritance of Israel; for they have committed lewdness and folly in Israel.'),
  ('2fd4246b-ee06-5ed0-ad6b-a4c691c7a497', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 7, 7, 'Behold, you children of Israel, all of you, give here your advice and counsel."'),
  ('25fba48c-b782-5b6b-a8cb-0d982eaefd06', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 8, 8, 'All the people arose as one man, saying, "We will not any of us go to his tent, neither will we any of us turn to his house.'),
  ('20866068-6468-5295-a3e3-11963c5ce0af', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 9, 9, 'But now this is the thing which we will do to Gibeah: [we will go up] against it by lot;'),
  ('99f40d0b-4204-5995-a6da-7b2aa57ea218', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 10, 10, 'and we will take ten men of one hundred throughout all the tribes of Israel, and one hundred of one thousand, and a thousand out of ten thousand, to get food for the people, that they may do, when they come to Gibeah of Benjamin, according to all the folly that they have worked in Israel."'),
  ('62b32d65-d474-55f5-aa54-fdaa1e3318d9', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 11, 11, 'So all the men of Israel were gathered against the city, knit together as one man.'),
  ('f679c5a7-5832-5893-a2a5-1dd0f7f56e90', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 12, 12, 'The tribes of Israel sent men through all the tribe of Benjamin, saying, "What wickedness is this that is happen among you?'),
  ('65af91d0-1dd6-54eb-ad96-6be5cc450f77', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 13, 13, 'Now therefore deliver up the men, the base fellows, who are in Gibeah, that we may put them to death, and put away evil from Israel." But Benjamin would not listen to the voice of their brothers the children of Israel.'),
  ('1919def6-0531-53fb-aafa-1caf8429c329', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 14, 14, 'The children of Benjamin gathered themselves together out of the cities to Gibeah, to go out to battle against the children of Israel.'),
  ('3f994be4-9e31-54d8-a627-54af40feba26', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 15, 15, 'The children of Benjamin were numbered on that day out of the cities twenty-six thousand men who drew the sword, besides the inhabitants of Gibeah, who were numbered seven hundred chosen men.'),
  ('64b5af4b-f2c3-5f87-a3ef-a0127129e16f', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 16, 16, 'Among all this people there were seven hundred chosen men left-handed; everyone could sling stones at a hair-breadth, and not miss.'),
  ('425e31bb-1d7d-5cd3-ad9e-f6629dba9bfc', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 17, 17, 'The men of Israel, besides Benjamin, were numbered four hundred thousand men who drew sword: all these were men of war.'),
  ('ba16ef3e-7ae7-52eb-af84-1404fa22ff63', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 18, 18, 'The children of Israel arose, and went up to Bethel, and asked counsel of God; and they said, "Who shall go up for us first to battle against the children of Benjamin?" Yahweh said, "Judah [shall go up] first."'),
  ('9b0b84e5-717d-57e0-a84c-57480d4a36a9', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 19, 19, 'The children of Israel rose up in the morning, and encamped against Gibeah.'),
  ('7ad17e1d-ce1e-5200-a292-89f04bdbee86', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 20, 20, 'The men of Israel went out to battle against Benjamin; and the men of Israel set the battle in array against them at Gibeah.'),
  ('91482c09-73a9-51d7-abc8-0cbc8201a5a8', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 21, 21, 'The children of Benjamin came forth out of Gibeah, and destroyed down to the ground of the Israelites on that day Twenty-two thousand men.'),
  ('e22c6da6-0a9a-5a84-a8d4-78213d1e2730', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 22, 22, 'The people, the men of Israel, encouraged themselves, and set the battle again in array in the place where they set themselves in array the first day.'),
  ('2fd948b7-40d8-5316-ae5b-3261ba691de9', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 23, 23, 'The children of Israel went up and wept before Yahweh until evening; and they asked of Yahweh, saying, "Shall I again draw near to battle against the children of Benjamin my brother?" Yahweh said, "Go up against him."'),
  ('2e59385d-1d49-557a-ac01-a80ce509af1a', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 24, 24, 'The children of Israel came near against the children of Benjamin the second day.'),
  ('c85193f2-a5df-5e90-abbe-201f02c64fc2', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 25, 25, 'Benjamin went forth against them out of Gibeah the second day, and destroyed down to the ground of the children of Israel again eighteen thousand men; all these drew the sword.'),
  ('770ee977-f4a6-5b26-a602-c3141cda7e25', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 26, 26, 'Then all the children of Israel, and all the people, went up, and came to Bethel, and wept, and sat there before Yahweh, and fasted that day until evening; and they offered burnt offerings and peace offerings before Yahweh.'),
  ('5c654ad2-1ca3-50a2-a551-0d25073526f7', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 27, 27, 'The children of Israel asked of Yahweh (for the ark of the covenant of God was there in those days,'),
  ('0ddbcfa7-509d-57f2-ab13-a3b5d17d22fa', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 28, 28, 'and Phinehas, the son of Eleazar, the son of Aaron, stood before it in those days), saying, "Shall I yet again go out to battle against the children of Benjamin my brother, or shall I cease?" Yahweh said, "Go up; for tomorrow I will deliver him into your hand."'),
  ('95de3e95-7203-5fea-a3d6-95b00a0c5f9c', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 29, 29, 'Israel set ambushes all around Gibeah.'),
  ('c193b299-12fc-5509-a615-4ecf37174acf', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 30, 30, 'The children of Israel went up against the children of Benjamin on the third day, and set themselves in array against Gibeah, as at other times.'),
  ('2b1087dc-e6e8-506b-a93e-b9a7eacc328c', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 31, 31, 'The children of Benjamin went out against the people, and were drawn away from the city; and they began to strike and kill of the people, as at other times, in the highways, of which one goes up to Bethel, and the other to Gibeah, in the field, about thirty men of Israel.'),
  ('45f5ba2a-b3b7-59a9-abdf-df194507f21d', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 32, 32, 'The children of Benjamin said, "They are struck down before us, as at the first." But the children of Israel said, "Let us flee, and draw them away from the city to the highways."'),
  ('8670e1db-b5fa-51dd-ac0c-230fb8467d6f', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 33, 33, 'All the men of Israel rose up out of their place, and set themselves in array at Baal Tamar: and the ambushers of Israel broke forth out of their place, even out of Maareh Geba.'),
  ('7ddc1c0a-457d-51d5-a965-27dcc813a1df', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 34, 34, 'There came over against Gibeah ten thousand chosen men out of all Israel, and the battle was severe; but they didn''t know that evil was close on them.'),
  ('a24677af-f60b-5146-a039-34fd7b87fc9c', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 35, 35, 'Yahweh struck Benjamin before Israel; and the children of Israel destroyed of Benjamin that day twenty-five thousand one hundred men: all these drew the sword.'),
  ('5343f103-ec22-5230-a249-2dbb9809f403', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 36, 36, 'So the children of Benjamin saw that they were struck; for the men of Israel gave place to Benjamin, because they trusted the ambushers whom they had set against Gibeah.'),
  ('e5076e6c-f7df-5afa-a286-c20d0a796a2a', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 37, 37, 'The ambushers hurried, and rushed on Gibeah; and the ambushers drew themselves along, and struck all the city with the edge of the sword.'),
  ('6e8c3626-0cdf-529b-afb1-7715a32308c7', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 38, 38, 'Now the appointed sign between the men of Israel and the ambushers was that they should make a great cloud of smoke rise up out of the city.'),
  ('041d8b50-885a-52f5-a34e-befbdd193fde', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 39, 39, 'The men of Israel turned in the battle, and Benjamin began to strike and kill of the men of Israel about thirty persons; for they said, "Surely they are struck down before us, as in the first battle."'),
  ('6c2044e3-731e-5d12-af6e-250f472d03e1', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 40, 40, 'But when the cloud began to arise up out of the city in a pillar of smoke, the Benjamites looked behind them; and behold, the whole of the city went up in smoke to the sky.'),
  ('b12a0219-093d-5f0b-aa1e-614cb97e49c3', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 41, 41, 'The men of Israel turned, and the men of Benjamin were dismayed; for they saw that evil had come on them.'),
  ('06871943-a23d-5603-ac0c-8315637dc5ce', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 42, 42, 'Therefore they turned their backs before the men of Israel to the way of the wilderness; but the battle followed hard after them; and those who came out of the cities destroyed them in its midst.'),
  ('ea333283-6863-5c39-a7c8-e240860c5e0f', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 43, 43, 'They surrounded the Benjamites, chased them, [and] trod them down at [their] resting place, as far as over against Gibeah toward the sunrise.'),
  ('3cac86b8-cd8f-5744-a1e3-40fd06e8b7cc', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 44, 44, 'There fell of Benjamin eighteen thousand men; all these [were] men of valor.'),
  ('bfd12254-fef8-56dd-a29b-32276f99c8f6', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 45, 45, 'They turned and fled toward the wilderness to the rock of Rimmon: and they gleaned of them in the highways five thousand men, and followed hard after them to Gidom, and struck of them two thousand men.'),
  ('41b43b3a-674f-5e42-ad8a-c1884c12fd45', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 46, 46, 'So that all who fell that day of Benjamin were twenty-five thousand men who drew the sword; all these [were] men of valor.'),
  ('d818c1df-e451-518c-ad55-82d8bb39c68a', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 47, 47, 'But six hundred men turned and fled toward the wilderness to the rock of Rimmon, and stayed in the rock of Rimmon four months.'),
  ('6597da37-2cce-5663-a13f-c73212e2213f', '07b12d24-f26b-5fdd-abf3-7d5779e820c5', NULL, 48, 48, 'The men of Israel turned again on the children of Benjamin, and struck them with the edge of the sword, both the entire city, and the livestock, and all that they found: moreover all the cities which they found they set on fire.'),
  ('891d2f1e-141a-59b5-afe0-0b11a993a23f', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 1, 1, 'Now the men of Israel had sworn in Mizpah, saying, "There shall not any of us give his daughter to Benjamin as wife."'),
  ('3244997f-c1b2-55e1-a0f0-f5294964219a', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 2, 2, 'The people came to Bethel, and sat there until evening before God, and lifted up their voices, and wept severely.'),
  ('be38c02c-4d2e-51b3-a9fa-475487649379', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 3, 3, 'They said, "Yahweh, the God of Israel, why has this happened in Israel, that there should be today one tribe lacking in Israel?"'),
  ('82206c8a-7f08-5a08-a613-5c0819536679', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 4, 4, 'It happened on the next day that the people rose early, and built there an altar, and offered burnt offerings and peace offerings.'),
  ('3f4be431-32e6-5986-acb5-cde59c3b9356', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 5, 5, 'The children of Israel said, "Who is there among all the tribes of Israel who didn''t come up in the assembly to Yahweh?" For they had made a great oath concerning him who didn''t come up to Yahweh to Mizpah, saying, "He shall surely be put to death."'),
  ('26d03fc7-4b16-576b-a2b6-510273c80590', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 6, 6, 'The children of Israel grieved for Benjamin their brother, and said, "There is one tribe cut off from Israel this day.'),
  ('3abcca00-d69f-58bc-abdf-89e138a2d51c', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 7, 7, 'How shall we provide wives for those who remain, since we have sworn by Yahweh that we will not give them of our daughters to wives?"'),
  ('1664e4e6-5438-56a7-a061-e706a7345e15', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 8, 8, 'They said, "What one is there of the tribes of Israel who didn''t come up to Yahweh to Mizpah?" Behold, there came none to the camp from Jabesh Gilead to the assembly.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('5d70e3ab-f39e-581f-aa94-664716222e3c', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 9, 9, 'For when the people were numbered, behold, there were none of the inhabitants of Jabesh Gilead there.'),
  ('7736d9c1-0d58-5bba-ae2f-14545ef6a215', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 10, 10, 'The congregation sent there twelve thousand men of the most valiant, and commanded them, saying, "Go and strike the inhabitants of Jabesh Gilead with the edge of the sword, with the women and the little ones.'),
  ('6949f479-88fa-5bba-a050-6aab5af7e21f', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 11, 11, 'This is the thing that you shall do: you shall utterly destroy every male, and every woman who has lain with a man."'),
  ('b16eae9d-e049-5cba-a329-36d029a2541f', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 12, 12, 'They found among the inhabitants of Jabesh Gilead four hundred young virgins, who had not known man by lying with him; and they brought them to the camp to Shiloh, which is in the land of Canaan.'),
  ('59d15463-4184-5778-a977-b25cf20af7cd', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 13, 13, 'The whole congregation sent and spoke to the children of Benjamin who were in the rock of Rimmon, and proclaimed peace to them.'),
  ('a366dc12-a348-5760-ab0f-26db6cff0cbd', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 14, 14, 'Benjamin returned at that time; and they gave them the women whom they had saved alive of the women of Jabesh Gilead: and yet so they weren''t enough for them.'),
  ('db659572-88e9-523d-ac78-d38a3d0c26d7', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 15, 15, 'The people grieved for Benjamin, because that Yahweh had made a breach in the tribes of Israel.'),
  ('7b973530-0c0b-5362-adf0-15e6f0cb3946', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 16, 16, 'Then the elders of the congregation said, "How shall we provide wives for those who remain, since the women are destroyed out of Benjamin?"'),
  ('0579ea45-be42-595b-af57-2144dabaff97', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 17, 17, 'They said, "There must be an inheritance for those who are escaped of Benjamin, that a tribe not be blotted out from Israel.'),
  ('caf14036-f090-5cb7-a2bf-4895867014b7', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 18, 18, 'However we may not give them wives of our daughters, for the children of Israel had sworn, saying, ''Cursed is he who gives a wife to Benjamin.''"'),
  ('5fdbb144-a4b6-5e41-a43c-4381626248dd', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 19, 19, 'They said, "Behold, there is a feast of Yahweh from year to year in Shiloh, which is on the north of Bethel, on the east side of the highway that goes up from Bethel to Shechem, and on the south of Lebonah."'),
  ('2e2ffbdf-6bcb-5df5-ae35-dd95407f9852', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 20, 20, 'They commanded the children of Benjamin, saying, "Go and lie in wait in the vineyards,'),
  ('d088157d-9f5d-5ea5-ae81-ca580b00efe2', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 21, 21, 'and see, and behold, if the daughters of Shiloh come out to dance in the dances, then come out of the vineyards, and each man catch his wife of the daughters of Shiloh, and go to the land of Benjamin.'),
  ('e3fc4541-842d-5d41-af00-2da42ea42bd4', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 22, 22, 'It shall be, when their fathers or their brothers come to complain to us, that we will say to them, ''Grant them graciously to us, because we didn''t take for each man his wife in battle, neither did you give them to them, otherwise you would now be guilty.''"'),
  ('614980e3-4ef1-5ebe-a2ff-aa8af89402c3', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 23, 23, 'The children of Benjamin did so, and took them wives, according to their number, of those who danced, whom they carried off. They went and returned to their inheritance, built the cities, and lived in them.'),
  ('35c26a86-3e1f-5cb2-a9b1-3dbf4f43c13b', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 24, 24, 'The children of Israel departed there at that time, every man to his tribe and to his family, and they went out from there every man to his inheritance.'),
  ('3bb1847d-be3c-500b-ad1c-c7ecc9b5498d', '144a9dfc-1414-5109-a3bd-d705e8c719ff', NULL, 25, 25, 'In those days there was no king in Israel: every man did that which was right in his own eyes.'),
  ('15176f7a-6ed8-5109-a27f-e884b045de91', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 1, 1, 'It happened in the days when the judges judged, that there was a famine in the land. A certain man of Bethlehem Judah went to live in the country of Moab, he, and his wife, and his two sons.'),
  ('5964d587-daad-5a85-a2a4-1b625904c26e', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 2, 2, 'The name of the man was Elimelech, and the name of his wife Naomi, and the name of his two sons Mahlon and Chilion, Ephrathites of Bethlehem Judah. They came into the country of Moab, and continued there.'),
  ('89bff202-ade2-5bc7-af46-0bcc4ff16b7a', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 3, 3, 'Elimelech, Naomi''s husband, died; and she was left, and her two sons.'),
  ('5b1268ba-cdd8-5fda-a4d3-7dc9035b4de9', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 4, 4, 'They took them wives of the women of Moab; the name of the one was Orpah, and the name of the other Ruth: and they lived there about ten years.'),
  ('2397830c-9e0b-5e8b-ab5e-35807bd5734f', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 5, 5, 'Mahlon and Chilion both died, and the woman was bereaved of her two children and of her husband.'),
  ('d6fe50e1-66c7-5f25-a37a-524aa0265b1a', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 6, 6, 'Then she arose with her daughters-in-law, that she might return from the country of Moab: for she had heard in the country of Moab how that Yahweh had visited his people in giving them bread.'),
  ('596fd740-4ed2-5457-a390-b608f7e8e9e1', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 7, 7, 'She went forth out of the place where she was, and her two daughters-in-law with her; and they went on the way to return to the land of Judah.'),
  ('6ecc46b1-f6df-5aef-af55-5cf97a61efcb', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 8, 8, 'Naomi said to her two daughters-in-law, "Go, return each of you to her mother''s house: Yahweh deal kindly with you, as you have dealt with the dead, and with me.'),
  ('5c8bd8a8-df28-5570-a738-e6f64c5d6cb2', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 9, 9, 'Yahweh grant you that you may find rest, each of you in the house of her husband." Then she kissed them, and they lifted up their voice, and wept.'),
  ('217f4be9-307a-57c9-a3c4-efd1b5a701a4', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 10, 10, 'They said to her, "No, but we will return with you to your people."'),
  ('a788fd5e-42d5-55b9-ae02-c012b6159ac4', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 11, 11, 'Naomi said, "Go back, my daughters. Why do you want to go with me? Do I still have sons in my womb, that they may be your husbands?'),
  ('14dcf64c-31f3-58f6-a1ef-0e5c4010b10e', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 12, 12, 'Go back, my daughters, go your way; for I am too old to have a husband. If I should say, ''I have hope,'' if I should even have a husband tonight, and should also bear sons;'),
  ('e1208107-a4b3-5abe-ad86-e15c6b4e0488', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 13, 13, 'would you then wait until they were grown? Would you then refrain from having husbands? No, my daughters, for it grieves me much for your sakes, for the hand of Yahweh has gone out against me."'),
  ('551ca5eb-999a-56fd-a131-1baa38933e25', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 14, 14, 'They lifted up their voice, and wept again: and Orpah kissed her mother-in-law, but Ruth joined with her.'),
  ('eece5a6d-f5d1-5e21-a4dc-92b41ff82a3d', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 15, 15, 'She said, "Behold, your sister-in-law has gone back to her people, and to her god. Follow your sister-in-law."'),
  ('9825b008-e06c-5d7f-a628-836bd0925ca3', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 16, 16, 'Ruth said, "Don''t entreat me to leave you, and to return from following after you, for where you go, I will go; and where you lodge, I will lodge; your people shall be my people, and your God my God;'),
  ('bf84303c-5360-55f2-aab1-a4d42aa0bdf4', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 17, 17, 'where you die, will I die, and there will I be buried. Yahweh do so to me, and more also, if anything but death part you and me."'),
  ('154bf38f-e246-5e7f-a124-376d3a51ee49', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 18, 18, 'When she saw that she was steadfastly minded to go with her, she left off speaking to her.'),
  ('393ba632-d8ee-5a4e-ad72-5c9ade2fe900', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 19, 19, 'So they two went until they came to Bethlehem. It happened, when they were come to Bethlehem, that all the city was moved about them, and [the women] said, "Is this Naomi?"'),
  ('645805c2-c25d-58a1-a799-171265bef9d7', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 20, 20, 'She said to them, "Don''t call me Naomi. Call me Mara; for the Almighty has dealt very bitterly with me.'),
  ('dd663f65-71e1-55d1-a831-e2f51ed2a2a5', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 21, 21, 'I went out full, and Yahweh has brought me home again empty; why do you call me Naomi, since Yahweh has testified against me, and the Almighty has afflicted me?"'),
  ('312f3a46-65c3-5531-ac1f-3c399c54fa8f', '0e707ffe-477f-5f43-a506-eddb397a78d5', NULL, 22, 22, 'So Naomi returned, and Ruth the Moabitess, her daughter-in-law, with her, who returned out of the country of Moab: and they came to Bethlehem in the beginning of barley harvest.'),
  ('5142c6b0-a527-55b8-a12a-de20cc784ae1', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 1, 1, 'Naomi had a kinsman of her husband''s, a mighty man of wealth, of the family of Elimelech, and his name was Boaz.'),
  ('83df9cb1-8f28-5ac3-a026-722e32dc859c', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 2, 2, 'Ruth the Moabitess said to Naomi, "Let me now go to the field, and glean among the ears of grain after him in whose sight I shall find favor." She said to her, "Go, my daughter."'),
  ('4fd1a7e9-0a91-5f11-ad92-e313463b8690', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 3, 3, 'She went, and came and gleaned in the field after the reapers: and she happened to come to the portion of the field belonging to Boaz, who was of the family of Elimelech.'),
  ('44aabce2-d4e0-5306-aad7-ede1f8766fda', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 4, 4, 'Behold, Boaz came from Bethlehem, and said to the reapers, "Yahweh be with you." They answered him, "Yahweh bless you."'),
  ('73e6c626-7481-5873-ad71-23632d4ab5ba', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 5, 5, 'Then Boaz said to his servant who was set over the reapers, "Whose young lady is this?"'),
  ('37ff1d25-cd5b-556b-a7d0-03f3ba0b5d94', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 6, 6, 'The servant who was set over the reapers answered, "It is the Moabite lady who came back with Naomi out of the country of Moab.'),
  ('852925e9-8f1a-5ad9-a979-26dcb0f1c37e', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 7, 7, 'She said, ''Please let me glean and gather after the reapers among the sheaves.'' So she came, and has continued even from the morning until now, except that she stayed a little in the house."'),
  ('2fa6cc54-0e5b-54c5-a9cc-d99ed618955a', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 8, 8, 'Then Boaz said to Ruth, "Listen, my daughter. Don''t go to glean in another field, and don''t go from here, but stay here close to my maidens.'),
  ('2de42484-e83c-5f3d-ae0e-2aa0a8e1ecd4', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 9, 9, 'Let your eyes be on the field that they reap, and go after them. Haven''t I commanded the young men not to touch you? When you are thirsty, go to the vessels, and drink from that which the young men have drawn."'),
  ('2e842ead-fe48-5d10-adc3-dbb9a7c84bbd', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 10, 10, 'Then she fell on her face, and bowed herself to the ground, and said to him, "Why have I found favor in your sight, that you should take knowledge of me, since I am a foreigner?"'),
  ('aae48ff1-a3ea-588f-afc4-19ab66818b9e', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 11, 11, 'Boaz answered her, "It has fully been shown me, all that you have done to your mother-in-law since the death of your husband; and how you have left your father and your mother, and the land of your birth, and have come to a people that you didn''t know before.'),
  ('26671040-4233-57b3-a771-db3904da61cc', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 12, 12, 'May Yahweh repay your work, and a full reward be given you from Yahweh, the God of Israel, under whose wings you have come to take refuge."'),
  ('9df93e4f-b259-5929-adce-6f5b7d54f88b', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 13, 13, 'Then she said, "Let me find favor in your sight, my lord, because you have comforted me, and because you have spoken kindly to your handmaid, though I am not as one of your handmaidens."'),
  ('fe3a1865-e042-54d3-a798-2dfca68a09cd', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 14, 14, 'At meal time Boaz said to her, "Come here, and eat of the bread, and dip your morsel in the vinegar." She sat beside the reapers, and they reached her parched grain, and she ate, and was satisfied, and left some of it.'),
  ('63c0b5c0-150b-59bd-af5e-cf10431dea73', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 15, 15, 'When she had risen up to glean, Boaz commanded his young men, saying, "Let her glean even among the sheaves, and don''t reproach her.'),
  ('b9c24ca4-0c18-55a5-a7b5-c24e76b78de5', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 16, 16, 'Also pull out some for her from the bundles, and leave it, and let her glean, and don''t rebuke her."'),
  ('b827cd49-20bd-5020-a3cc-7ea4aa7c0347', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 17, 17, 'So she gleaned in the field until evening; and she beat out that which she had gleaned, and it was about an ephah of barley.'),
  ('25bec552-dc68-55f7-ae1f-bdc667650dbb', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 18, 18, 'She took it up, and went into the city; and her mother-in-law saw what she had gleaned: and she brought forth and gave to her that which she had left after she was sufficed.'),
  ('007de232-445d-56d3-acb9-a6fc646e4de7', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 19, 19, 'Her mother-in-law said to her, "Where have you gleaned today? Where have you worked? Blessed be he who noticed you." She showed her mother-in-law with whom she had worked, and said, "The man''s name with whom I worked today is Boaz."'),
  ('1c07e41b-066f-590d-a7a8-9a5157216933', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 20, 20, 'Naomi said to her daughter-in-law, "Blessed be he of Yahweh, who has not left off his kindness to the living and to the dead." Naomi said to her, "The man is a close relative to us, one of our near kinsmen."'),
  ('c1a1c41f-53fb-5455-a94c-652238e32134', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 21, 21, 'Ruth the Moabitess said, "Yes, he said to me, ''You shall stay close to my young men, until they have ended all my harvest.''"'),
  ('c781ce8f-adde-5d45-ab94-29929cdb23e6', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 22, 22, 'Naomi said to Ruth her daughter-in-law, "It is good, my daughter, that you go out with his maidens, and that they not meet you in any other field."'),
  ('02d546b3-d321-527a-a631-8255a01afd8e', '612dcd0a-470a-504d-a750-f30f956e38b9', NULL, 23, 23, 'So she stayed close to the maidens of Boaz, to glean to the end of barley harvest and of wheat harvest; and she lived with her mother-in-law.'),
  ('5a43872f-8928-5cc6-ad5d-d8635d9fe1b8', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 1, 1, 'Naomi her mother-in-law said to her, "My daughter, shall I not seek rest for you, that it may be well with you?'),
  ('a867412c-34e0-5765-a80e-bf62ea726f01', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 2, 2, 'Now isn''t Boaz our kinsman, with whose maidens you were? Behold, he winnows barley tonight in the threshing floor.'),
  ('94996964-aa41-5936-ab57-4c6a39bbffbf', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 3, 3, 'Therefore wash yourself, anoint yourself, get dressed, and go down to the threshing floor, but don''t make yourself known to the man until he has finished eating and drinking.'),
  ('0ff04b1d-9aae-5b40-a64e-e0a34c805b96', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 4, 4, 'It shall be, when he lies down, that you shall mark the place where he shall lie, and you shall go in, and uncover his feet, and lay down; then he will tell you what you shall do."'),
  ('d0af746e-9e45-5e0c-a000-713e43f09c14', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 5, 5, 'She said to her, "All that you say I will do."'),
  ('c0cd5c9d-1e0b-5168-acfa-1ade3be4d558', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 6, 6, 'She went down to the threshing floor, and did according to all that her mother-in-law told her.'),
  ('3727b9d5-3881-5f35-af57-78d4d80fdb25', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 7, 7, 'When Boaz had eaten and drunk, and his heart was merry, he went to lie down at the end of the heap of grain. She came softly, uncovered his feet, and laid her down.'),
  ('7ce816de-b166-56dd-a56f-5eaba61e0a53', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 8, 8, 'It happened at midnight, that the man was startled and turned himself; and behold, a woman lay at his feet.'),
  ('ef6d62f8-38ed-572f-ab59-6e2ad9923cb5', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 9, 9, 'He said, "Who are you?" She answered, "I am Ruth your handmaid. Therefore spread your skirt over your handmaid; for you are a near kinsman."'),
  ('43e002e3-d3f7-5e4f-ac6c-c4f51460e9d0', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 10, 10, 'He said, "Blessed are you by Yahweh, my daughter. You have shown more kindness in the latter end than at the beginning, inasmuch as you didn''t follow young men, whether poor or rich.'),
  ('a24662c6-fb4b-5ca7-a1ae-0ee28fde6bf1', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 11, 11, 'Now, my daughter, don''t be afraid; I will do to you all that you say; for all the city of my people does know that you are a worthy woman.'),
  ('35b5c315-1628-5c9f-a3b9-c29417ceb487', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 12, 12, 'Now it is true that I am a near kinsman; however there is a kinsman nearer than I.'),
  ('6ab4b414-85bd-53e4-a586-78b2e9d9e536', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 13, 13, 'Stay this night, and it shall be in the morning, that if he will perform for you the part of a kinsman, well; let him do the kinsman''s part. But if he will not do the part of a kinsman for you, then will I do the part of a kinsman for you, as Yahweh lives. Lie down until the morning."'),
  ('b50dce08-efe3-5a8d-a984-7892a5912e3c', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 14, 14, 'She lay at his feet until the morning. She rose up before one could discern another. For he said, "Let it not be known that the woman came to the threshing floor."'),
  ('8e4c86c3-d55b-52ec-ae15-90d3f93a8ba6', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 15, 15, 'He said, "Bring the mantle that is on you, and hold it." She held it; and he measured six [measures] of barley, and laid it on her; and he went into the city.'),
  ('a2bc5342-87ba-57ce-a314-91ad8037e89b', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 16, 16, 'When she came to her mother-in-law, she said, "How did it go, my daughter?" She told her all that the man had done to her.'),
  ('35604240-c811-5d04-afd3-68b3c4deb363', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 17, 17, 'She said, "He gave me these six [measures] of barley; for he said, ''Don''t go empty to your mother-in-law.''"'),
  ('fad45147-1cde-59fe-ad58-4366678d82a3', 'd7cfd879-136e-56c2-a0e3-5b253460b6c2', NULL, 18, 18, 'Then she said, "Sit still, my daughter, until you know how the matter will fall; for the man will not rest, until he has finished the thing this day."'),
  ('0c1be401-e4cd-509d-ae18-7761c70c80ff', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 1, 1, 'Now Boaz went up to the gate, and sat down there. Behold, the near kinsman of whom Boaz spoke came by; to whom he said, "Come over here, friend, and sit down!" He turned aside, and sat down.'),
  ('cf35446c-8d40-5b65-a03d-c543301e88b6', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 2, 2, 'He took ten men of the elders of the city, and said, "Sit down here." They sat down.'),
  ('69c7083c-f587-5f8b-a05e-7f39d59a36de', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 3, 3, 'He said to the near kinsman, "Naomi, who has come back out of the country of Moab, is selling the parcel of land, which was our brother Elimelech''s.'),
  ('b55443ac-9a7f-50ab-a028-fc0c2bb32bb4', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 4, 4, 'I thought to disclose it to you, saying, ''Buy it before those who sit here, and before the elders of my people.'' If you will redeem it, redeem it; but if you will not redeem it, then tell me, that I may know. For there is no one to redeem it besides you; and I am after you." He said, "I will redeem it."'),
  ('a332bbad-cc1e-5a18-a74a-1786add98d67', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 5, 5, 'Then Boaz said, "On the day you buy the field from the hand of Naomi, you must buy it also from Ruth the Moabitess, the wife of the dead, to raise up the name of the dead on his inheritance."'),
  ('d818c1cc-dcbd-5d5d-a9d0-04d8d7ff5ff4', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 6, 6, 'The near kinsman said, "I can''t redeem it for myself, lest I mar my own inheritance. Take my right of redemption for yourself; for I can''t redeem it."'),
  ('8cb885b0-70fd-557d-aba6-84b7c9d9ec91', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 7, 7, 'Now this was [the custom] in former time in Israel concerning redeeming and concerning exchanging, to confirm all things: a man took off his shoe, and gave it to his neighbor; and this was the [way of] attestation in Israel.'),
  ('d9f9f2db-90b4-5930-a8d5-b524bd20481a', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 8, 8, 'So the near kinsman said to Boaz, "Buy it for yourself." He took off his shoe.'),
  ('9c803a08-4bd8-5015-ad1a-77adc98afce0', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 9, 9, 'Boaz said to the elders, and to all the people, "You are witnesses this day, that I have bought all that was Elimelech''s, and all that was Chilion''s and Mahlon''s, from the hand of Naomi.'),
  ('04f86169-ecf2-5655-acd3-3e2f020d8160', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 10, 10, 'Moreover Ruth the Moabitess, the wife of Mahlon, I have purchased to be my wife, to raise up the name of the dead on his inheritance, that the name of the dead not be cut off from among his brothers, and from the gate of his place. You are witnesses this day."'),
  ('98c1df07-739e-5b1e-a3e6-9f86ff79b69a', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 11, 11, 'All the people who were in the gate, and the elders, said, "We are witnesses. May Yahweh make the woman who has come into your house like Rachel and like Leah, which two built the house of Israel; and treat you worthily in Ephrathah, and be famous in Bethlehem.'),
  ('cde5a790-b845-50d9-aa95-07019c3a41da', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 12, 12, 'Let your house be like the house of Perez, whom Tamar bore to Judah, of the seed which Yahweh shall give you of this young woman."'),
  ('75d72fff-303b-59ae-a3ba-b93761bb8646', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 13, 13, 'So Boaz took Ruth, and she became his wife; and he went in to her, and Yahweh gave her conception, and she bore a son.'),
  ('d1e7860b-dedc-5ac6-a5ef-d5c3a64c79fa', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 14, 14, 'The women said to Naomi, "Blessed be Yahweh, who has not left you this day without a near kinsman; and let his name be famous in Israel.'),
  ('b7c44a45-961c-5cc0-ac6f-c3fe78a527c5', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 15, 15, 'He shall be to you a restorer of life, and sustain you in your old age, for your daughter-in-law, who loves you, who is better to you than seven sons, has borne him."'),
  ('cf305e88-e86f-521e-a79e-b021885e0b5f', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 16, 16, 'Naomi took the child, and laid it in her bosom, and became nurse to it.'),
  ('46b2c71e-72e4-51a2-a9dd-b00520f524b5', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 17, 17, 'The women, her neighbors, gave him a name, saying, "There is a son born to Naomi;" and they named him Obed. He is the father of Jesse, the father of David.'),
  ('422979a0-a29c-52d5-aa4b-acc0d3d73293', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 18, 18, 'Now this is the history of the generations of Perez: Perez became the father of Hezron,'),
  ('0249f26c-4d42-5d4e-a3c9-b638ed1d3d0c', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 19, 19, 'and Hezron became the father of Ram, and Ram became the father of Amminadab,'),
  ('991c1443-d7d5-5bc1-a868-2f7ee0b9b97c', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 20, 20, 'and Amminadab became the father of Nahshon, and Nahshon became the father of Salmon,'),
  ('55d3bb30-3d22-51f5-ae6c-d9c91ec3d72c', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 21, 21, 'and Salmon became the father of Boaz, and Boaz became the father of Obed,'),
  ('da2db625-a4cd-5129-aafa-3a5a5c030e43', '108175e6-2b0d-5694-a688-f34da6cc0a0c', NULL, 22, 22, 'and Obed became the father of Jesse, and Jesse became the father of David.'),
  ('3569fc17-b51d-5adc-ad24-4014c5b65f05', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 1, 1, 'Now there was a certain man of Ramathaim Zophim, of the hill country of Ephraim, and his name was Elkanah, the son of Jeroham, the son of Elihu, the son of Tohu, the son of Zuph, an Ephraimite:'),
  ('3b49a00c-5a7b-57bc-ad05-7bf6c23c3c53', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 2, 2, 'and he had two wives; the name of the one was Hannah, and the name of other Peninnah: and Peninnah had children, but Hannah had no children.'),
  ('d586c880-b09c-5da6-a7bc-5d28dd0126a8', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 3, 3, 'This man went up out of his city from year to year to worship and to sacrifice to Yahweh of Armies in Shiloh. The two sons of Eli, Hophni and Phinehas, priests to Yahweh, were there.'),
  ('d46b34cf-e16d-5197-a637-45f252145914', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 4, 4, 'When the day came that Elkanah sacrificed, he gave to Peninnah his wife, and to all her sons and her daughters, portions:'),
  ('d05b23ea-de40-5d92-aed2-f918edb27618', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 5, 5, 'but to Hannah he gave a double portion; for he loved Hannah, but Yahweh had shut up her womb.'),
  ('7262f8ac-957b-5b40-ad38-32dbe6a6640a', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 6, 6, 'Her rival provoked her severely, to make her fret, because Yahweh had shut up her womb.'),
  ('a233e8ed-e451-5b69-a817-2466d3bab74f', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 7, 7, '[as] he did so year by year, when she went up to the house of Yahweh, so she provoked her; therefore she wept, and did not eat.'),
  ('c33ca98c-565a-59ca-a6f5-362ff713d32a', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 8, 8, 'Elkanah her husband said to her, "Hannah, why do you weep? Why don''t you eat? Why is your heart grieved? Am I not better to you than ten sons?"'),
  ('bc977d58-d708-5454-aa4b-49cc130c670f', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 9, 9, 'So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest was sitting on his seat by the doorpost of the temple of Yahweh.'),
  ('38675fb5-0d5c-5d8c-aeef-e82aa302887e', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 10, 10, 'She was in bitterness of soul, and prayed to Yahweh, and wept bitterly.'),
  ('4f066596-2fd2-55e9-a6e2-a953b20f141a', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 11, 11, 'She vowed a vow, and said, "Yahweh of Armies, if you will indeed look on the affliction of your handmaid, and remember me, and not forget your handmaid, but will give to your handmaid a boy, then I will give him to Yahweh all the days of his life, and no razor shall come on his head."'),
  ('d54038d9-9b14-560e-ac4e-813d37b98e8b', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 12, 12, 'It happened, as she continued praying before Yahweh, that Eli saw her mouth.'),
  ('458b997e-a568-55c6-ae40-9b0e1892b904', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 13, 13, 'Now Hannah spoke in her heart. Only her lips moved, but her voice was not heard. Therefore Eli thought she had been drunken.'),
  ('f175f7e6-7c4d-5d81-a83f-8b6ccd9d7062', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 14, 14, 'Eli said to her, "How long will you be drunken? Put away your wine from you."'),
  ('73950f36-1181-51e5-ad82-8a9fef18b65d', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 15, 15, 'Hannah answered, "No, my lord, I am a woman of a sorrowful spirit. I have drunk neither wine nor strong drink, but I poured out my soul before Yahweh.'),
  ('f6fdd220-9b48-580f-ab6b-54ca2cad275e', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 16, 16, 'Don''t count your handmaid for a wicked woman; for I have been speaking out of the abundance of my complaint and my provocation."'),
  ('ee722127-0af8-5c8b-a5ac-6b1ac215439f', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 17, 17, 'Then Eli answered, "Go in peace; and may the God of Israel grant your petition that you have asked of him."'),
  ('caa8c695-c19a-5dc6-a9b9-c132c219871e', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 18, 18, 'She said, "Let your handmaid find favor in your sight." So the woman went her way, and ate; and her facial expression wasn''t sad any more.'),
  ('1abf750e-ba1b-5680-a774-83b89f2bbffd', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 19, 19, 'They rose up in the morning early, and worshiped before Yahweh, and returned, and came to their house to Ramah: and Elkanah knew Hannah his wife; and Yahweh remembered her.'),
  ('93bbc4fd-1f35-5cd9-a292-ed85f93b0b87', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 20, 20, 'It happened, when the time had come, that Hannah conceived, and bore a son; and she named him Samuel, [saying], "Because I have asked him of Yahweh."'),
  ('03b5e8d3-0579-549c-a0ea-0deafff29487', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 21, 21, 'The man Elkanah, and all his house, went up to offer to Yahweh the yearly sacrifice, and his vow.'),
  ('6c5391b8-8686-5e7b-af39-6c53b6af0f40', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 22, 22, 'But Hannah didn''t go up; for she said to her husband, "Not until the child is weaned; then I will bring him, that he may appear before Yahweh, and stay there forever."'),
  ('ffd4f186-ccf4-5928-a7c3-5025b3dcee2b', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 23, 23, 'Elkanah her husband said to her, "Do what seems good to you. Wait until you have weaned him; only may Yahweh establish his word." So the woman waited and nursed her son, until she weaned him.'),
  ('bb79c508-17f1-5b0b-a99e-9a4370d96be8', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 24, 24, 'When she had weaned him, she took him up with her, with three bulls, and one ephah of meal, and a bottle of wine, and brought him to Yahweh''s house in Shiloh. The child was young.'),
  ('56525abd-3e23-5dd8-a635-1c2c828bf3ce', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 25, 25, 'They killed the bull, and brought the child to Eli.'),
  ('76eea009-90ae-5d8a-abce-704f15b8996d', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 26, 26, 'She said, "Oh, my lord, as your soul lives, my lord, I am the woman who stood by you here, praying to Yahweh.'),
  ('1fd49dac-f4e8-58fe-ae2c-0a15a6f0ebdd', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 27, 27, 'For this child I prayed; and Yahweh has given me my petition which I asked of him.'),
  ('0e2378bc-fcec-5f87-a865-3c8489851c3f', '8feda52b-e579-50b9-a046-b86a6c2a47aa', NULL, 28, 28, 'Therefore also I have granted him to Yahweh. As long as he lives he is granted to Yahweh." He worshiped Yahweh there.'),
  ('5cfb98e5-4a6f-5e4d-a4f1-722774c7d6ad', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 1, 1, 'Hannah prayed, and said: "My heart exults in Yahweh! My horn is exalted in Yahweh. My mouth is enlarged over my enemies, because I rejoice in your salvation.'),
  ('78bfd4de-7a85-5b9f-a7d8-9ec5f2bedca4', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 2, 2, 'There is no one as holy as Yahweh, For there is no one besides you, nor is there any rock like our God.'),
  ('7b52328e-87ae-50b6-a4d6-914c065bfaa7', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 3, 3, '"Talk no more so exceeding proudly. Don''t let arrogance come out of your mouth, For Yahweh is a God of knowledge. By him actions are weighed.'),
  ('6d4b3509-3373-5d8a-a693-b408fce46caf', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 4, 4, '"The bows of the mighty men are broken. Those who stumbled are armed with strength.'),
  ('8be90325-fd08-5804-a720-462ce44026b2', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 5, 5, 'Those who were full have hired themselves out for bread. Those who were hungry have ceased [to hunger]. Yes, the barren has borne seven. She who has many children languishes.'),
  ('fd1629d5-7cd3-544f-a8d7-86357e196d63', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 6, 6, '"Yahweh kills, and makes alive. He brings down to Sheol, and brings up.'),
  ('8efd2d98-16b8-50f6-ab42-9ee0695fc1b7', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 7, 7, 'Yahweh makes poor, and makes rich. He brings low, he also lifts up.'),
  ('7f3a88e5-8e78-5408-a610-2ddb872f0ba8', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 8, 8, 'He raises up the poor out of the dust. He lifts up the needy from the dunghill, To make them sit with princes, and inherit the throne of glory. For the pillars of the earth are Yahweh''s. He has set the world on them.'),
  ('05d01d1a-3089-54ff-a5aa-6dad7975b685', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 9, 9, 'He will keep the feet of his holy ones, but the wicked shall be put to silence in darkness; for no man shall prevail by strength.'),
  ('5f3ee007-b314-5e05-ac36-09392b79a83e', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 10, 10, 'Those who strive with Yahweh shall be broken to pieces. He will thunder against them in the sky. "Yahweh will judge the ends of the earth. He will give strength to his king, and exalt the horn of his anointed."'),
  ('903987e8-a4cc-53d0-a224-326ae904bbce', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 11, 11, 'Elkanah went to Ramah to his house. The child did minister to Yahweh before Eli the priest.'),
  ('e9074ca1-4a99-5b35-a914-42ef98aff7f6', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 12, 12, 'Now the sons of Eli were base men; they didn''t know Yahweh.'),
  ('3683c1e2-5d71-5adb-a25e-7950bf4929b5', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 13, 13, 'The custom of the priests with the people was that when any man offered sacrifice, the priest''s servant came, while the flesh was boiling, with a fork of three teeth in his hand;'),
  ('b05ef040-7251-55d1-a4c2-9ba3f45c6ceb', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 14, 14, 'and he struck it into the pan, or kettle, or caldron, or pot; all that the fork brought up the priest took therewith. So they did in Shiloh to all the Israelites who came there.'),
  ('7505776e-2206-528a-a801-9be1986b2520', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 15, 15, 'Yes, before they burnt the fat, the priest''s servant came, and said to the man who sacrificed, "Give meat to roast for the priest; for he will not accept boiled meat from you, but raw."'),
  ('147f161c-c08a-502a-ab85-a8cb356bc4f7', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 16, 16, 'If the man said to him, "Let the fat be burned first, and then take as much as your soul desires;" then he would say, "No, but you shall give it to me now; and if not, I will take it by force."'),
  ('0eed8018-aaf2-55c0-a40a-c90fef48a18c', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 17, 17, 'The sin of the young men was very great before Yahweh; for the men despised the offering of Yahweh.'),
  ('96688c85-b458-56ff-a258-59e7353b8baf', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 18, 18, 'But Samuel ministered before Yahweh, being a child, clothed with a linen ephod.'),
  ('16cf34d6-9f11-5ce5-ae45-a00840d0d43f', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 19, 19, 'Moreover his mother made him a little robe, and brought it to him from year to year, when she came up with her husband to offer the yearly sacrifice.'),
  ('e371cfc3-2805-5376-a7f3-6e3822c6f8e7', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 20, 20, 'Eli blessed Elkanah and his wife, and said, "Yahweh give you seed of this woman for the petition which was asked of Yahweh." They went to their own home.'),
  ('1c18f334-32e5-58d7-acd8-712fd35c8ff8', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 21, 21, 'Yahweh visited Hannah, and she conceived, and bore three sons and two daughters. The child Samuel grew before Yahweh.'),
  ('e5287573-20de-5219-a3f8-3d06627b0c98', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 22, 22, 'Now Eli was very old; and he heard all that his sons did to all Israel, and how that they lay with the women who served at the door of the Tent of Meeting.'),
  ('8ca8d862-654c-5e38-a8f8-29e590d8af74', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 23, 23, 'He said to them, "Why do you do such things? for I hear of your evil dealings from all this people.'),
  ('e848a10b-e0ff-549f-a891-bd4c9bcb907a', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 24, 24, 'No, my sons; for it is no good report that I hear: you make Yahweh''s people disobey.'),
  ('353e3c1e-1bcc-539b-a0f9-5ed22533b15e', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 25, 25, 'If one man sin against another, God shall judge him; but if a man sin against Yahweh, who shall entreat for him?" Notwithstanding, they didn''t listen to the voice of their father, because Yahweh was minded to kill them.'),
  ('0622ea9b-9828-5853-a921-309037ae3bd6', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 26, 26, 'The child Samuel grew on, and increased in favor both with Yahweh, and also with men.'),
  ('03bdefea-9d75-562a-aeab-c8e49ba58578', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 27, 27, 'A man of God came to Eli, and said to him, "Thus says Yahweh, ''Did I reveal myself to the house of your father, when they were in Egypt [in bondage] to Pharaoh''s house?'),
  ('d51cfe33-cf8c-5f2c-aef3-505cece52798', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 28, 28, 'Did I choose him out of all the tribes of Israel to be my priest, to go up to my altar, to burn incense, to wear an ephod before me? Did I give to the house of your father all the offerings of the children of Israel made by fire?'),
  ('4d3fa42d-439f-50a3-af10-1c00d756615a', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 29, 29, 'Why do you kick at my sacrifice and at my offering, which I have commanded in [my] habitation, and honor your sons above me, to make yourselves fat with the best of all the offerings of Israel my people?'''),
  ('4a57be0a-9bfe-55ea-ae99-fdca1d5acc43', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 30, 30, '"Therefore Yahweh, the God of Israel, says, ''I said indeed that your house, and the house of your father, should walk before me forever.'' But now Yahweh says, ''Be it far from me; for those who honor me I will honor, and those who despise me shall be lightly esteemed.'),
  ('c9894336-534e-506b-aa94-757ea008c04a', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 31, 31, 'Behold, the days come, that I will cut off your arm, and the arm of your father''s house, that there shall not be an old man in your house.'),
  ('d2e58a55-b80d-5a5a-abb7-bcd4b297e437', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 32, 32, 'You shall see the affliction of [my] habitation, in all the wealth which [God] shall give Israel; and there shall not be an old man in your house forever.'),
  ('b14baf7b-6379-519c-a82e-fa591e84a88f', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 33, 33, 'The man of yours, [whom] I shall not cut off from my altar, [shall be] to consume your eyes, and to grieve your heart; and all the increase of your house shall die in the flower of their age.'),
  ('d3a1f6d3-be39-5ba8-aad7-1874c3de6a0d', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 34, 34, '"''This shall be the sign to you, that shall come on your two sons, on Hophni and Phinehas: in one day they shall both die.'),
  ('eaef8c4f-e923-509c-a8ba-801af307cf35', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 35, 35, 'I will raise me up a faithful priest, that shall do according to that which is in my heart and in my mind. I will build him a sure house; and he shall walk before my anointed forever.'),
  ('5834842f-c4db-5017-a2b0-7859776c3c3f', 'bfb218ba-a248-53a2-a036-6a21ab23dc70', NULL, 36, 36, 'It shall happen, that everyone who is left in your house shall come and bow down to him for a piece of silver and a loaf of bread, and shall say, "Please put me into one of the priests'' offices, that I may eat a morsel of bread."''"'),
  ('5f291022-d8a3-558a-ac7b-a62b8e8784ea', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 1, 1, 'The child Samuel ministered to Yahweh before Eli. The word of Yahweh was precious in those days; there was no frequent vision.'),
  ('9627af3a-7d4f-5342-a33b-ab0ce757e8a8', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 2, 2, 'It happened at that time, when Eli was laid down in his place (now his eyes had begun to grow dim, so that he could not see),'),
  ('f0abdedf-5f11-5c3d-ab0c-efb3e588688d', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 3, 3, 'and the lamp of God hadn''t yet gone out, and Samuel had laid down [to sleep], in the temple of Yahweh, where the ark of God was;'),
  ('8b8e94dd-7ffb-599e-ae54-5b5409bedeb7', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 4, 4, 'that Yahweh called Samuel; and he said, "Here I am."'),
  ('d428210f-7efc-5a37-aac2-ad018aed0f12', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 5, 5, 'He ran to Eli, and said, "Here I am; for you called me." He said, "I didn''t call; lie down again." He went and lay down.'),
  ('a3036836-f8f6-5ab6-a3b7-bb07fded4d52', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 6, 6, 'Yahweh called yet again, "Samuel!" Samuel arose and went to Eli, and said, "Here I am; for you called me." He answered, "I didn''t call, my son; lie down again."'),
  ('48f794d0-3c54-5a29-a5aa-a2194eb7aa61', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 7, 7, 'Now Samuel didn''t yet know Yahweh, neither was the word of Yahweh yet revealed to him.'),
  ('43e4a418-a0d7-5fb9-a250-4f59ea046c83', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 8, 8, 'Yahweh called Samuel again the third time. He arose and went to Eli, and said, "Here I am; for you called me." Eli perceived that Yahweh had called the child.'),
  ('da8fa53d-4bdc-577b-af2b-e37d81d473c0', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 9, 9, 'Therefore Eli said to Samuel, "Go, lie down: and it shall be, if he calls you, that you shall say, ''Speak, Yahweh; for your servant hears.''" So Samuel went and lay down in his place.'),
  ('08051bca-0ba6-5de2-a139-02464e1be3b9', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 10, 10, 'Yahweh came, and stood, and called as at other times, "Samuel! Samuel!" Then Samuel said, "Speak; for your servant hears."'),
  ('86732514-8ad1-5f91-ae9f-512922c9e743', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 11, 11, 'Yahweh said to Samuel, "Behold, I will do a thing in Israel, at which both the ears of everyone who hears it shall tingle.'),
  ('dbdb1113-e14d-5076-aabe-b57c0d1f8208', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 12, 12, 'In that day I will perform against Eli all that I have spoken concerning his house, from the beginning even to the end.'),
  ('00498ec4-e116-586e-a553-893c71794523', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 13, 13, 'For I have told him that I will judge his house forever, for the iniquity which he knew, because his sons brought a curse on themselves, and he didn''t restrain them.'),
  ('d9d19d9f-019c-50d0-a02d-66d559c85c56', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 14, 14, 'Therefore I have sworn to the house of Eli, that the iniquity of Eli''s house shall not be removed with sacrifice nor offering forever."'),
  ('71de0223-1e37-5c97-a121-adc6a483d23b', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 15, 15, 'Samuel lay until the morning, and opened the doors of the house of Yahweh. Samuel feared to show Eli the vision.'),
  ('1e82ac46-f6ad-51ae-a55b-6d4541e5fc3f', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 16, 16, 'Then Eli called Samuel, and said, "Samuel, my son!" He said, "Here I am."'),
  ('b072094a-b368-5fcc-a7d6-8f30394dbfcd', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 17, 17, 'He said, "What is the thing that [Yahweh] has spoken to you? Please don''t hide it from me. God do so to you, and more also, if you hide anything from me of all the things that he spoke to you."'),
  ('4fa87edd-05e4-5e93-a602-b7ea4926a500', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 18, 18, 'Samuel told him every bit, and hid nothing from him. He said, "It is Yahweh. Let him do what seems good to him."'),
  ('9768d8e0-1b34-5555-a06a-6e354cec7421', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 19, 19, 'Samuel grew, and Yahweh was with him, and let none of his words fall to the ground.'),
  ('51b609c8-4f42-51d1-a2bb-a799f8826326', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 20, 20, 'All Israel from Dan even to Beersheba knew that Samuel was established to be a prophet of Yahweh.'),
  ('fe0900af-12db-58f6-ab42-50e75b710c94', '0fd5d732-7ebd-5ad4-ab8e-fec7ed6c6863', NULL, 21, 21, 'Yahweh appeared again in Shiloh; for Yahweh revealed himself to Samuel in Shiloh by the word of Yahweh.'),
  ('9969b324-8114-5785-a471-f9899f3244e9', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 1, 1, 'The word of Samuel came to all Israel. Now Israel went out against the Philistines to battle, and encamped beside Ebenezer: and the Philistines encamped in Aphek.'),
  ('7d5dc205-0f8d-5cda-a0cf-d419f18ff359', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 2, 2, 'The Philistines put themselves in array against Israel: and when they joined battle, Israel was struck before the Philistines; and they killed of the army in the field about four thousand men.'),
  ('03c3020c-a3c3-5960-a611-9f1c924fc9bc', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 3, 3, 'When the people were come into the camp, the elders of Israel said, "Why has Yahweh struck us today before the Philistines? Let us get the ark of the covenant of Yahweh out of Shiloh to us, that it may come among us, and save us out of the hand of our enemies."'),
  ('5390809c-9ce5-5507-a808-3af189e30084', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 4, 4, 'So the people sent to Shiloh; and they brought from there the ark of the covenant of Yahweh of Armies, who sits [above] the cherubim: and the two sons of Eli, Hophni and Phinehas, were there with the ark of the covenant of God.'),
  ('b0140762-d52d-52fc-ab9e-4bd507f9ac28', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 5, 5, 'When the ark of the covenant of Yahweh came into the camp, all Israel shouted with a great shout, so that the earth rang again.'),
  ('4f47176b-242f-5835-a26b-df89e0fa48f9', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 6, 6, 'When the Philistines heard the noise of the shout, they said, "What does the noise of this great shout in the camp of the Hebrews mean?" They understood that the ark of Yahweh had come into the camp.'),
  ('735a9ce1-1239-5f0b-abb2-7f0dd6a1484f', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 7, 7, 'The Philistines were afraid, for they said, "God has come into the camp." They said, "Woe to us! For there has not been such a thing before.'),
  ('8a28a132-8aff-5e0a-afee-627ac649380e', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 8, 8, 'Woe to us! Who shall deliver us out of the hand of these mighty gods? These are the gods that struck the Egyptians with all kinds of plagues in the wilderness.'),
  ('ec9fb645-ebc1-5048-a751-2a623b7dd645', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 9, 9, 'Be strong, and behave like men, O you Philistines, that you not be servants to the Hebrews, as they have been to you. Strengthen yourselves like men, and fight!"'),
  ('91d4ca14-2e99-5d4a-a918-cda178d7df22', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 10, 10, 'The Philistines fought, and Israel was struck, and they fled every man to his tent: and there was a very great slaughter; for there fell of Israel thirty thousand footmen.'),
  ('9434f488-7879-5ae8-a428-d0358acb205f', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 11, 11, 'The ark of God was taken; and the two sons of Eli, Hophni and Phinehas, were slain.'),
  ('e6341618-2732-59c7-a3e4-5b8937780fa9', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 12, 12, 'There ran a man of Benjamin out of the army, and came to Shiloh the same day, with his clothes torn, and with earth on his head.'),
  ('430facc1-f2fd-5a82-a73c-29caee968c5d', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 13, 13, 'When he came, behold, Eli was sitting on his seat by the road watching; for his heart trembled for the ark of God. When the man came into the city, and told it, all the city cried out.'),
  ('91fc35f2-c043-592c-abcb-807cd63cf0ec', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 14, 14, 'When Eli heard the noise of the crying, he said, "What does the noise of this tumult mean?" The man hurried, and came and told Eli.'),
  ('743ae138-0199-5b12-a23d-b7e06a083b01', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 15, 15, 'Now Eli was ninety-eight years old; and his eyes were set, so that he could not see.'),
  ('68a3c710-b400-5ef7-addf-16898dbd088f', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 16, 16, 'The man said to Eli, "I am he who came out of the army, and I fled today out of the army." He said, "How did the matter go, my son?"'),
  ('a3c3b19b-145c-5862-a972-42f971d5de2e', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 17, 17, 'He who brought the news answered, "Israel has fled before the Philistines, and there has been also a great slaughter among the people. Your two sons also, Hophni and Phinehas, are dead, and the ark of God has been captured."'),
  ('7d660bbb-73d0-5d5e-a61e-e6055ee2131c', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 18, 18, 'It happened, when he made mention of the ark of God, that Eli fell from off his seat backward by the side of the gate; and his neck broke, and he died; for he was an old man, and heavy. He had judged Israel forty years.'),
  ('4560199f-8956-54dc-af57-8bd0ce952476', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 19, 19, 'His daughter-in-law, Phinehas'' wife, was with child, near to be delivered. When she heard the news that the ark of God was taken, and that her father-in-law and her husband were dead, she bowed herself and brought forth; for her pains came on her.'),
  ('bffe6702-a9ef-59c5-a83f-7fe8d9994460', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 20, 20, 'About the time of her death the women who stood by her said to her, "Don''t be afraid; for you have brought forth a son." But she didn''t answer, neither did she regard it.'),
  ('e06e42a6-653b-5218-ae4e-a2a24db73a06', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 21, 21, 'She named the child Ichabod, saying, "The glory has departed from Israel;" because the ark of God was taken, and because of her father-in-law and her husband.'),
  ('440af932-09ea-5f84-a0dd-14f714e66024', '55c2e042-9c73-5030-a923-65e05efb7017', NULL, 22, 22, 'She said, "The glory has departed from Israel; for the ark of God is taken."'),
  ('fe8566d6-4417-5c86-a4e8-c27ec2ee224c', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 1, 1, 'Now the Philistines had taken the ark of God, and they brought it from Ebenezer to Ashdod.'),
  ('860ead77-c4e2-5b1d-a598-dc7c1c8c9845', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 2, 2, 'The Philistines took the ark of God, and brought it into the house of Dagon, and set it by Dagon.'),
  ('d90f5264-7ecf-52ab-a4ec-db024428a08a', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 3, 3, 'When they of Ashdod arose early on the next day, behold, Dagon was fallen on his face to the ground before the ark of Yahweh. They took Dagon, and set him in his place again.'),
  ('9c286631-9967-589c-a7b3-327cdd2454c7', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 4, 4, 'When they arose early on the next day morning, behold, Dagon was fallen on his face to the ground before the ark of Yahweh; and the head of Dagon and both the palms of his hands [lay] cut off on the threshold; only [the stump of] Dagon was left to him.'),
  ('845746df-3993-5edc-a4b4-7cbf02f07e1d', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 5, 5, 'Therefore neither the priests of Dagon, nor any who come into Dagon''s house, tread on the threshold of Dagon in Ashdod, to this day.'),
  ('d824accf-38b2-56cd-a5ac-d267cfab853f', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 6, 6, 'But the hand of Yahweh was heavy on them of Ashdod, and he destroyed them, and struck them with tumors, even Ashdod and its borders.'),
  ('baad6206-c01a-58e3-a38e-82c611a4ec31', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 7, 7, 'When the men of Ashdod saw that it was so, they said, "The ark of the God of Israel shall not stay with us; for his hand is severe on us, and on Dagon our god."'),
  ('443e24ba-3d37-5655-a315-0f1478bb4b1f', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 8, 8, 'They sent therefore and gathered all the lords of the Philistines to them, and said, "What shall we do with the ark of the God of Israel?" They answered, "Let the ark of the God of Israel be carried over to Gath." They carried the ark of the God of Israel [there].'),
  ('79e513f9-9c47-579b-a60e-df456d0cc140', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 9, 9, 'It was so, that after they had carried it about, the hand of Yahweh was against the city with a very great confusion: and he struck the men of the city, both small and great; and tumors broke out on them.'),
  ('a5474064-0cfa-52ab-ac85-d7b9057c2138', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 10, 10, 'So they sent the ark of God to Ekron. It happened, as the ark of God came to Ekron, that the Ekronites cried out, saying, "They have brought about the ark of the God of Israel to us, to kill us and our people."'),
  ('5dbb25f5-1f01-5bfc-aa74-050b21a9d35b', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 11, 11, 'They sent therefore and gathered together all the lords of the Philistines, and they said, "Send away the ark of the God of Israel, and let it go again to its own place, that it not kill us and our people." For there was a deadly confusion throughout all the city; the hand of God was very heavy there.'),
  ('8c5d91ae-eec8-5399-ae43-8c57f337a24b', '28149ea5-419b-5312-a27c-2069b87f98a8', NULL, 12, 12, 'The men who didn''t die were struck with the tumors; and the cry of the city went up to heaven.'),
  ('23b8e85f-5c19-579e-aa8a-3bf029ed7d35', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 1, 1, 'The ark of Yahweh was in the country of the Philistines seven months.'),
  ('2f240cb5-ecdb-50d1-a00a-bcb7bca39b21', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 2, 2, 'The Philistines called for the priests and the diviners, saying, "What shall we do with the ark of Yahweh? Show us with which we shall send it to its place."'),
  ('8ea18eb3-53e3-55a3-a78d-31e3116f01c6', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 3, 3, 'They said, "If you send away the ark of the God of Israel, don''t send it empty; but by all means return him a trespass offering: then you shall be healed, and it shall be known to you why his hand is not removed from you."'),
  ('430bf1e8-a83f-5c6d-a93b-82edad4bdd31', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 4, 4, 'Then they said, "What shall be the trespass offering which we shall return to him?" They said, "Five golden tumors, and five golden mice, [according to] the number of the lords of the Philistines; for one plague was on you all, and on your lords.'),
  ('47f72f3f-2fea-5d2d-a8ad-1b4b926973ed', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 5, 5, 'Therefore you shall make images of your tumors, and images of your mice that mar the land; and you shall give glory to the God of Israel: perhaps he will lighten his hand from off you, and from off your gods, and from off your land.'),
  ('d8460da9-6188-5458-a1f1-2c2d60db75e9', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 6, 6, 'Why then do you harden your hearts, as the Egyptians and Pharaoh hardened their hearts? When he had worked wonderfully among them, didn''t they let the people go, and they departed?'),
  ('29c7fd22-aeb9-5810-a746-5a1f61366e04', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 7, 7, '"Now therefore take and prepare yourselves a new cart, and two milk cows, on which there has come no yoke; and tie the cows to the cart, and bring their calves home from them;'),
  ('192216df-7199-541d-acef-34b762c63457', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 8, 8, 'and take the ark of Yahweh, and lay it on the cart; and put the jewels of gold, which you return him for a trespass offering, in a coffer by its side; and send it away, that it may go.'),
  ('2f08ca4b-4590-511e-a4d9-4eca3b5754b8', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 9, 9, 'Behold; if it goes up by the way of its own border to Beth Shemesh, then he has done us this great evil: but if not, then we shall know that it is not his hand that struck us; it was a chance that happened to us."'),
  ('4b0019a4-bf77-520b-aa7d-3377cdf7b41d', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 10, 10, 'The men did so, and took two milk cows, and tied them to the cart, and shut up their calves at home;'),
  ('bc1730d3-4ba8-5a8e-a173-c21eea024434', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 11, 11, 'and they put the ark of Yahweh on the cart, and the coffer with the mice of gold and the images of their tumors.'),
  ('5136e959-f531-5970-ab55-4c8e6bc9f157', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 12, 12, 'The cows took the straight way by the way to Beth Shemesh; they went along the highway, lowing as they went, and didn''t turn aside to the right hand or to the left; and the lords of the Philistines went after them to the border of Beth Shemesh.'),
  ('78666266-e054-5029-ac71-919ae28363a2', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 13, 13, 'They of Beth Shemesh were reaping their wheat harvest in the valley; and they lifted up their eyes, and saw the ark, and rejoiced to see it.'),
  ('4fb6b43e-3afa-533b-ad00-a8872935cbac', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 14, 14, 'The cart came into the field of Joshua of Beth Shemesh, and stood there, where there was a great stone: and they split the wood of the cart, and offered up the cows for a burnt offering to Yahweh.'),
  ('3ef72aa0-32ff-5808-a7a0-345a0aca41b5', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 15, 15, 'The Levites took down the ark of Yahweh, and the coffer that was with it, in which the jewels of gold were, and put them on the great stone: and the men of Beth Shemesh offered burnt offerings and sacrificed sacrifices the same day to Yahweh.'),
  ('422fff4c-7fe8-549b-a1c8-8ef9c834a54b', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 16, 16, 'When the five lords of the Philistines had seen it, they returned to Ekron the same day.'),
  ('b75315ba-03a0-5746-ad1b-f768ce98326b', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 17, 17, 'These are the golden tumors which the Philistines returned for a trespass offering to Yahweh: for Ashdod one, for Gaza one, for Ashkelon one, for Gath one, for Ekron one;'),
  ('b29fabfd-4713-5e89-aa12-863d38ed4ed1', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 18, 18, 'and the golden mice, according to the number of all the cities of the Philistines belonging to the five lords, both of fortified cities and of country villages, even to the great stone, whereon they set down the ark of Yahweh, [which stone remains] to this day in the field of Joshua of Beth Shemesh.'),
  ('ddcf4d7c-9979-5154-a275-543a4c36468d', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 19, 19, 'He struck of the men of Beth Shemesh, because they had looked into the ark of Yahweh, he struck of the people fifty thousand seventy men; and the people mourned, because Yahweh had struck the people with a great slaughter.'),
  ('f028cc45-25a2-56d9-a438-93ad823e9cf1', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 20, 20, 'The men of Beth Shemesh said, "Who is able to stand before Yahweh, this holy God? To whom shall he go up from us?"'),
  ('e72643b6-4735-5292-aa34-5f83b6c6f997', 'd7b2e2e1-80a0-5332-a4c8-d9a30dc4aafd', NULL, 21, 21, 'They sent messengers to the inhabitants of Kiriath Jearim, saying, "The Philistines have brought back the ark of Yahweh; come down, and bring it up to yourselves."'),
  ('c19af6fc-4329-56fd-a1d4-3ac19467ade1', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 1, 1, 'The men of Kiriath Jearim came, and fetched up the ark of Yahweh, and brought it into the house of Abinadab in the hill, and sanctified Eleazar his son to keep the ark of Yahweh.'),
  ('73d568bd-aa48-5599-af91-ce8a30d3351f', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 2, 2, 'It happened, from the day that the ark stayed in Kiriath Jearim, that the time was long; for it was twenty years: and all the house of Israel lamented after Yahweh.'),
  ('b7643d55-2d9e-5874-a3b6-d019cc30afa8', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 3, 3, 'Samuel spoke to all the house of Israel, saying, "If you do return to Yahweh with all your heart, then put away the foreign gods and the Ashtaroth from among you, and direct your hearts to Yahweh, and serve him only; and he will deliver you out of the hand of the Philistines."'),
  ('b0fcfc31-0546-5193-a3ce-f92915e35223', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 4, 4, 'Then the children of Israel did put away the Baals and the Ashtaroth, and served Yahweh only.'),
  ('8cf3cf5f-b8c4-56a1-a060-7b2ec6e7bb53', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 5, 5, 'Samuel said, "Gather all Israel to Mizpah, and I will pray for you to Yahweh."'),
  ('7853810a-9792-5a45-ad0a-14b41a7c6e79', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 6, 6, 'They gathered together to Mizpah, and drew water, and poured it out before Yahweh, and fasted on that day, and said there, "We have sinned against Yahweh." Samuel judged the children of Israel in Mizpah.'),
  ('ff9663cb-d6c2-541d-ac30-c2264d650bd3', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 7, 7, 'When the Philistines heard that the children of Israel were gathered together at Mizpah, the lords of the Philistines went up against Israel. When the children of Israel heard it, they were afraid of the Philistines.'),
  ('665883d0-b661-5cad-aea2-fbbe4199a9c5', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 8, 8, 'The children of Israel said to Samuel, "Don''t cease to cry to Yahweh our God for us, that he will save us out of the hand of the Philistines."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f35fa343-61f5-541d-aa69-c39b29a5e6ce', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 9, 9, 'Samuel took a suckling lamb, and offered it for a whole burnt offering to Yahweh: and Samuel cried to Yahweh for Israel; and Yahweh answered him.'),
  ('e9bbea22-68d7-5ca7-af96-5b3ceb00f204', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 10, 10, 'As Samuel was offering up the burnt offering, the Philistines drew near to battle against Israel; but Yahweh thundered with a great thunder on that day on the Philistines, and confused them; and they were struck down before Israel.'),
  ('8db7d013-668c-5b40-aaac-cf7b1b9d42fc', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 11, 11, 'The men of Israel went out of Mizpah, and pursued the Philistines, and struck them, until they came under Beth Kar.'),
  ('e46f825d-7e96-510f-ac9b-e99c82a8d4fe', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 12, 12, 'Then Samuel took a stone, and set it between Mizpah and Shen, and called its name Ebenezer, saying, "Yahweh helped us until now."'),
  ('1474204e-05f7-53c5-a0d9-55b9cb948a1c', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 13, 13, 'So the Philistines were subdued, and they came no more within the border of Israel. The hand of Yahweh was against the Philistines all the days of Samuel.'),
  ('84d62be1-114c-5be8-a9a2-41965671b9b0', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 14, 14, 'The cities which the Philistines had taken from Israel were restored to Israel, from Ekron even to Gath; and its border did Israel deliver out of the hand of the Philistines. There was peace between Israel and the Amorites.'),
  ('f4499005-6300-578f-a285-b280ee3beb59', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 15, 15, 'Samuel judged Israel all the days of his life.'),
  ('ed8d50a3-c4ed-5e09-ac40-ef23042fdfae', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 16, 16, 'He went from year to year in circuit to Bethel and Gilgal, and Mizpah; and he judged Israel in all those places.'),
  ('1838a25b-0351-51be-ab95-c5af8bcba54a', 'efc73b3a-97a2-51bb-a721-bcc4b75d30fa', NULL, 17, 17, 'His return was to Ramah, for there was his house; and there he judged Israel: and he built there an altar to Yahweh.'),
  ('4815c7c9-3b24-58fe-ad68-4d6565913139', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 1, 1, 'It happened, when Samuel was old, that he made his sons judges over Israel.'),
  ('f67c935e-6b15-596c-a422-e60378cdad88', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 2, 2, 'Now the name of his firstborn was Joel; and the name of his second, Abijah: they were judges in Beersheba.'),
  ('495a8e43-c51b-5254-abe7-b4b6be42c879', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 3, 3, 'His sons didn''t walk in his ways, but turned aside after lucre, and took bribes, and perverted justice.'),
  ('73498e8d-de86-51d6-a1c4-58f6892bdad9', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 4, 4, 'Then all the elders of Israel gathered themselves together, and came to Samuel to Ramah;'),
  ('efafdb07-a2d3-5c1e-a25d-8c91fe4ef5fc', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 5, 5, 'and they said to him, "Behold, you are old, and your sons don''t walk in your ways: now make us a king to judge us like all the nations."'),
  ('9da7b08c-bb5c-5f29-aef9-b73596405f67', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 6, 6, 'But the thing displeased Samuel, when they said, "Give us a king to judge us." Samuel prayed to Yahweh.'),
  ('c1f27385-0a44-540b-ae46-72b8435d575c', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 7, 7, 'Yahweh said to Samuel, "Listen to the voice of the people in all that they tell you; for they have not rejected you, but they have rejected me, that I should not be king over them.'),
  ('5deed91e-a8b3-57ce-ab22-da692be569bb', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 8, 8, 'According to all the works which they have done since the day that I brought them up out of Egypt even to this day, in that they have forsaken me, and served other gods, so do they also to you.'),
  ('f901c91b-150b-5143-a5ea-32d39df85f1c', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 9, 9, 'Now therefore listen to their voice: however you shall protest solemnly to them, and shall show them the way of the king who shall reign over them."'),
  ('c982a13c-e01f-5a6e-aa28-768702538475', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 10, 10, 'Samuel told all the words of Yahweh to the people who asked of him a king.'),
  ('216fa213-c54c-5711-ad0d-3d2063bc4b62', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 11, 11, 'He said, "This will be the way of the king who shall reign over you: he will take your sons, and appoint them to him, for his chariots, and to be his horsemen; and they shall run before his chariots;'),
  ('b24f59d3-ab73-535c-a14b-2b156d645224', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 12, 12, 'and he will appoint them to him for captains of thousands, and captains of fifties; and [he will set some] to plow his ground, and to reap his harvest, and to make his instruments of war, and the instruments of his chariots.'),
  ('73884d57-c138-5bb5-a749-77ae06e7eb52', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 13, 13, 'He will take your daughters to be perfumers, and to be cooks, and to be bakers.'),
  ('a93cee48-93a8-5576-a593-483280cfab1f', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 14, 14, 'He will take your fields, and your vineyards, and your olive groves, even the best of them, and give them to his servants.'),
  ('8eb9b586-0ba1-5751-a04d-082d9fd478ae', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 15, 15, 'He will take the tenth of your seed, and of your vineyards, and give to his officers, and to his servants.'),
  ('c187b39d-a8a2-537d-a3c6-134cf69488d8', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 16, 16, 'He will take your male servants, and your female servants, and your best young men, and your donkeys, and put them to his work.'),
  ('6e965132-c22e-5c09-af3c-02a1026033d4', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 17, 17, 'He will take the tenth of your flocks: and you shall be his servants.'),
  ('0c0e8211-a406-5e93-ab3f-76e22812e95e', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 18, 18, 'You shall cry out in that day because of your king whom you shall have chosen you; and Yahweh will not answer you in that day."'),
  ('d21401f5-f749-5c60-adad-eee68058c9bb', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 19, 19, 'But the people refused to listen to the voice of Samuel; and they said, "No; but we will have a king over us,'),
  ('143b28cc-23f9-5348-ac9d-5080384caf7e', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 20, 20, 'that we also may be like all the nations, and that our king may judge us, and go out before us, and fight our battles."'),
  ('6cdac383-64c8-511d-af25-5a21ce0d5ae1', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 21, 21, 'Samuel heard all the words of the people, and he rehearsed them in the ears of Yahweh.'),
  ('fcc103c6-4c3e-5180-abde-ec05acb7897a', '6ea96682-4435-5f06-ab8d-9f4ea2bd2a39', NULL, 22, 22, 'Yahweh said to Samuel, "Listen to their voice, and make them a king." Samuel said to the men of Israel, "Every man go to his city."'),
  ('7946ace7-98a8-5878-a6e5-a3c575ffddd2', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 1, 1, 'Now there was a man of Benjamin, whose name was Kish, the son of Abiel, the son of Zeror, the son of Becorath, the son of Aphiah, the son of a Benjamite, a mighty man of valor.'),
  ('4769eca5-1df6-5307-a12f-f7a136003f1b', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 2, 2, 'He had a son, whose name was Saul, an impressive young man; and there was not among the children of Israel a better person than he. From his shoulders and upward he was higher than any of the people.'),
  ('fe45622c-bbd4-5ce1-aa87-b7f276625bf3', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 3, 3, 'The donkeys of Kish, Saul''s father, were lost. Kish said to Saul his son, "Take now one of the servants with you, and arise, go seek the donkeys."'),
  ('540f1391-a317-5a98-abbc-b37fd2fb0545', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 4, 4, 'He passed through the hill country of Ephraim, and passed through the land of Shalishah, but they didn''t find them: then they passed through the land of Shaalim, and there they weren''t there: and he passed through the land of the Benjamites, but they didn''t find them.'),
  ('6fa28ddb-0d9f-5a4a-ad3b-47640f1a1cca', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 5, 5, 'When they had come to the land of Zuph, Saul said to his servant who was with him, "Come, and let us return, lest my father stop caring about the donkeys, and be anxious for us."'),
  ('0587043c-0446-5a60-a817-156a675a6933', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 6, 6, 'He said to him, "See now, there is in this city a man of God, and he is a man who is held in honor. All that he says comes surely to pass. Now let us go there. Perhaps he can tell us concerning our journey whereon we go."'),
  ('11112d00-e979-52a5-a505-bc8c939846cb', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 7, 7, 'Then Saul said to his servant, "But, behold, if we go, what shall we bring the man? For the bread is spent in our vessels, and there is not a present to bring to the man of God. What do we have?"'),
  ('2dbdf5ac-f533-54ea-af74-2abdec031cb2', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 8, 8, 'The servant answered Saul again, and said, "Behold, I have in my hand the fourth part of a shekel of silver. I will give that to the man of God, to tell us our way."'),
  ('b0ccb897-a640-550f-addf-776d5ff1445f', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 9, 9, '(In earlier times in Israel, when a man went to inquire of God, thus he said, "Come, and let us go to the seer;" for he who is now called a prophet was before called a Seer.)'),
  ('1c0042b4-69e0-5b10-a625-28b055786a18', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 10, 10, 'Then Saul said to his servant, "Well said. Come, let us go." So they went to the city where the man of God was.'),
  ('dd71fe2a-0038-5edf-aac7-e60a0e4689a9', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 11, 11, 'As they went up the ascent to the city, they found young maidens going out to draw water, and said to them, "Is the seer here?"'),
  ('5385b772-18c5-53e7-a5e8-8f2e498f1b56', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 12, 12, 'They answered them, and said, "He is. Behold, he is before you. Hurry now, for he has come today into the city; for the people have a sacrifice today in the high place.'),
  ('84a86a88-eca3-5ad8-aaad-8d5906b2d270', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 13, 13, 'As soon as you have come into the city, you shall immediately find him, before he goes up to the high place to eat; for the people will not eat until he come, because he blesses the sacrifice. Afterwards those who are invited eat. Now therefore go up; for at this time you shall find him."'),
  ('1ce425c0-637d-5407-a71d-604d38510eee', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 14, 14, 'They went up to the city; [and] as they came within the city, behold, Samuel came out toward them, to go up to the high place.'),
  ('267944d3-c726-5168-a9e8-b2a2209757af', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 15, 15, 'Now Yahweh had revealed to Samuel a day before Saul came, saying,'),
  ('e0ff2787-902c-56ee-ae44-c35bc5947563', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 16, 16, '"Tomorrow about this time I will send you a man out of the land of Benjamin, and you shall anoint him to be prince over my people Israel; and he shall save my people out of the hand of the Philistines: for I have looked on my people, because their cry has come to me."'),
  ('eeb4bfac-bcfb-5331-a803-34fabf98375f', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 17, 17, 'When Samuel saw Saul, Yahweh said to him, "Behold, the man of whom I spoke to you! this same shall have authority over my people."'),
  ('bd5be899-9247-5674-a9f5-b2c00585b6fc', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 18, 18, 'Then Saul drew near to Samuel in the gate, and said, "Please tell me where the seer''s house is."'),
  ('1a7370f7-f958-59ad-a5dc-2a232d2b1da7', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 19, 19, 'Samuel answered Saul, and said, "I am the seer. Go up before me to the high place, for you shall eat with me today. In the morning I will let you go, and will tell you all that is in your heart.'),
  ('f439e0ba-c322-54e4-a1fd-3de37a42c4d5', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 20, 20, 'As for your donkeys who were lost three days ago, don''t set your mind on them; for they are found. For whom is all that is desirable in Israel? Is it not for you, and for all your father''s house?"'),
  ('f432a702-e04f-5eeb-a67e-97413c79a1a6', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 21, 21, 'Saul answered, "Am I not a Benjamite, of the smallest of the tribes of Israel? And my family the least of all the families of the tribe of Benjamin? Why then do you speak to me like this?"'),
  ('ea0fbc6c-88db-573d-aa0a-af03fadb936b', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 22, 22, 'Samuel took Saul and his servant, and brought them into the guest room, and made them sit in the best place among those who were invited, who were about thirty persons.'),
  ('1a5ef62f-445a-599c-aa92-45101d6a9502', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 23, 23, 'Samuel said to the cook, "Bring the portion which I gave you, of which I said to you, ''Set it aside.''"'),
  ('5e3f7982-8adc-58c8-aaa9-6c0d0522d8d3', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 24, 24, 'The cook took up the thigh, and that which was on it, and set it before Saul. Samuel said, "Behold, that which has been reserved! Set it before yourself and eat; because for the appointed time has it been kept for you, for I said, ''I have invited the people.''" So Saul ate with Samuel that day.'),
  ('7e8642a8-c905-58b9-aec9-5eb08c3c08f9', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 25, 25, 'When they had come down from the high place into the city, he talked with Saul on the housetop.'),
  ('005e2928-ae06-548b-aa82-1e3c0d584c84', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 26, 26, 'They arose early: and it happened about the spring of the day, that Samuel called to Saul on the housetop, saying, "Get up, that I may send you away." Saul arose, and they went out both of them, he and Samuel, abroad.'),
  ('20f08793-a292-5a7a-a9a1-a10baf4fdb28', 'bfd6a721-c88c-53ba-a755-f27a8836ce3c', NULL, 27, 27, 'As they were going down at the end of the city, Samuel said to Saul, "Tell the servant pass on before us" (and he passed on), "but stand still first, that I may cause you to hear the word of God."'),
  ('9a7bc247-7c35-5afe-a892-8d4d29ed7e31', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 1, 1, 'Then Samuel took the vial of oil, and poured it on his head, and kissed him, and said, "Isn''t it that Yahweh has anointed you to be prince over his inheritance?'),
  ('8b38b825-4db1-5e20-a484-fbb3920ad396', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 2, 2, 'When you have departed from me today, then you shall find two men by Rachel''s tomb, in the border of Benjamin at Zelzah; and they will tell you, ''The donkeys which you went to seek have been found; and behold, your father has stopped caring about the donkeys, and is anxious for you, saying, "What shall I do for my son?"'''),
  ('7cfc1018-2483-5cf3-ad85-07b2de17867a', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 3, 3, '"Then you shall go on forward from there, and you shall come to the oak of Tabor; and three men shall meet you there going up to God to Bethel, one carrying three young goats, and another carrying three loaves of bread, and another carrying a bottle of wine:'),
  ('d65ee4c8-cdae-5dc3-a873-21646db2883c', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 4, 4, 'and they will greet you, and give you two loaves of bread, which you shall receive of their hand.'),
  ('99f4b434-6400-563d-a88b-b0f87cede83d', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 5, 5, '"After that you shall come to the hill of God, where is the garrison of the Philistines: and it shall happen, when you have come there to the city, that you shall meet a band of prophets coming down from the high place with a psaltery, and a tambourine, and a pipe, and a harp, before them; and they will be prophesying:'),
  ('b615de2d-df4b-52ce-a95c-6f7a87052ba0', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 6, 6, 'and the Spirit of Yahweh will come mightily on you, and you shall prophesy with them, and shall be turned into another man.'),
  ('140268cd-06ad-5d29-a5f5-c13a087985ee', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 7, 7, 'Let it be, when these signs have come to you, that you do as occasion shall serve you; for God is with you.'),
  ('9aabd077-11d6-54ef-a6c0-76768ad2eccd', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 8, 8, '"You shall go down before me to Gilgal; and behold, I will come down to you, to offer burnt offerings, and to sacrifice sacrifices of peace offerings: you shall wait seven days, until I come to you, and show you what you shall do."'),
  ('0190e538-1a58-5561-abb2-9b24dbfcd9ab', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 9, 9, 'It was so, that when he had turned his back to go from Samuel, God gave him another heart: and all those signs happened that day.'),
  ('99d29bcc-25e5-57b1-a801-82adea0567f1', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 10, 10, 'When they came there to the hill, behold, a band of prophets met him; and the Spirit of God came mightily on him, and he prophesied among them.'),
  ('e965465a-5732-5c19-a994-1a3ca6659d92', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 11, 11, 'It happened, when all who knew him before saw that, behold, he prophesied with the prophets, then the people said one to another, "What is this that is come to the son of Kish? Is Saul also among the prophets?"'),
  ('2d81f5ec-4538-5d65-a65c-6a101b9a6550', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 12, 12, 'One of the same place answered, "Who is their father?" Therefore it became a proverb, "Is Saul also among the prophets?"'),
  ('20ac8764-da2a-51d6-a5e1-14c3aa7465d8', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 13, 13, 'When he had made an end of prophesying, he came to the high place.'),
  ('5aa357cd-887e-54b7-acc9-380b0ce61aff', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 14, 14, 'Saul''s uncle said to him and to his servant, "Where did you go?" He said, "To seek the donkeys. When we saw that they were not found, we came to Samuel."'),
  ('8ee1fa36-4e5b-54e8-a7c5-84ed4af23d53', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 15, 15, 'Saul''s uncle said, "Please tell me what Samuel said to you."'),
  ('13c73c27-72b6-55de-a4f1-205d034055ba', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 16, 16, 'Saul said to his uncle, "He told us plainly that the donkeys were found." But concerning the matter of the kingdom, of which Samuel spoke, he didn''t tell him.'),
  ('0f2741e0-b363-5d60-a55a-ab54488bf63e', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 17, 17, 'Samuel called the people together to Yahweh to Mizpah;'),
  ('555cfdea-d175-5aca-ab00-e4d3e9f218f8', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 18, 18, 'and he said to the children of Israel, "Thus says Yahweh, the God of Israel, ''I brought up Israel out of Egypt, and I delivered you out of the hand of the Egyptians, and out of the hand of all the kingdoms that oppressed you:'''),
  ('7fda9b0c-1deb-5b63-a7c9-0f400b5417b0', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 19, 19, 'but you have this day rejected your God, who himself saves you out of all your calamities and your distresses; and you have said to him, ''[No], but set a king over us.'' Now therefore present yourselves before Yahweh by your tribes, and by your thousands."'),
  ('6f2e97e9-3de7-5601-a4ed-c3dfd326b882', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 20, 20, 'So Samuel brought all the tribes of Israel near, and the tribe of Benjamin was taken.'),
  ('5c477b07-45b1-572e-a536-3af204e05477', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 21, 21, 'He brought the tribe of Benjamin near by their families; and the family of the Matrites was taken; and Saul the son of Kish was taken: but when they sought him, he could not be found.'),
  ('c2bb5584-7abf-5544-af2d-f0e2d60dba4c', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 22, 22, 'Therefore they asked of Yahweh further, "Is there yet a man to come here?" Yahweh answered, "Behold, he has hidden himself among the baggage."'),
  ('088dec78-2e0f-58e8-af44-31ebf62a88c0', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 23, 23, 'They ran and fetched him there; and when he stood among the people, he was higher than any of the people from his shoulders and upward.'),
  ('20f61354-e23d-591b-af6d-7fe3a1d2e210', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 24, 24, 'Samuel said to all the people, "You see him whom Yahweh has chosen, that there is none like him among all the people?" All the people shouted, and said, "[Long] live the king!"'),
  ('646bac8d-d65b-5865-a366-ce610ea29001', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 25, 25, 'Then Samuel told the people the regulations of the kingdom, and wrote it in a book, and laid it up before Yahweh. Samuel sent all the people away, every man to his house.'),
  ('522fbb44-fe6c-5303-af8e-aee8c3ae9fa0', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 26, 26, 'Saul also went to his house to Gibeah; and there went with him the army, whose hearts God had touched.'),
  ('33ade2df-f56f-53d2-ae15-d47e3011f87e', 'a7390dd6-cf95-5718-abdf-cb1e6acc7e19', NULL, 27, 27, 'But certain worthless fellows said, "How shall this man save us?" They despised him, and brought him no present. But he held his peace.'),
  ('bf082392-ea4e-5b93-a6e8-8a1496feff98', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 1, 1, 'Then Nahash the Ammonite came up, and encamped against Jabesh Gilead: and all the men of Jabesh said to Nahash, "Make a covenant with us, and we will serve you."'),
  ('c8f2f448-af4c-5ae8-a106-ffeba8300078', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 2, 2, 'Nahash the Ammonite said to them, "On this condition I will make it with you, that all your right eyes be put out; and I will lay it for a reproach on all Israel."'),
  ('5d8415c7-1388-59bd-ad34-1c6b73529f96', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 3, 3, 'The elders of Jabesh said to him, "Give us seven day, that we may send messengers to all the borders of Israel; and then, if there is no one to save us, we will come out to you."'),
  ('72c8857f-ed7c-5099-ac46-5ed10520d888', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 4, 4, 'Then the messengers came to Gibeah of Saul, and spoke these words in the ears of the people: and all the people lifted up their voice, and wept.'),
  ('9a628933-fd8d-5412-a16d-5e670cba0191', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 5, 5, 'Behold, Saul came following the oxen out of the field; and Saul said, "What ails the people that they weep?" They told him the words of the men of Jabesh.'),
  ('46ac67e0-af99-54a7-a14a-9323b6868a18', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 6, 6, 'The Spirit of God came mightily on Saul when he heard those words, and his anger was kindled greatly.'),
  ('d7b6faa3-16f4-5443-a79d-3500d7e4a6b4', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 7, 7, 'He took a yoke of oxen, and cut them in pieces, and sent them throughout all the borders of Israel by the hand of messengers, saying, "Whoever doesn''t come forth after Saul and after Samuel, so shall it be done to his oxen." The dread of Yahweh fell on the people, and they came out as one man.'),
  ('dced3d66-547c-5a71-aa73-f011d413350f', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 8, 8, 'He numbered them in Bezek; and the children of Israel were three hundred thousand, and the men of Judah thirty thousand.'),
  ('c87948f6-184f-5cc7-a835-c4600efbb4ed', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 9, 9, 'They said to the messengers who came, "Thus you shall tell the men of Jabesh Gilead, ''Tomorrow, by the time the sun is hot, you shall have deliverance.''" The messengers came and told the men of Jabesh; and they were glad.'),
  ('37cb0c88-5a94-5b15-a0a1-04af9b962e59', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 10, 10, 'Therefore the men of Jabesh said, "Tomorrow we will come out to you, and you shall do with us all that seems good to you."'),
  ('c52669d5-3336-59d2-a7ed-380fb9e287b6', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 11, 11, 'It was so on the next day, that Saul put the people in three companies; and they came into the midst of the camp in the morning watch, and struck the Ammonites until the heat of the day: and it happened, that those who remained were scattered, so that no two of them were left together.'),
  ('b3156a4f-08fe-5a0d-a070-25eb480ee5f9', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 12, 12, 'The people said to Samuel, "Who is he who said, ''Shall Saul reign over us?'' Bring those men, that we may put them to death!"'),
  ('a54b1d65-880e-52cd-a915-18a2c5fa0381', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 13, 13, 'Saul said, "There shall not a man be put to death this day; for today Yahweh has worked deliverance in Israel."'),
  ('195fd317-457c-5013-ad0c-5b4bd7b527e3', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 14, 14, 'Then Samuel said to the people, "Come, and let us go to Gilgal, and renew the kingdom there."'),
  ('3b7e99c5-164e-573d-a332-f14d4ac96b59', '1fcf23ac-479e-5042-ac99-56a2ddcc8ac8', NULL, 15, 15, 'All the people went to Gilgal; and there they made Saul king before Yahweh in Gilgal; and there they offered sacrifices of peace offerings before Yahweh; and there Saul and all the men of Israel rejoiced greatly.'),
  ('2b82aaac-946b-576b-a510-fc19a209339d', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 1, 1, 'Samuel said to all Israel, "Behold, I have listened to your voice in all that you said to me, and have made a king over you.'),
  ('ec837391-09ff-5b79-a483-5ae26a98a234', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 2, 2, 'Now, behold, the king walks before you; and I am old and gray-headed; and behold, my sons are with you: and I have walked before you from my youth to this day.'),
  ('90adc2c3-04ee-5e59-af26-7ed412b116a0', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 3, 3, 'Here I am. Witness against me before Yahweh, and before his anointed. Whose ox have I taken? Whose donkey have I taken? Whom have I defrauded? Whom have I oppressed? Of whose hand have I taken a ransom to blind my eyes therewith? I will restore it to you."'),
  ('b2056cc9-6052-5a53-a4c5-2ec4b742a374', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 4, 4, 'They said, "You have not defrauded us, nor oppressed us, neither have you taken anything of any man''s hand."'),
  ('406d19fc-5374-53c6-a72e-a1a7c16e83ac', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 5, 5, 'He said to them, "Yahweh is witness against you, and his anointed is witness this day, that you have not found anything in my hand." They said, "He is witness."'),
  ('e4897de8-f970-5488-a8f5-1bf43809e992', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 6, 6, 'Samuel said to the people, "It is Yahweh who appointed Moses and Aaron, and that brought your fathers up out of the land of Egypt.'),
  ('92254d75-a071-571c-a0b9-417351b9a762', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 7, 7, 'Now therefore stand still, that I may plead with you before Yahweh concerning all the righteous acts of Yahweh, which he did to you and to your fathers.'),
  ('5638d21c-dfca-5c42-a1c3-1744c9d18a38', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 8, 8, '"When Jacob was come into Egypt, and your fathers cried to Yahweh, then Yahweh sent Moses and Aaron, who brought forth your fathers out of Egypt, and made them to dwell in this place.'),
  ('0454d8f8-84c2-5389-a9ac-1f319c523e7a', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 9, 9, '"But they forgot Yahweh their God; and he sold them into the hand of Sisera, captain of the army of Hazor, and into the hand of the Philistines, and into the hand of the king of Moab; and they fought against them.'),
  ('3673df19-3d71-58ef-aa77-4ed5027f70a8', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 10, 10, 'They cried to Yahweh, and said, ''We have sinned, because we have forsaken Yahweh, and have served the Baals and the Ashtaroth: but now deliver us out of the hand of our enemies, and we will serve you.'''),
  ('44220ea9-da29-5342-a815-dcee2db601dd', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 11, 11, 'Yahweh sent Jerubbaal, and Bedan, and Jephthah, and Samuel, and delivered you out of the hand of your enemies on every side; and you lived in safety.'),
  ('94cf08af-f0a6-554a-a49e-4b052b029df9', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 12, 12, '"When you saw that Nahash the king of the children of Ammon came against you, you said to me, ''No, but a king shall reign over us;'' when Yahweh your God was your king.'),
  ('fb6af0f5-2dff-529f-a0ed-5dc3af3b271e', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 13, 13, 'Now therefore see the king whom you have chosen, and whom you have asked for: and behold, Yahweh has set a king over you.'),
  ('4aeb2186-634a-59e3-a72f-fdea806dc32e', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 14, 14, 'If you will fear Yahweh, and serve him, and listen to his voice, and not rebel against the commandment of Yahweh, and both you and also the king who reigns over you are followers of Yahweh your God, [well]:'),
  ('e9e12e1a-eca5-5e1d-ae00-125c617c68b7', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 15, 15, 'but if you will not listen to the voice of Yahweh, but rebel against the commandment of Yahweh, then will the hand of Yahweh be against you, as it was against your fathers.'),
  ('f740e6ba-d709-5f9a-ade8-e2b0363d7094', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 16, 16, '"Now therefore stand still and see this great thing, which Yahweh will do before your eyes.'),
  ('40505570-f4b3-5553-a6b3-7c74c344e36c', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 17, 17, 'Isn''t it wheat harvest today? I will call to Yahweh, that he may send thunder and rain; and you shall know and see that your wickedness is great, which you have done in the sight of Yahweh, in asking for a king."'),
  ('83f3df5c-932a-519d-a899-0bdb9092dcb5', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 18, 18, 'So Samuel called to Yahweh; and Yahweh sent thunder and rain that day: and all the people greatly feared Yahweh and Samuel.'),
  ('d1e72285-5e3b-585f-a664-78099694a87f', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 19, 19, 'All the people said to Samuel, "Pray for your servants to Yahweh your God, that we not die; for we have added to all our sins [this] evil, to ask us a king."'),
  ('35271b1a-c7d0-508b-aada-d11947b49d79', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 20, 20, 'Samuel said to the people, "Don''t be afraid. You have indeed done all this evil; yet don''t turn aside from following Yahweh, but serve Yahweh with all your heart.'),
  ('3a43be9c-efe1-5faf-a45e-de65bfd588d4', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 21, 21, 'Don''t turn aside; for [then you would go] after vain things which can''t profit nor deliver, for they are vain.'),
  ('ee6fa76e-6d04-57b2-aa5a-a88fc2d728ad', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 22, 22, 'For Yahweh will not forsake his people for his great name''s sake, because it has pleased Yahweh to make you a people to himself.'),
  ('0e4cad03-9978-527b-a47a-7448d607ef71', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 23, 23, 'Moreover as for me, far be it from me that I should sin against Yahweh in ceasing to pray for you: but I will instruct you in the good and the right way.'),
  ('4ba21f6f-b66b-51fe-a582-94f75c4d064e', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 24, 24, 'Only fear Yahweh, and serve him in truth with all your heart; for consider how great things he has done for you.'),
  ('0df510ae-8056-5361-a298-14db24b865ab', 'cea26ae9-fab9-52b5-a1a1-4067959e02b1', NULL, 25, 25, 'But if you shall still do wickedly, you shall be consumed, both you and your king."'),
  ('d669092a-e242-51ff-afa5-051458d3f9ae', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 1, 1, 'Saul was [forty] years old when he began to reign; and when he had reigned two years over Israel,'),
  ('cb7a48b4-419a-5792-a7c3-c03c37ca584c', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 2, 2, 'Saul chose him three thousand men of Israel, of which two thousand were with Saul in Michmash and in the Mount of Bethel, and one thousand were with Jonathan in Gibeah of Benjamin: and the rest of the people he sent every man to his tent.'),
  ('75cadd2c-23a2-54d2-a8fd-819690442d8a', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 3, 3, 'Jonathan struck the garrison of the Philistines that was in Geba: and the Philistines heard of it. Saul blew the trumpet throughout all the land, saying, "Let the Hebrews hear!"'),
  ('ededf7a5-1473-5cfc-a9ef-6215029ee350', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 4, 4, 'All Israel heard that Saul had struck the garrison of the Philistines, and also that Israel was had in abomination with the Philistines. The people were gathered together after Saul to Gilgal.'),
  ('7cf41190-c7e9-52ab-ad31-6ffe731c4a65', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 5, 5, 'The Philistines assembled themselves together to fight with Israel, thirty thousand chariots, and six thousand horsemen, and people as the sand which is on the seashore in multitude: and they came up, and encamped in Michmash, eastward of Beth Aven.'),
  ('7a8d8538-af93-52c5-a5cd-21316efba9c3', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 6, 6, 'When the men of Israel saw that they were in a strait (for the people were distressed), then the people did hide themselves in caves, and in thickets, and in rocks, and in coverts, and in pits.'),
  ('ea1e8ef2-7e83-5c5c-a97f-7a5e0525e90a', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 7, 7, 'Now some of the Hebrews had gone over the Jordan to the land of Gad and Gilead; but as for Saul, he was yet in Gilgal, and all the people followed him trembling.'),
  ('df03d610-a8ab-522f-abb3-352db9c1541f', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 8, 8, 'He stayed seven days, according to the set time that Samuel [had appointed]: but Samuel didn''t come to Gilgal; and the people were scattered from him.'),
  ('964803fb-6a4b-5f9b-a596-4eb2ff8898ab', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 9, 9, 'Saul said, "Bring here the burnt offering to me, and the peace offerings." He offered the burnt offering.'),
  ('4fc479a8-56c6-54d6-a3d4-131167e316c9', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 10, 10, 'It came to pass that as soon as he had made an end of offering the burnt offering, behold, Samuel came; and Saul went out to meet him, that he might greet him.'),
  ('c0abdbde-a9a3-5597-a00a-f3acd52559d2', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 11, 11, 'Samuel said, "What have you done?" Saul said, "Because I saw that the people were scattered from me, and that you didn''t come within the days appointed, and that the Philistines assembled themselves together at Michmash;'),
  ('e243db38-b6ba-5e5f-a80c-3f2b35a2646f', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 12, 12, 'therefore I said, ''Now the Philistines will come down on me to Gilgal, and I haven''t entreated the favor of Yahweh.'' I forced myself therefore, and offered the burnt offering."'),
  ('fab19485-f4b5-585f-a7a9-684187511a3e', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 13, 13, 'Samuel said to Saul, "You have done foolishly. You have not kept the commandment of Yahweh your God, which he commanded you; for now Yahweh would have established your kingdom on Israel forever.'),
  ('5d133d2d-c15f-5e11-a54c-ed268bb56b86', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 14, 14, 'But now your kingdom shall not continue. Yahweh has sought for himself a man after his own heart, and Yahweh has appointed him to be prince over his people, because you have not kept that which Yahweh commanded you."'),
  ('79ab632f-590f-568d-a335-430787e9b532', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 15, 15, 'Samuel arose, and went from Gilgal to Gibeah of Benjamin. Saul numbered the people who were present with him, about six hundred men.'),
  ('fde70330-b7a9-5ea9-a296-a0b13254409b', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 16, 16, 'Saul, and Jonathan his son, and the people who were present with them, stayed in Geba of Benjamin: but the Philistines encamped in Michmash.'),
  ('0ec4c836-1060-5654-a40e-85dd625897a0', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 17, 17, 'The spoilers came out of the camp of the Philistines in three companies: one company turned to the way that leads to Ophrah, to the land of Shual;'),
  ('388f3c7c-94ca-5536-aadf-cba26aa9212c', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 18, 18, 'and another company turned the way to Beth Horon; and another company turned the way of the border that looks down on the valley of Zeboim toward the wilderness.'),
  ('c4e234b7-0206-5427-a292-1ab85f3afded', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 19, 19, 'Now there was no smith found throughout all the land of Israel; for the Philistines said, "Lest the Hebrews make them swords or spears;"'),
  ('e622b484-f230-5bcb-ac84-5f1c807bcc63', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 20, 20, 'but all the Israelites went down to the Philistines, to sharpen every man his plowshare, mattock, axe, and sickle;'),
  ('994979c1-87c3-5eb0-a5bd-235d29468977', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 21, 21, 'yet they had a file for the mattocks, and for the plowshares, and for the forks, and for the axes, and to set the goads.'),
  ('19be420b-12f2-541a-a955-bd310048a2d5', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 22, 22, 'So it came to pass in the day of battle, that there was neither sword nor spear found in the hand of any of the people who were with Saul and Jonathan: but with Saul and with Jonathan his son was there found.'),
  ('8b4d2d9b-d455-5fa1-a53b-d3332da69781', '1d96e6fa-2dc7-5ca0-a067-db578b1c5671', NULL, 23, 23, 'The garrison of the Philistines went out to the pass of Michmash.'),
  ('bab0be49-24c3-5eab-afac-d90e2fc91557', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 1, 1, 'Now it fell on a day, that Jonathan the son of Saul said to the young man who bore his armor, "Come, and let us go over to the Philistines'' garrison, that is on the other side." But he didn''t tell his father.'),
  ('451e43c2-6417-51c2-acf9-0ba16cd78603', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 2, 2, 'Saul stayed in the uttermost part of Gibeah under the pomegranate tree which is in Migron: and the people who were with him were about six hundred men;'),
  ('4b16224d-e44d-579d-a375-de080a006a25', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 3, 3, 'and Ahijah, the son of Ahitub, Ichabod''s brother, the son of Phinehas, the son of Eli, the priest of Yahweh in Shiloh, wearing an ephod. The people didn''t know that Jonathan was gone.'),
  ('7bd2a373-709f-54d9-a9f9-8d87ae55d9d7', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 4, 4, 'Between the passes, by which Jonathan sought to go over to the Philistines'' garrison, there was a rocky crag on the one side, and a rocky crag on the other side: and the name of the one was Bozez, and the name of the other Seneh.'),
  ('010db936-74b9-567f-a7fe-18fe36fd614f', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 5, 5, 'The one crag rose up on the north in front of Michmash, and the other on the south in front of Geba.'),
  ('c0700cd3-ff13-55a5-a48b-9e277e7722fa', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 6, 6, 'Jonathan said to the young man who bore his armor, "Come, and let us go over to the garrison of these uncircumcised. It may be that Yahweh will work for us; for there is no restraint on Yahweh to save by many or by few."'),
  ('30c9b3e5-7735-5918-ad4e-497592a40bd2', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 7, 7, 'His armor bearer said to him, "Do all that is in your heart. Turn and, behold, I am with you according to your heart."'),
  ('959662a0-838d-5830-a237-4735131ed653', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 8, 8, 'Then Jonathan said, "Behold, we will pass over to the men, and we will reveal ourselves to them.'),
  ('48dbd0f0-2453-5aa6-a3e1-94a660a8e3ff', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 9, 9, 'If they say thus to us, ''Wait until we come to you!'' then we will stand still in our place, and will not go up to them.'),
  ('4e058a95-07ef-520e-a7cb-e738b4e95550', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 10, 10, 'But if they say this, ''Come up to us!'' then we will go up; for Yahweh has delivered them into our hand. This shall be the sign to us."'),
  ('7d6cc874-a6eb-5ff5-a0ed-33b53c173e67', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 11, 11, 'Both of them revealed themselves to the garrison of the Philistines: and the Philistines said, "Behold, the Hebrews are coming out of the holes where they had hidden themselves!"'),
  ('1aac5b7f-3103-5b71-a561-bb5f4c7481f9', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 12, 12, 'The men of the garrison answered Jonathan and his armor bearer, and said, "Come up to us, and we will show you something!" Jonathan said to his armor bearer, "Come up after me; for Yahweh has delivered them into the hand of Israel."'),
  ('ea09b4ca-9ceb-50b1-aa99-dd9552b47e73', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 13, 13, 'Jonathan climbed up on his hands and on his feet, and his armor bearer after him: and they fell before Jonathan; and his armor bearer killed them after him.'),
  ('e686c050-1724-5d7e-aa3a-0de88c3f9502', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 14, 14, 'That first slaughter, which Jonathan and his armor bearer made, was about twenty men, within as it were half a furrow''s length in an acre of land.'),
  ('8a1d93b5-39ff-5af5-a33b-b5d65f673cc2', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 15, 15, 'There was a trembling in the camp, in the field, and among all the people; the garrison, and the spoilers, they also trembled; and the earth quaked: so there was an exceeding great trembling.'),
  ('3c8b4ed6-d6ce-5da4-a145-7b3004e728bf', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 16, 16, 'The watchmen of Saul in Gibeah of Benjamin looked; and behold, the multitude melted away, and they went [here] and there.'),
  ('6c513a8b-2366-56cf-afcb-fd15f3725fb4', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 17, 17, 'Then Saul said to the people who were with him, "Count now, and see who is missing from us." When they had counted, behold, Jonathan and his armor bearer were not there.'),
  ('f3411cbd-f06b-5e53-ae7d-0cb11398486e', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 18, 18, 'Saul said to Ahijah, "Bring the ark of God here." For the ark of God was [there] at that time with the children of Israel.'),
  ('4ace0b34-f7c2-5400-a5a6-b6acbf290462', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 19, 19, 'It happened, while Saul talked to the priest, that the tumult that was in the camp of the Philistines went on and increased: and Saul said to the priest, "Withdraw your hand!"'),
  ('48d8b975-9213-5b76-a0be-b1ca388cdd70', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 20, 20, 'Saul and all the people who were with him were gathered together, and came to the battle: and behold, every man''s sword was against his fellow, [and there was] a very great confusion.'),
  ('982ed655-b053-5985-a044-21bc2d851b23', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 21, 21, 'Now the Hebrews who were with the Philistines as before, and who went up with them into the camp, [from the country] all around, even they also [turned] to be with the Israelites who were with Saul and Jonathan.'),
  ('7034de4e-3a90-5791-a047-489317ceca67', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 22, 22, 'Likewise all the men of Israel who had hidden themselves in the hill country of Ephraim, when they heard that the Philistines fled, even they also followed hard after them in the battle.'),
  ('ad6f8d36-58a8-5e5e-aac5-bcee93ae01a5', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 23, 23, 'So Yahweh saved Israel that day: and the battle passed over by Beth Aven.'),
  ('c56b1e66-f896-5c6b-a36d-e79d7cba173b', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 24, 24, 'The men of Israel were distressed that day; for Saul had adjured the people, saying, "Cursed is the man who eats any food until it is evening, and I am avenged of my enemies." So none of the people tasted food.'),
  ('0947f35c-447e-57d5-a510-366d9062d0bb', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 25, 25, 'All the people came into the forest; and there was honey on the ground.'),
  ('409bef30-8ded-555a-af79-8690d25542b1', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 26, 26, 'When the people were come to the forest, behold, the honey dropped: but no man put his hand to his mouth; for the people feared the oath.'),
  ('9b6e0ecb-9cc2-5dc1-a44e-e0257687fedd', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 27, 27, 'But Jonathan didn''t hear when his father commanded the people with the oath: therefore he put forth the end of the rod who was in his hand, and dipped it in the honeycomb, and put his hand to his mouth; and his eyes were enlightened.'),
  ('2ae504d6-ed9c-5462-a947-6d1c06f469ee', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 28, 28, 'Then one of the people answered, and said, "Your father directly commanded the people with an oath, saying, ''Cursed is the man who eats food this day.''" The people were faint.'),
  ('37aa5b85-4841-59b1-a3eb-da6b11c67085', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 29, 29, 'Then Jonathan said, "My father has troubled the land. Please look how my eyes have been enlightened, because I tasted a little of this honey.'),
  ('c3f00653-2984-50e3-a820-f26fb0ae6523', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 30, 30, 'How much more, if perhaps the people had eaten freely today of the spoil of their enemies which they found? For now has there been no great slaughter among the Philistines."'),
  ('0a3ebb86-d8d3-5d34-a1b1-80cd54800d3f', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 31, 31, 'They struck of the Philistines that day from Michmash to Aijalon. The people were very faint;'),
  ('74d8b81b-7bf3-5bd3-a84d-7de2babc1bb2', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 32, 32, 'and the people flew on the spoil, and took sheep, and cattle, and calves, and killed them on the ground; and the people ate them with the blood.'),
  ('3a14b9b8-da08-59b5-ae86-bc39357e5103', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 33, 33, 'Then they told Saul, saying, "Behold, the people are sinning against Yahweh, in that they eat meat with the blood." He said, "You have dealt treacherously. Roll a large stone to me this day!"'),
  ('250f4d3b-447d-5cf6-ab7e-a93561f54656', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 34, 34, 'Saul said, "Disperse yourselves among the people, and tell them, ''Bring me here every man his ox, and every man his sheep, and kill them here, and eat; and don''t sin against Yahweh in eating meat with the blood.''" All the people brought every man his ox with him that night, and killed them there.'),
  ('f5f873b5-1b29-57c4-a960-2a35af0be30a', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 35, 35, 'Saul built an altar to Yahweh. This was the first altar that he built to Yahweh.'),
  ('1c9f53dd-2178-5552-a061-f868e1ae6d49', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 36, 36, 'Saul said, "Let us go down after the Philistines by night, and take spoil among them until the morning light, and let us not leave a man of them." They said, "Do whatever seems good to you." Then the priest said, "Let us draw near here to God."'),
  ('fbd7fb2d-6d0c-5d73-ada0-32cc5caf9139', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 37, 37, 'Saul asked counsel of God, "Shall I go down after the Philistines? Will you deliver them into the hand of Israel?" But he didn''t answer him that day.'),
  ('b2791f5b-b603-5414-a92d-8cc6ef481e4c', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 38, 38, 'Saul said, "Draw near here, all you chiefs of the people; and know and see in which this sin has been this day.'),
  ('3d91da1c-5b9a-57dc-a2f5-0409a847e012', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 39, 39, 'For, as Yahweh lives, who saves Israel, though it is in Jonathan my son, he shall surely die." But there was not a man among all the people who answered him.'),
  ('c446ade9-2976-5566-a2ed-f242042402ad', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 40, 40, 'Then he said to all Israel, "You be on one side, and I and Jonathan my son will be on the other side." The people said to Saul, "Do what seems good to you."'),
  ('417f4f6b-f377-5cb1-ad64-3168fc4c63db', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 41, 41, 'Therefore Saul said to Yahweh, the God of Israel, "Show the right." Jonathan and Saul were chosen; but the people escaped.'),
  ('8187e130-204d-5c5a-a3e8-cca28affc03d', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 42, 42, 'Saul said, "Cast lots between me and Jonathan my son." Jonathan was selected.'),
  ('ad25b73c-a09f-57f9-a48c-04e5ddf8924b', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 43, 43, 'Then Saul said to Jonathan, "Tell me what you have done!" Jonathan told him, and said, "I certainly did taste a little honey with the end of the rod that was in my hand; and behold, I must die."'),
  ('676b8abc-bcbc-580b-a403-1d8a7977ce2a', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 44, 44, 'Saul said, "God do so and more also; for you shall surely die, Jonathan."'),
  ('6b3b8548-5d31-5005-ad69-a29699cfbe65', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 45, 45, 'The people said to Saul, "Shall Jonathan die, who has worked this great salvation in Israel? Far from it! As Yahweh lives, there shall not one hair of his head fall to the ground; for he has worked with God this day!" So the people rescued Jonathan, that he didn''t die.'),
  ('74ba6fee-411f-59bd-a97a-648eda35792f', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 46, 46, 'Then Saul went up from following the Philistines; and the Philistines went to their own place.'),
  ('d82d3626-3a08-5480-a6d4-e8632b53173a', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 47, 47, 'Now when Saul had taken the kingdom over Israel, he fought against all his enemies on every side, against Moab, and against the children of Ammon, and against Edom, and against the kings of Zobah, and against the Philistines: and wherever he turned himself, he put [them] to the worse.'),
  ('8f82a30d-f4ea-51c8-a029-cc292eae16cc', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 48, 48, 'He did valiantly, and struck the Amalekites, and delivered Israel out of the hands of those who despoiled them.'),
  ('8f5434f6-2510-51b4-a4de-e7ce30804a0e', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 49, 49, 'Now the sons of Saul were Jonathan, and Ishvi, and Malchishua; and the names of his two daughters were these: the name of the firstborn Merab, and the name of the younger Michal:'),
  ('e64f095f-63ec-5293-a286-c7bcf239c8b2', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 50, 50, 'and the name of Saul''s wife was Ahinoam the daughter of Ahimaaz. The name of the captain of his army was Abner the son of Ner, Saul''s uncle.'),
  ('9a4f3cfa-920c-53e3-affe-7d4a5f6d0c25', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 51, 51, 'Kish was the father of Saul; and Ner the father of Abner was the son of Abiel.'),
  ('c622fc90-7241-5b8b-a6e4-d6f5040956d1', 'ea016cff-4592-574a-a974-e41e044ea529', NULL, 52, 52, 'There was severe war against the Philistines all the days of Saul: and when Saul saw any mighty man, or any valiant man, he took him to him.'),
  ('c1278cbb-f898-552e-a07b-0f5118435156', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 1, 1, 'Samuel said to Saul, "Yahweh sent me to anoint you to be king over his people, over Israel. Now therefore listen to the voice of the words of Yahweh.'),
  ('83651036-6d9c-5efd-a241-4a1cfb03d451', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 2, 2, 'Thus says Yahweh of Armies, ''I have marked that which Amalek did to Israel, how he set himself against him in the way, when he came up out of Egypt.'),
  ('f117721a-f4b2-59e2-addb-474fdabbb29f', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 3, 3, 'Now go and strike Amalek, and utterly destroy all that they have, and don''t spare them; but kill both man and woman, infant and nursing baby, ox and sheep, camel and donkey.''"'),
  ('e458a7ae-b1c7-50cb-aa53-0848ef33ceab', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 4, 4, 'Saul summoned the people, and numbered them in Telaim, two hundred thousand footmen, and ten thousand men of Judah.'),
  ('df2cd201-a6ef-55d4-a361-237f20ef9df6', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 5, 5, 'Saul came to the city of Amalek, and laid wait in the valley.'),
  ('2aa8580a-8ad7-5606-aee8-f907ccf08443', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 6, 6, 'Saul said to the Kenites, "Go, depart, go down from among the Amalekites, lest I destroy you with them; for you showed kindness to all the children of Israel, when they came up out of Egypt." So the Kenites departed from among the Amalekites.'),
  ('5e151e9e-0b10-5f7c-a008-8edb01547250', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 7, 7, 'Saul struck the Amalekites, from Havilah as you go to Shur, that is before Egypt.'),
  ('ce0ea2d4-480f-509f-a3ae-45f86f15344c', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 8, 8, 'He took Agag the king of the Amalekites alive, and utterly destroyed all the people with the edge of the sword.'),
  ('716c6231-b630-50e3-ab98-e89bb7d3d9eb', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 9, 9, 'But Saul and the people spared Agag, and the best of the sheep, and of the cattle, and of the fatlings, and the lambs, and all that was good, and wouldn''t utterly destroy them: but everything that was vile and refuse, that they destroyed utterly.'),
  ('221b53f6-687c-5290-a2fe-d2b8973f28a6', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 10, 10, 'Then the word of Yahweh came to Samuel, saying,'),
  ('0c938d9a-6f99-53d9-a523-8777a3945e29', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 11, 11, '"It grieves me that I have set up Saul to be king; for he is turned back from following me, and has not performed my commandments." Samuel was angry; and he cried to Yahweh all night.'),
  ('aa6f6736-7ab2-55ab-a3d1-2e6aaf67adca', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 12, 12, 'Samuel rose early to meet Saul in the morning; and it was told Samuel, saying, "Saul came to Carmel, and behold, he set up a monument for himself, and turned, and passed on, and went down to Gilgal."'),
  ('06df94dc-06f8-58de-a0ab-2655c977cb11', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 13, 13, 'Samuel came to Saul; and Saul said to him, "You are blessed by Yahweh! I have performed the commandment of Yahweh."'),
  ('d78fb6e2-cd1f-5f5b-a0e4-700f9001cbf8', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 14, 14, 'Samuel said, "Then what does this bleating of the sheep in my ears, and the lowing of the cattle which I hear mean?"'),
  ('17e43284-673b-5396-aadb-8b12b675480c', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 15, 15, 'Saul said, "They have brought them from the Amalekites; for the people spared the best of the sheep and of the cattle, to sacrifice to Yahweh your God. We have utterly destroyed the rest."'),
  ('34d3badd-8c7c-5448-a8b0-bcdfe7d4e4cd', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 16, 16, 'Then Samuel said to Saul, "Stay, and I will tell you what Yahweh has said to me last night." He said to him, "Say on."'),
  ('9f6e6eff-1721-5fca-ab5a-8a827b0f69b5', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 17, 17, 'Samuel said, "Though you were little in your own sight, weren''t you made the head of the tribes of Israel? Yahweh anointed you king over Israel;'),
  ('9863acd7-574e-509a-a16f-715ec61db178', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 18, 18, 'and Yahweh sent you on a journey, and said, ''Go, and utterly destroy the sinners the Amalekites, and fight against them until they are consumed.'''),
  ('4a424677-fca3-5131-a520-d4ea6a0e4baf', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 19, 19, 'Why then didn''t you obey the voice of Yahweh, but took the spoils, and did that which was evil in the sight of Yahweh?"'),
  ('1c1e0554-1f14-527f-a173-f7469057a8af', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 20, 20, 'Saul said to Samuel, "But I have obeyed the voice of Yahweh, and have gone the way which Yahweh sent me, and have brought Agag the king of Amalek, and have utterly destroyed the Amalekites.'),
  ('bc94c2ef-93d4-561c-aa8a-0df57826c3a4', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 21, 21, 'But the people took of the spoil, sheep and cattle, the chief of the devoted things, to sacrifice to Yahweh your God in Gilgal."'),
  ('af8bfd35-fb72-5905-abbd-29f1bbc8cf2a', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 22, 22, 'Samuel said, "Has Yahweh as great delight in burnt offerings and sacrifices, as in obeying the voice of Yahweh? Behold, to obey is better than sacrifice, and to listen than the fat of rams.'),
  ('e4a98c88-444a-5d1a-acf3-85f20e247066', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 23, 23, 'For rebellion is as the sin of witchcraft, and stubbornness is as idolatry and teraphim. Because you have rejected the word of Yahweh, he has also rejected you from being king."'),
  ('4bb28bc6-182d-52e5-a147-499b65a174c0', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 24, 24, 'Saul said to Samuel, "I have sinned; for I have transgressed the commandment of Yahweh, and your words, because I feared the people, and obeyed their voice.'),
  ('505eab56-8b6e-555f-ad5e-0543eb949a75', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 25, 25, 'Now therefore, please pardon my sin, and turn again with me, that I may worship Yahweh."'),
  ('f3f12036-c1dd-5b8e-a301-72bc32f0b1eb', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 26, 26, 'Samuel said to Saul, "I will not return with you; for you have rejected the word of Yahweh, and Yahweh has rejected you from being king over Israel."'),
  ('d0d7f667-8a65-5ba7-a832-9f72a2b3e5c3', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 27, 27, 'As Samuel turned about to go away, Saul grabbed the skirt of his robe, and it tore.'),
  ('7c59ba8c-7b3c-5796-a0b7-3c59b0cfb303', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 28, 28, 'Samuel said to him, "Yahweh has torn the kingdom of Israel from you this day, and has given it to a neighbor of yours who is better than you.'),
  ('d88ca835-67ba-52b8-acbd-8e10bee043b1', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 29, 29, 'Also the Strength of Israel will not lie nor repent; for he is not a man, that he should repent."'),
  ('ba974c84-4fff-5d75-a0fd-0e55c16f2945', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 30, 30, 'Then he said, "I have sinned: yet please honor me now before the elders of my people, and before Israel, and come back with me, that I may worship Yahweh your God."'),
  ('5e1c08ce-db2b-56fc-a4ef-667d17f9c3bc', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 31, 31, 'So Samuel went back with Saul; and Saul worshiped Yahweh.'),
  ('8f2ede7d-b705-538b-a592-7f518b90984c', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 32, 32, 'Then Samuel said, "Bring here to me Agag the king of the Amalekites!" Agag came to him cheerfully. Agag said, "Surely the bitterness of death is past."'),
  ('a1aa2ca4-01e2-5e57-acf0-1579be65a626', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 33, 33, 'Samuel said, "As your sword has made women childless, so your mother will be childless among women!" Samuel cut Agag in pieces before Yahweh in Gilgal.'),
  ('b98d01be-a59e-52ef-a8fb-8ea7f990d684', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 34, 34, 'Then Samuel went to Ramah; and Saul went up to his house to Gibeah of Saul.'),
  ('601c8f5a-418f-536d-ac62-69749c6253e9', 'f009ac26-f772-5a48-a4fe-2e5e53003af4', NULL, 35, 35, 'Samuel came no more to see Saul until the day of his death; for Samuel mourned for Saul: and Yahweh grieved that he had made Saul king over Israel.'),
  ('5346d12b-7f95-5259-a0e0-27b7b607f828', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 1, 1, 'Yahweh said to Samuel, "How long will you mourn for Saul, since I have rejected him from being king over Israel? Fill your horn with oil, and go. I will send you to Jesse the Bethlehemite; for I have provided a king for myself among his sons."'),
  ('3f3e935b-3b53-5c45-af7b-b1a61309a08d', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 2, 2, 'Samuel said, "How can I go? If Saul hears it, he will kill me." Yahweh said, "Take a heifer with you, and say, I have come to sacrifice to Yahweh.'),
  ('dfc9a0ab-4fba-5fd9-a73a-f71519d55bee', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 3, 3, 'Call Jesse to the sacrifice, and I will show you what you shall do. You shall anoint to me him whom I name to you."'),
  ('82c49ee9-9643-5aed-a880-fc443ad33d69', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 4, 4, 'Samuel did that which Yahweh spoke, and came to Bethlehem. The elders of the city came to meet him trembling, and said, "Do you come peaceably?"'),
  ('29bbd633-1825-5ff1-a952-0193bf3d9263', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 5, 5, 'He said, "Peaceably; I have come to sacrifice to Yahweh. Sanctify yourselves, and come with me to the sacrifice." He sanctified Jesse and his sons, and called them to the sacrifice.'),
  ('0c6fa442-16dd-545a-aa35-82e31bfe494e', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 6, 6, 'It happened, when they had come, that he looked at Eliab, and said, "Surely Yahweh''s anointed is before him."'),
  ('78749bd1-75d4-52f7-a4b7-1e94e7f9c375', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 7, 7, 'But Yahweh said to Samuel, "Don''t look on his face, or on the height of his stature; because I have rejected him: for [Yahweh sees] not as man sees; for man looks at the outward appearance, but Yahweh looks at the heart."'),
  ('de815844-b1f3-5b90-ad5c-5de8c3d16b8e', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 8, 8, 'Then Jesse called Abinadab, and made him pass before Samuel. He said, "Neither has Yahweh chosen this one."'),
  ('e9689b63-a4b5-585b-a410-7e8b93f90e52', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 9, 9, 'Then Jesse made Shammah to pass by. He said, "Neither has Yahweh chosen this one."'),
  ('243ab674-cb98-5ba0-af89-5d9960d759a5', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 10, 10, 'Jesse made seven of his sons to pass before Samuel. Samuel said to Jesse, "Yahweh has not chosen these."'),
  ('838293f2-2799-5959-adbe-3b498b596c1c', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 11, 11, 'Samuel said to Jesse, "Are all your children here?" He said, "There remains yet the youngest, and behold, he is keeping the sheep." Samuel said to Jesse, "Send and get him; for we will not sit down until he comes here."'),
  ('a1f42d03-5d6d-5369-ad96-f04cf5ea907a', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 12, 12, 'He sent, and brought him in. Now he was ruddy, and withal of a beautiful face, and goodly to look on. Yahweh said, "Arise, anoint him; for this is he."'),
  ('24cdcfa2-042a-5b6d-a6e8-5ff427860acf', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 13, 13, 'Then Samuel took the horn of oil, and anointed him in the midst of his brothers: and the Spirit of Yahweh came mightily on David from that day forward. So Samuel rose up, and went to Ramah.'),
  ('b811e03f-82fc-5255-a4af-52da99209cef', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 14, 14, 'Now the Spirit of Yahweh departed from Saul, and an evil spirit from Yahweh troubled him.'),
  ('1a827209-d0d2-5c70-ad7a-8049528b5b2b', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 15, 15, 'Saul''s servants said to him, "See now, an evil spirit from God troubles you.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f1c54db9-236d-5396-a5bb-0cc570d9dfc7', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 16, 16, 'Let our lord now command your servants who are before you, to seek out a man who is a skillful player on the harp. It shall happen, when the evil spirit from God is on you, that he shall play with his hand, and you shall be well."'),
  ('38cf5e53-ee09-51ce-a54f-ab17c9663dac', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 17, 17, 'Saul said to his servants, "Provide me now a man who can play well, and bring him to me."'),
  ('e06f35cb-59a7-5b7e-aef1-51f383a8c82a', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 18, 18, 'Then one of the young men answered, and said, "Behold, I have seen a son of Jesse the Bethlehemite, who is skillful in playing, a mighty man of valor, a man of war, prudent in speech, and a comely person; and Yahweh is with him."'),
  ('8b40cf5a-534d-5d10-a5b6-16dc385df6aa', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 19, 19, 'Therefore Saul sent messengers to Jesse, and said, "Send me David your son, who is with the sheep."'),
  ('8edc3268-e242-585f-a453-c54564894167', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 20, 20, 'Jesse took a donkey loaded with bread, and a bottle of wine, and a young goat, and sent them by David his son to Saul.'),
  ('d0670e09-ca02-5cb6-a8ce-c885d49bec53', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 21, 21, 'David came to Saul, and stood before him. He loved him greatly; and he became his armor bearer.'),
  ('dbb6ac68-af45-5eba-aef9-5e31fdcc5b3b', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 22, 22, 'Saul sent to Jesse, saying, "Please let David stand before me; for he has found favor in my sight."'),
  ('a7573eee-21d2-52e5-af7c-bf34ee256f1f', 'cc50dfb7-450e-5079-a2a0-06a9fd565fdb', NULL, 23, 23, 'It happened, when the [evil] spirit from God was on Saul, that David took the harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him.'),
  ('a68fe013-95f9-5809-ae5a-fe91f9307892', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 1, 1, 'Now the Philistines gathered together their armies to battle; and they were gathered together at Socoh, which belongs to Judah, and encamped between Socoh and Azekah, in Ephesdammim.'),
  ('253fdba0-c1f0-50a0-a22d-616c8b0929a9', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 2, 2, 'Saul and the men of Israel were gathered together, and encamped in the valley of Elah, and set the battle in array against the Philistines.'),
  ('3d63f72e-b11c-5065-ac26-59fe82a981b4', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 3, 3, 'The Philistines stood on the mountain on the one side, and Israel stood on the mountain on the other side: and there was a valley between them.'),
  ('59ed2e2b-2330-5fa2-acfc-39e0ed69bc1b', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 4, 4, 'There went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span.'),
  ('2c28a60d-0451-5a95-adf2-09171ecd0777', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 5, 5, 'He had a helmet of brass on his head, and he was clad with a coat of mail; and the weight of the coat was five thousand shekels of brass.'),
  ('dbaa14a3-6f30-5911-ab82-b553ed7a2e0b', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 6, 6, 'He had brass shin armor on his legs, and a javelin of brass between his shoulders.'),
  ('da5fb56f-c7ab-5bae-a8b9-03062bc91ecc', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 7, 7, 'The staff of his spear was like a weaver''s beam; and his spear''s head [weighed] six hundred shekels of iron: and his shield bearer went before him.'),
  ('7e522c7f-754e-585d-a039-cd7809bb4c10', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 8, 8, 'He stood and cried to the armies of Israel, and said to them, "Why have you come out to set your battle in array? Am I not a Philistine, and you servants to Saul? Choose a man for yourselves, and let him come down to me.'),
  ('2f2a85cd-bfc9-5e36-afda-8ae5616c101e', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 9, 9, 'If he be able to fight with me, and kill me, then will we be your servants; but if I prevail against him, and kill him, then you will be our servants, and serve us."'),
  ('488edd58-151b-576b-a80d-29813e66f120', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 10, 10, 'The Philistine said, "I defy the armies of Israel this day! Give me a man, that we may fight together!"'),
  ('d1a412ef-1f7b-54ec-a647-376a143ab180', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 11, 11, 'When Saul and all Israel heard those words of the Philistine, they were dismayed, and greatly afraid.'),
  ('57e7a829-1752-5f09-a4f3-3557f1a97170', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 12, 12, 'Now David was the son of that Ephrathite of Bethlehem Judah, whose name was Jesse; and he had eight sons: and the man was an old man in the days of Saul, stricken [in years] among men.'),
  ('6fe3bcd0-241d-55c3-a868-de8a3d9554fa', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 13, 13, 'The three eldest sons of Jesse had gone after Saul to the battle: and the names of his three sons who went to the battle were Eliab the firstborn, and next to him Abinadab, and the third Shammah.'),
  ('f7a1e2fe-57c7-5af1-acc3-3191fb536e65', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 14, 14, 'David was the youngest; and the three eldest followed Saul.'),
  ('a9b0adc0-0a81-51f0-af0b-bdfb1f7d0e3a', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 15, 15, 'Now David went back and forth from Saul to feed his father''s sheep at Bethlehem.'),
  ('88741fc1-cb86-5d4e-a25a-0845bfce7886', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 16, 16, 'The Philistine drew near morning and evening, and presented himself forty days.'),
  ('76cb8e0d-c403-5615-a58d-c3db72c829a0', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 17, 17, 'Jesse said to David his son, "Now take for your brothers an ephah of this parched grain, and these ten loaves, and carry [them] quickly to the camp to your brothers;'),
  ('eb7773eb-769c-515a-afb9-fdabed8a6552', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 18, 18, 'and bring these ten cheeses to the captain of their thousand, and see how your brothers are doing, and bring back news."'),
  ('cf63f775-4962-5526-a5c4-8f914e20b60c', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 19, 19, 'Now Saul, and they, and all the men of Israel, were in the valley of Elah, fighting with the Philistines.'),
  ('a7e2db2b-22df-5364-a180-2974d4105e10', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 20, 20, 'David rose up early in the morning, and left the sheep with a keeper, and took, and went, as Jesse had commanded him; and he came to the place of the wagons, as the army which was going forth to the fight shouted for the battle.'),
  ('8058e96d-885e-5001-ae3c-2e54fb0167e5', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 21, 21, 'Israel and the Philistines put the battle in array, army against army.'),
  ('d69c342e-735b-56f1-ae4c-68f9b6ee3487', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 22, 22, 'David left his baggage in the hand of the keeper of the baggage, and ran to the army, and came and greeted his brothers.'),
  ('16e48b78-255b-568c-a6ea-5ffab86552db', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 23, 23, 'As he talked with them, behold, there came up the champion, the Philistine of Gath, Goliath by name, out of the ranks of the Philistines, and spoke according to the same words: and David heard them.'),
  ('06dd2e6d-45e3-5f18-a6fc-060ffd89da5c', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 24, 24, 'All the men of Israel, when they saw the man, fled from him, and were terrified.'),
  ('16a5d3ad-cf5d-539a-af2e-7d73cb4e4b61', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 25, 25, 'The men of Israel said, "Have you seen this man who is come up? He has surely come up to defy Israel. It shall be, that the man who kills him, the king will enrich him with great riches, and will give him his daughter, and make his father''s house free in Israel."'),
  ('5b487e7f-9dba-57af-a5a7-a88f57d28a89', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 26, 26, 'David spoke to the men who stood by him, saying, "What shall be done to the man who kills this Philistine, and takes away the reproach from Israel? For who is this uncircumcised Philistine, that he should defy the armies of the living God?"'),
  ('9b6a252e-7d6c-5de4-aa7f-79f714a703fb', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 27, 27, 'The people answered him in this way, saying, "So shall it be done to the man who kills him."'),
  ('df00bcf7-1b3c-5c28-a965-4649590aff29', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 28, 28, 'Eliab his eldest brother heard when he spoke to the men; and Eliab''s anger was kindled against David, and he said, "Why have you come down? With whom have you left those few sheep in the wilderness? I know your pride, and the naughtiness of your heart; for you have come down that you might see the battle."'),
  ('8b2606e4-2483-5fea-a6de-0ae8fc2ebfd3', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 29, 29, 'David said, "What have I now done? Is there not a cause?"'),
  ('b5231fba-f6f4-59de-a373-5e1c4d075a17', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 30, 30, 'He turned away from him toward another, and spoke like that again; and the people answered him again the same way.'),
  ('3658af15-343f-53c4-af98-5fa3ffe62348', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 31, 31, 'When the words were heard which David spoke, they rehearsed them before Saul; and he sent for him.'),
  ('18c33334-842a-501d-a2aa-a26467de3921', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 32, 32, 'David said to Saul, "Let no man''s heart fail because of him. Your servant will go and fight with this Philistine."'),
  ('d888b686-e708-5f0e-a11d-b3462e3d9db1', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 33, 33, 'Saul said to David, "You are not able to go against this Philistine to fight with him; for you are but a youth, and he a man of war from his youth."'),
  ('d64ccacb-a4f6-52df-a512-42bac4718cfc', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 34, 34, 'David said to Saul, "Your servant was keeping his father''s sheep; and when a lion or a bear came, and took a lamb out of the flock,'),
  ('8a0a3adc-c8ff-54b0-a4a8-14f941d98cfe', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 35, 35, 'I went out after him, and struck him, and rescued it out of his mouth. When he arose against me, I caught him by his beard, and struck him, and killed him.'),
  ('440100f4-086d-5af2-adda-a6da32a0edc3', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 36, 36, 'Your servant struck both the lion and the bear. This uncircumcised Philistine shall be as one of them, since he has defied the armies of the living God."'),
  ('abe16619-4b41-564e-a578-d449704de7fc', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 37, 37, 'David said, "Yahweh who delivered me out of the paw of the lion, and out of the paw of the bear, he will deliver me out of the hand of this Philistine." Saul said to David, "Go; and Yahweh shall be with you."'),
  ('d0ff45b9-49c8-5f0f-afe2-29a42e43a7d1', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 38, 38, 'Saul dressed David with his clothing. He put a helmet of brass on his head, and he clad him with a coat of mail.'),
  ('db83495a-094b-5ff4-aee0-21e26e33178a', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 39, 39, 'David strapped his sword on his clothing, and he tried to move; for he had not tested it. David said to Saul, "I can''t go with these; for I have not tested them." David took them off.'),
  ('3551163e-09f3-537e-ab79-727695177d1a', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 40, 40, 'He took his staff in his hand, and chose for himself five smooth stones out of the brook, and put them in the shepherd''s bag which he had, even in his wallet. His sling was in his hand; and he drew near to the Philistine.'),
  ('fb203a51-b902-502c-a2df-5c15aa48f918', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 41, 41, 'The Philistine came on and drew near to David; and the man who bore the shield went before him.'),
  ('c61fa6ae-26cc-5c21-a092-a79451e1cee4', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 42, 42, 'When the Philistine looked about, and saw David, he disdained him; for he was but a youth, and ruddy, and withal of a fair face.'),
  ('24d8f7d2-2342-5c33-a98e-6df36891b403', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 43, 43, 'The Philistine said to David, "Am I a dog, that you come to me with sticks?" The Philistine cursed David by his gods.'),
  ('9ad7f695-dd26-54eb-a09e-c863ad70223f', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 44, 44, 'The Philistine said to David, "Come to me, and I will give your flesh to the birds of the sky, and to the animals of the field."'),
  ('65c9e31b-b357-5f3d-a663-75b2949b0a42', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 45, 45, 'Then David said to the Philistine, "You come to me with a sword, and with a spear, and with a javelin: but I come to you in the name of Yahweh of Armies, the God of the armies of Israel, whom you have defied.'),
  ('6bcd0212-fc2e-5d27-ad84-f1e630ca6c4a', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 46, 46, 'Today, Yahweh will deliver you into my hand. I will strike you, and take your head from off you. I will give the dead bodies of the army of the Philistines this day to the birds of the sky, and to the wild animals of the earth; that all the earth may know that there is a God in Israel,'),
  ('52604c13-15e0-55a2-aca5-a05c10635193', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 47, 47, 'and that all this assembly may know that Yahweh doesn''t save with sword and spear: for the battle is Yahweh''s, and he will give you into our hand."'),
  ('570fb78d-caec-5fc7-ae9a-1899cb529b24', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 48, 48, 'It happened, when the Philistine arose, and came and drew near to meet David, that David hurried, and ran toward the army to meet the Philistine.'),
  ('8846280b-20ee-516b-ab11-2776d16b17e6', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 49, 49, 'David put his hand in his bag, took a stone, and slung it, and struck the Philistine in his forehead; and the stone sank into his forehead, and he fell on his face to the earth.'),
  ('3caf79b6-bdfa-5996-aec2-b65a49414d35', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 50, 50, 'So David prevailed over the Philistine with a sling and with a stone, and struck the Philistine, and killed him; but there was no sword in the hand of David.'),
  ('b3025ea5-cc89-512b-acde-4b42366c5683', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 51, 51, 'Then David ran, and stood over the Philistine, and took his sword, and drew it out of its sheath, and killed him, and cut off his head therewith. When the Philistines saw that their champion was dead, they fled.'),
  ('d6b019e8-d750-5447-a65c-bb87beb00f4a', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 52, 52, 'The men of Israel and of Judah arose, and shouted, and pursued the Philistines, until you come to Gai, and to the gates of Ekron. The wounded of the Philistines fell down by the way to Shaaraim, even to Gath, and to Ekron.'),
  ('554c43ea-1302-508d-a6ba-c28e71562b1c', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 53, 53, 'The children of Israel returned from chasing after the Philistines, and they plundered their camp.'),
  ('afc3ed56-0cd5-5c05-ada2-92ea65bdef92', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 54, 54, 'David took the head of the Philistine, and brought it to Jerusalem; but he put his armor in his tent.'),
  ('21549492-431e-5ecf-ae54-910de51fe300', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 55, 55, 'When Saul saw David go forth against the Philistine, he said to Abner, the captain of the army, "Abner, whose son is this youth?" Abner said, "As your soul lives, O king, I can''t tell."'),
  ('2ada200e-4ea8-57ce-a3dc-7d49e7350c63', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 56, 56, 'The king said, "Inquire whose son the young man is!"'),
  ('07813501-8645-5999-aecb-6b24197c64ed', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 57, 57, 'As David returned from the slaughter of the Philistine, Abner took him, and brought him before Saul with the head of the Philistine in his hand.'),
  ('f35421d6-0127-5106-af6f-886673c8090b', 'c4f3c7dd-07af-5a9b-a5b2-8162abcaa04a', NULL, 58, 58, 'Saul said to him, "Whose son are you, you young man?" David answered, "I am the son of your servant Jesse the Bethlehemite."'),
  ('bf58a147-6bf4-5044-ac08-d8c0a0230a11', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 1, 1, 'It happened, when he had made an end of speaking to Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul.'),
  ('12763b77-7e96-5f08-aa5c-52c07fb5270f', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 2, 2, 'Saul took him that day, and would let him go no more home to his father''s house.'),
  ('c1559848-3805-5235-ab44-02059d71937b', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 3, 3, 'Then Jonathan and David made a covenant, because he loved him as his own soul.'),
  ('4eb5d654-7c7d-5c03-a975-f912e59d048a', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 4, 4, 'Jonathan stripped himself of the robe that was on him, and gave it to David, and his clothing, even to his sword, and to his bow, and to his sash.'),
  ('1559878e-5b92-5055-a561-bcf333377d61', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 5, 5, 'David went out wherever Saul sent him, [and] behaved himself wisely: and Saul set him over the men of war, and it was good in the sight of all the people, and also in the sight of Saul''s servants.'),
  ('3da7c2e6-24cc-5786-a5c4-3114d9dabbdf', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 6, 6, 'It happened as they came, when David returned from the slaughter of the Philistine, that the women came out of all the cities of Israel, singing and dancing, to meet king Saul, with tambourines, with joy, and with instruments of music.'),
  ('4e28aa9f-4170-58ad-ae52-7c6cc65049c0', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 7, 7, 'The women sang one to another as they played, and said, "Saul has slain his thousands, David his ten thousands."'),
  ('e934b3e5-919b-5fc7-a35f-8f2a51090215', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 8, 8, 'Saul was very angry, and this saying displeased him; and he said, "They have ascribed to David ten thousands, and to me they have ascribed but thousands. What can he have more but the kingdom?"'),
  ('4b70e1e3-c6df-513a-a971-f9861924693a', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 9, 9, 'Saul eyed David from that day and forward.'),
  ('0f486b6a-d6db-5c99-af5b-4bca11749b33', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 10, 10, 'It happened on the next day, that an evil spirit from God came mightily on Saul, and he prophesied in the midst of the house. David played with his hand, as he did day by day. Saul had his spear in his hand;'),
  ('80a73880-3b1e-53a6-a402-7ec5a2aab579', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 11, 11, 'and Saul threw the spear; for he said, "I will pin David even to the wall!" David escaped from his presence twice.'),
  ('eb194777-34e3-55d1-accc-daa6fd9dce43', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 12, 12, 'Saul was afraid of David, because Yahweh was with him, and was departed from Saul.'),
  ('a75c8a7d-4c16-5dbe-a4e2-39d2987c9c56', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 13, 13, 'Therefore Saul removed him from him, and made him his captain over a thousand; and he went out and came in before the people.'),
  ('021d927f-57e4-5ca4-af0b-fda46023433d', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 14, 14, 'David behaved himself wisely in all his ways; and Yahweh was with him.'),
  ('790d6ed1-9c7e-56b7-acb9-6ce59a27c4f0', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 15, 15, 'When Saul saw that he behaved himself very wisely, he stood in awe of him.'),
  ('5df983bd-9ca1-59ff-a456-f0699901ea39', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 16, 16, 'But all Israel and Judah loved David; for he went out and came in before them.'),
  ('14f9eba9-2f13-5641-a75b-dd6aeb49f2ab', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 17, 17, 'Saul said to David, "Behold, my elder daughter Merab, I will give her to you as wife. Only be valiant for me, and fight Yahweh''s battles." For Saul said, "Don''t let my hand be on him, but let the hand of the Philistines be on him."'),
  ('e113d214-5bd8-5179-af0e-277e3ca446b4', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 18, 18, 'David said to Saul, "Who am I, and what is my life, or my father''s family in Israel, that I should be son-in-law to the king?"'),
  ('9382b3f3-e4f6-5c3b-ad16-7c40f2ed0dac', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 19, 19, 'But it happened at the time when Merab, Saul''s daughter, should have been given to David, that she was given to Adriel the Meholathite as wife.'),
  ('cf2018d9-82ee-5500-ab43-2fa3efdd3216', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 20, 20, 'Michal, Saul''s daughter, loved David; and they told Saul, and the thing pleased him.'),
  ('185c813b-7cd0-5319-a0db-d7e6001babe2', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 21, 21, 'Saul said, I will give her to him, that she may be a snare to him, and that the hand of the Philistines may be against him. Therefore Saul said to David, "You shall this day be my son-in-law a second time."'),
  ('a6a02fb1-219a-5e7f-a732-b779f2cd6919', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 22, 22, 'Saul commanded his servants, "Talk with David secretly, and say, ''Behold, the king has delight in you, and all his servants love you: now therefore be the king''s son-in-law.''"'),
  ('394e31e9-6b35-5749-ad56-42e6d97b6851', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 23, 23, 'Saul''s servants spoke those words in the ears of David. David said, "Does it seems to you a light thing to be the king''s son-in-law, since I am a poor man, and lightly esteemed?"'),
  ('2967b4ad-9b81-5974-a425-15526623fbfd', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 24, 24, 'The servants of Saul told him, saying, "David spoke like this."'),
  ('b4ab3dac-783f-54d6-aa0a-8392878b330c', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 25, 25, 'Saul said, "You shall tell David, ''The king desires no dowry except one hundred foreskins of the Philistines, to be avenged of the king''s enemies.''" Now Saul thought to make David fall by the hand of the Philistines.'),
  ('a1bc60d0-421b-56be-a8b9-a95b0f8e97eb', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 26, 26, 'When his servants told David these words, it pleased David well to be the king''s son-in-law. The days were not expired;'),
  ('d3f1fe43-a0b9-5e80-a356-1f6024f0e93f', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 27, 27, 'and David arose and went, he and his men, and killed of the Philistines two hundred men; and David brought their foreskins, and they gave them in full number to the king, that he might be the king''s son-in-law. Saul gave him Michal his daughter as wife.'),
  ('5b971869-a7d6-59df-a13c-581925a8d01a', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 28, 28, 'Saul saw and knew that Yahweh was with David; and Michal, Saul''s daughter, loved him.'),
  ('bfacd0a2-95d7-5234-ac75-cab10e70d6b4', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 29, 29, 'Saul was yet the more afraid of David; and Saul was David''s enemy continually.'),
  ('ac514680-a0a6-5456-a6ee-5d9b4ed19b97', '218a503e-6234-5c6a-a2d3-3045b94090e0', NULL, 30, 30, 'Then the princes of the Philistines went forth: and it happened, as often as they went forth, that David behaved himself more wisely than all the servants of Saul; so that his name was highly esteemed.'),
  ('ba8c2d64-cf7d-57e8-ae10-39cc29fa43d1', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 1, 1, 'Saul spoke to Jonathan his son, and to all his servants, that they should kill David. But Jonathan, Saul''s son, delighted much in David.'),
  ('8f0ae74f-648e-52e5-a0e8-6d6569e3440e', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 2, 2, 'Jonathan told David, saying, "Saul my father seeks to kill you. Now therefore, please take care of yourself in the morning, and live in a secret place, and hide yourself.'),
  ('25dbd3d9-284b-520e-add5-47cea3b903f1', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 3, 3, 'I will go out and stand beside my father in the field where you are, and I will talk with my father about you; and if I see anything, I will tell you."'),
  ('148127f2-4ae4-5db5-a474-eac3e5020f38', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 4, 4, 'Jonathan spoke good of David to Saul his father, and said to him, "Don''t let the king sin against his servant, against David; because he has not sinned against you, and because his works have been very good toward you;'),
  ('80a5c654-3a70-55d7-a22e-d1c01b976adc', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 5, 5, 'for he put his life in his hand, and struck the Philistine, and Yahweh worked a great victory for all Israel. You saw it, and rejoiced. Why then will you sin against innocent blood, to kill David without a cause?"'),
  ('48b2cc20-e8a6-5605-ad33-ee756bb7dd55', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 6, 6, 'Saul listened to the voice of Jonathan: and Saul swore, "As Yahweh lives, he shall not be put to death."'),
  ('cc7520bb-c61e-534f-a5c2-80fa787e9e87', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 7, 7, 'Jonathan called David, and Jonathan showed him all those things. Jonathan brought David to Saul, and he was in his presence, as before.'),
  ('f5100eb2-9c8f-529a-a424-4997a51e31da', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 8, 8, 'There was war again. David went out, and fought with the Philistines, and killed them with a great slaughter; and they fled before him.'),
  ('297eee33-8883-5e1c-ac3d-cee609f324a3', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 9, 9, 'An evil spirit from Yahweh was on Saul, as he sat in his house with his spear in his hand; and David was playing with his hand.'),
  ('f11954b2-55e9-53a0-a733-135d599d3902', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 10, 10, 'Saul sought to pin David even to the wall with the spear; but he slipped away out of Saul''s presence, and he stuck the spear into the wall. David fled, and escaped that night.'),
  ('48e65097-8c49-5c0c-a401-c108dfd3b63e', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 11, 11, 'Saul sent messengers to David''s house, to watch him, and to kill him in the morning. Michal, David''s wife, told him, saying, "If you don''t save your life tonight, tomorrow you will be killed."'),
  ('aa6a7722-bc95-55a5-a673-fba3551a43f3', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 12, 12, 'So Michal let David down through the window. He went, fled, and escaped.'),
  ('fd9d5fa6-7b41-583f-ab6d-327a3d5b5e63', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 13, 13, 'Michal took the teraphim, and laid it in the bed, and put a pillow of goats'' [hair] at its head, and covered it with the clothes.'),
  ('d02461c3-f21d-5aff-a119-2a26b5e48cf2', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 14, 14, 'When Saul sent messengers to take David, she said, "He is sick."'),
  ('e351a4c4-1b34-5f8a-aa2a-ce7b79c5e7f0', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 15, 15, 'Saul sent the messengers to see David, saying, "Bring him up to me in the bed, that I may kill him."'),
  ('1cdc87d7-d893-5260-abc4-9d3568010295', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 16, 16, 'When the messengers came in, behold, the teraphim was in the bed, with the pillow of goats'' hair at its head.'),
  ('aa56a415-8b63-5c9f-ac4d-f0fce240140f', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 17, 17, 'Saul said to Michal, "Why have you deceived me thus, and let my enemy go, so that he is escaped?" Michal answered Saul, "He said to me, ''Let me go! Why should I kill you?''"'),
  ('630d464d-87e0-5386-af97-3ff7369a4b2f', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 18, 18, 'Now David fled, and escaped, and came to Samuel to Ramah, and told him all that Saul had done to him. He and Samuel went and lived in Naioth.'),
  ('4424272e-04ea-54e0-a5f0-e01277ea3f87', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 19, 19, 'It was told Saul, saying, "Behold, David is at Naioth in Ramah."'),
  ('8599d6db-bc11-538d-ae0f-2df3beec328c', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 20, 20, 'Saul sent messengers to take David: and when they saw the company of the prophets prophesying, and Samuel standing as head over them, the Spirit of God came on the messengers of Saul, and they also prophesied.'),
  ('7c102c65-ba83-5cfb-a0d0-fb8b167baf89', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 21, 21, 'When it was told Saul, he sent other messengers, and they also prophesied. Saul sent messengers again the third time, and they also prophesied.'),
  ('91145f96-a345-5b35-adab-f1a274e03b1a', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 22, 22, 'Then went he also to Ramah, and came to the great well that is in Secu: and he asked, "Where are Samuel and David?" One said, "Behold, they are at Naioth in Ramah."'),
  ('582b2761-6a9b-5627-a6a2-68b22d06f451', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 23, 23, 'He went there to Naioth in Ramah. Then the Spirit of God came on him also, and he went on, and prophesied, until he came to Naioth in Ramah.'),
  ('086a290a-5fb1-5d40-a1c3-ae9a0d5325c8', 'd6fb6d65-682b-5543-a4c3-668ab6a92f50', NULL, 24, 24, 'He also stripped off his clothes, and he also prophesied before Samuel, and lay down naked all that day and all that night. Therefore they say, "Is Saul also among the prophets?"'),
  ('e724cb98-fe78-599a-aeb7-0acf88a679c8', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 1, 1, 'David fled from Naioth in Ramah, and came and said before Jonathan, "What have I done? What is my iniquity? What is my sin before your father, that he seeks my life?"'),
  ('d0b253b2-cb84-5628-a6f8-6f820cab9db2', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 2, 2, 'He said to him, "Far from it; you shall not die. Behold, my father does nothing either great or small, but that he discloses it to me; and why should my father hide this thing from me? It is not so."'),
  ('d36f6574-2d98-5f7f-a052-2668559a78f2', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 3, 3, 'David swore moreover, and said, "Your father knows well that I have found favor in your eyes; and he says, ''Don''t let Jonathan know this, lest he be grieved:'' but truly as Yahweh lives, and as your soul lives, there is but a step between me and death."'),
  ('38343459-aaf3-519c-a44b-25e86cb65aec', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 4, 4, 'Then Jonathan said to David, "Whatever your soul desires, I will even do it for you."'),
  ('c4ec389c-2f10-5c66-a109-d2c9ddcde8cf', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 5, 5, 'David said to Jonathan, "Behold, tomorrow is the new moon, and I should not fail to dine with the king; but let me go, that I may hide myself in the field to the third day at evening.'),
  ('5de600b8-d5d0-51e0-aa33-4d75091aee3c', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 6, 6, 'If your father miss me at all, then say, ''David earnestly asked leave of me that he might run to Bethlehem his city; for it is the yearly sacrifice there for all the family.'''),
  ('0bccf50e-11f4-5098-acac-0f8cb4164fda', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 7, 7, 'If he says, ''It is well;'' your servant shall have peace: but if he be angry, then know that evil is determined by him.'),
  ('45f14cbe-0aed-56b5-a718-cd8d47d9ed14', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 8, 8, 'Therefore deal kindly with your servant; for you have brought your servant into a covenant of Yahweh with you: but if there be in me iniquity, kill me yourself; for why should you bring me to your father?"'),
  ('e4214077-0b8d-5115-a1ce-5687ffe600aa', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 9, 9, 'Jonathan said, "Far be it from you; for if I should at all know that evil were determined by my father to come on you, then wouldn''t I tell you that?"'),
  ('a8e81c2b-3b11-561a-aaca-d9b31ec94fa8', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 10, 10, 'Then David said to Jonathan, "Who shall tell me if perchance your father answers you roughly?"'),
  ('26607ad0-c8d5-560c-a27b-1a155940a0a0', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 11, 11, 'Jonathan said to David, "Come, and let us go out into the field." They both went out into the field.'),
  ('139b99a6-2db9-542c-ae92-5cd2642ff518', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 12, 12, 'Jonathan said to David, "Yahweh, the God of Israel, [be witness]: when I have sounded my father about this time tomorrow, [or] the third day, behold, if there be good toward David, shall I not then send to you, and disclose it to you?'),
  ('c4aa6de9-91fb-5187-a503-f3f9d53ab108', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 13, 13, 'Yahweh do so to Jonathan, and more also, should it please my father to do you evil, if I don''t disclose it to you, and send you away, that you may go in peace: and Yahweh be with you, as he has been with my father.'),
  ('ed41b7b2-ad0e-5ad6-a2dd-81356df8c351', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 14, 14, 'You shall not only while yet I live show me the loving kindness of Yahweh, that I not die;'),
  ('dc4a3424-9977-5039-a469-7cb68347b696', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 15, 15, 'but also you shall not cut off your kindness from my house forever; no, not when Yahweh has cut off the enemies of David everyone from the surface of the earth."'),
  ('fac7c6d4-42bb-55ef-a651-5bae745c296e', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 16, 16, 'So Jonathan made a covenant with the house of David, saying, "Yahweh will require it at the hand of David''s enemies."'),
  ('d5689c77-a6be-5f51-a6f6-cc251ca5f2f0', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 17, 17, 'Jonathan caused David to swear again, for the love that he had to him; for he loved him as he loved his own soul.'),
  ('b4bc39b1-76a3-5716-ae18-c7f2d6a03942', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 18, 18, 'Then Jonathan said to him, "Tomorrow is the new moon: and you will be missed, because your seat will be empty.'),
  ('4dbad29b-f737-5dbb-a985-207ccad8a3cf', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 19, 19, 'When you have stayed three days, you shall go down quickly, and come to the place where you did hide yourself when the business was in hand, and shall remain by the stone Ezel.'),
  ('b836b8c2-d6a1-5eb2-aafc-abd643b3bdd8', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 20, 20, 'I will shoot three arrows on its side, as though I shot at a mark.'),
  ('76291603-b0fd-5dbf-af70-d9fce9f4e830', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 21, 21, 'Behold, I will send the boy, saying, ''Go, find the arrows!'' If I tell the boy, ''Behold, the arrows are on this side of you. Take them;'' then come; for there is peace to you and no hurt, as Yahweh lives.'),
  ('a1ae22c2-7e42-55c2-ad8f-444e3006436d', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 22, 22, 'But if I say this to the boy, ''Behold, the arrows are beyond you;'' then go your way; for Yahweh has sent you away.'),
  ('1ad66d4d-12bf-5feb-ac3d-aa25f2863dc3', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 23, 23, 'Concerning the matter which you and I have spoken of, behold, Yahweh is between you and me forever."'),
  ('6fbcf01c-1aba-5039-a99a-e9654fa63299', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 24, 24, 'So David hid himself in the field: and when the new moon was come, the king sat him down to eat food.'),
  ('4c944824-7972-5526-a95c-c8835b3b3964', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 25, 25, 'The king sat on his seat, as at other times, even on the seat by the wall; and Jonathan stood up, and Abner sat by Saul''s side: but David''s place was empty.'),
  ('511a57b2-351d-5ed9-a237-3dfec86b2dda', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 26, 26, 'Nevertheless Saul didn''t say anything that day: for he thought, "Something has happened to him. He is not clean. Surely he is not clean."'),
  ('d5025c97-2f16-523f-a81b-66ae401d5f77', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 27, 27, 'It happened on the next day after the new moon, the second day, that David''s place was empty. Saul said to Jonathan his son, "Why doesn''t the son of Jesse come to eat, neither yesterday, nor today?"'),
  ('d13fefc2-bb4b-55a4-a9b8-33458a3749fd', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 28, 28, 'Jonathan answered Saul, "David earnestly asked leave of me to go to Bethlehem.'),
  ('d5504f46-6e27-56c5-aa50-b46da703f021', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 29, 29, 'He said, ''Please let me go, for our family has a sacrifice in the city. My brother has commanded me to be there. Now, if I have found favor in your eyes, please let me go away and see my brothers.'' Therefore he has not come to the king''s table."'),
  ('b7f8f8d7-8750-5d0d-a039-7bf1f306f96b', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 30, 30, 'Then Saul''s anger was kindled against Jonathan, and he said to him, "You son of a perverse rebellious woman, don''t I know that you have chosen the son of Jesse to your own shame, and to the shame of your mother''s nakedness?'),
  ('8f4d4be4-31e9-5ad7-a550-4fbade766de5', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 31, 31, 'For as long as the son of Jesse lives on the earth, you shall not be established, nor your kingdom. Therefore now send and bring him to me, for he shall surely die!"'),
  ('748d4c03-98d3-5f61-a7e3-0ea1901a5aef', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 32, 32, 'Jonathan answered Saul his father, and said to him, "Why should he be put to death? What has he done?"'),
  ('682bc975-cbff-522d-a05b-34871da52197', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 33, 33, 'Saul cast his spear at him to strike him. By this Jonathan knew that his father was determined to put David to death.'),
  ('de85a2f4-19cf-5159-abc4-c720667e1032', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 34, 34, 'So Jonathan arose from the table in fierce anger, and ate no food the second day of the month; for he was grieved for David, because his father had done him shame.'),
  ('43100e61-3c3b-5beb-a8d1-c1fd15019bcf', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 35, 35, 'It happened in the morning, that Jonathan went out into the field at the time appointed with David, and a little boy with him.'),
  ('59a8913f-b395-5b04-a7e4-4ac301f27dea', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 36, 36, 'He said to his boy, "Run, find now the arrows which I shoot." As the boy ran, he shot an arrow beyond him.'),
  ('98d94a43-73e5-52f1-a55f-d48f3803d8b7', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 37, 37, 'When the boy was come to the place of the arrow which Jonathan had shot, Jonathan cried after the boy, and said, "Isn''t the arrow beyond you?"'),
  ('31fed6b8-5906-563d-a701-6d55d14c6edf', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 38, 38, 'Jonathan cried after the boy, "Go fast! Hurry! Don''t delay!" Jonathan''s boy gathered up the arrows, and came to his master.'),
  ('beed5564-c831-5407-ad9f-e2b1dac3657e', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 39, 39, 'But the boy didn''t know anything. Only Jonathan and David knew the matter.'),
  ('090792fe-f7aa-5d69-a691-40f46de49147', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 40, 40, 'Jonathan gave his weapons to his boy, and said to him, "Go, carry them to the city."'),
  ('ced3fea2-62ff-585e-aa1d-00937c8d043f', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 41, 41, 'As soon as the boy was gone, David arose out of [a place] toward the South, and fell on his face to the ground, and bowed himself three times. They kissed one another, and wept one with another, and David wept the most.'),
  ('f01406e1-6ec0-5e99-acd0-1088eefd8951', '2eb32069-ffe6-57a0-ae52-9a6e2e9d429a', NULL, 42, 42, 'Jonathan said to David, "Go in peace, because we have both sworn in the name of Yahweh, saying, ''Yahweh shall be between me and you, and between my seed and your seed, forever.''" He arose and departed; and Jonathan went into the city.'),
  ('3aa4f71a-657f-5281-a1bc-a9b2b661f514', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 1, 1, 'Then came David to Nob to Ahimelech the priest. Ahimelech came to meet David trembling, and said to him, "Why are you alone, and no man with you?"'),
  ('6229f3f0-fef5-5ac3-a68d-080981bf9739', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 2, 2, 'David said to Ahimelech the priest, "The king has commanded me a business, and has said to me, ''Let no man know anything of the business about which I send you, and what I have commanded you; and I have appointed the young men to such and such a place.'''),
  ('86018098-a765-5102-ad5c-361e46b097bf', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 3, 3, 'Now therefore what is under your hand? Give me five loaves of bread in my hand, or whatever there is present."'),
  ('57d45374-2cb8-5496-ad77-8a3bc8d0f021', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 4, 4, 'The priest answered David, and said, "There is no common bread under my hand, but there is holy bread; if only the young men have kept themselves from women."'),
  ('34772147-6e54-55f7-a55e-3a4172ab7fdd', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 5, 5, 'David answered the priest, and said to him, "Truly, women have been kept from us about these three days. When I came out, the vessels of the young men were holy, though it was but a common journey. How much more then today shall their vessels be holy?"'),
  ('3f20bbc5-b1ed-5408-a109-14024bdce7c7', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 6, 6, 'So the priest gave him holy [bread]; for there was no bread there but the show bread, that was taken from before Yahweh, to put hot bread in the day when it was taken away.'),
  ('8f68229d-b866-58f0-a04f-711870224c8d', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 7, 7, 'Now a certain man of the servants of Saul was there that day, detained before Yahweh; and his name was Doeg the Edomite, the best of the herdsmen who belonged to Saul.'),
  ('f00c7f0f-494a-520b-aedb-991f51d2e25b', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 8, 8, 'David said to Ahimelech, "Isn''t there here under your hand spear or sword? For I have neither brought my sword nor my weapons with me, because the king''s business required haste."'),
  ('6b4a4c7b-7820-556f-a743-c9a91af7998e', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 9, 9, 'The priest said, "The sword of Goliath the Philistine, whom you killed in the valley of Elah, behold, it is here wrapped in a cloth behind the ephod. If you will take that, take it; for there is no other except that here." David said, "There is none like that. Give it to me."'),
  ('864f3cba-a407-52a6-a945-9e73ed314a9e', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 10, 10, 'David arose, and fled that day for fear of Saul, and went to Achish the king of Gath.'),
  ('f010bc4d-10ab-5dc3-a0e8-f51b73659389', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 11, 11, 'The servants of Achish said to him, "Isn''t this David the king of the land? Didn''t they sing one to another about him in dances, saying, ''Saul has slain his thousands, David his ten thousands?''"'),
  ('c9e03f28-3c8e-511d-a5fe-a09122cdc7ae', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 12, 12, 'David laid up these words in his heart, and was very afraid of Achish the king of Gath.'),
  ('6ab8709a-54fd-5f2e-a287-04ca37ca0064', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 13, 13, 'He changed his behavior before them, and pretended to be mad in their hands, and scrabbled on the doors of the gate, and let his spittle fall down on his beard.'),
  ('d6f30ea2-98aa-509b-a608-226ca8ed9d78', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 14, 14, 'Then Achish said to his servants, "Look, you see the man is mad. Why then have you brought him to me?'),
  ('b3b2e360-b250-5e22-a41d-47e0d432f2cc', 'a9d6f818-b5dd-5531-a988-48a2d1060d97', NULL, 15, 15, 'Do I lack madmen, that you have brought this fellow to play the madman in my presence? Shall this fellow come into my house?"'),
  ('74dcfb3c-feac-549a-a974-ebe812d29e2c', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 1, 1, 'David therefore departed there, and escaped to the cave of Adullam. When his brothers and all his father''s house heard it, they went down there to him.'),
  ('6df40033-4655-5639-a9d1-2bdd3c6e89f6', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 2, 2, 'Everyone who was in distress, and everyone who was in debt, and everyone who was discontented, gathered themselves to him; and he became captain over them: and there were with him about four hundred men.'),
  ('1be69163-2fc3-5022-a023-15f8110787d7', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 3, 3, 'David went there to Mizpeh of Moab, and he said to the king of Moab, "Please let my father and my mother come out with you, until I know what God will do for me."'),
  ('d2a3f124-9f05-5a80-af64-562f2a5a1b86', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 4, 4, 'He brought them before the king of Moab; and they lived with him all the while that David was in the stronghold.'),
  ('d28c7ece-ad13-50d4-a007-14e7f4d523bc', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 5, 5, 'The prophet Gad said to David, "Don''t stay in the stronghold. Depart, and go into the land of Judah." Then David departed, and came into the forest of Hereth.'),
  ('07d31677-4482-5b77-a0c1-08d9caf8ebb5', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 6, 6, 'Saul heard that David was discovered, and the men who were with him. Now Saul was sitting in Gibeah, under the tamarisk tree in Ramah, with his spear in his hand, and all his servants were standing about him.'),
  ('011c2bb8-543a-5d1c-ad8b-7eb8f0e516a4', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 7, 7, 'Saul said to his servants who stood about him, "Hear now, you Benjamites! Will the son of Jesse give everyone of you fields and vineyards, will he make you all captains of thousands and captains of hundreds,'),
  ('3a34c88a-2e17-5437-af7e-df436a5c2bb6', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 8, 8, 'that all of you have conspired against me, and there is none who discloses to me when my son makes a treaty with the son of Jesse, and there is none of you who is sorry for me, or discloses to me that my son has stirred up my servant against me, to lie in wait, as at this day?"'),
  ('3eb84f81-2bc4-5c9b-af41-66c91a36f5ad', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 9, 9, 'Then Doeg the Edomite, who stood by the servants of Saul, answered and said, "I saw the son of Jesse coming to Nob, to Ahimelech the son of Ahitub.'),
  ('a054838a-e9fb-5cca-a4d6-9dd6f7ce6155', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 10, 10, 'He inquired of Yahweh for him, gave him food, and gave him the sword of Goliath the Philistine."'),
  ('ffdb56d3-45ad-52aa-ab88-7bbaf3627bc6', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 11, 11, 'Then the king sent to call Ahimelech the priest, the son of Ahitub, and all his father''s house, the priests who were in Nob: and they came all of them to the king.'),
  ('a6187087-0933-5b1f-a60b-05c721bde867', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 12, 12, 'Saul said, "Hear now, you son of Ahitub." He answered, "Here I am, my lord."'),
  ('083c2db7-4555-559d-a0d2-7d6ccec36f37', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 13, 13, 'Saul said to him, "Why have you conspired against me, you and the son of Jesse, in that you have given him bread, and a sword, and have inquired of God for him, that he should rise against me, to lie in wait, as at this day?"'),
  ('c295212d-cb80-59d9-ac82-590e6077f8b4', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 14, 14, 'Then Ahimelech answered the king, and said, "Who among all your servants is so faithful as David, who is the king''s son-in-law, and is taken into your council, and is honorable in your house?'),
  ('b5dda243-4a47-58d2-a96e-70378080330f', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 15, 15, 'Have I today begun to inquire of God for him? Be it far from me! Don''t let the king impute anything to his servant, nor to all the house of my father; for your servant knows nothing of all this, less or more."'),
  ('95656d35-add7-5f53-ad0d-9491facdc555', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 16, 16, 'The king said, "You shall surely die, Ahimelech, you, and all your father''s house."'),
  ('c33eabf2-af37-5053-a024-d0eeac0483d6', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 17, 17, 'The king said to the guard who stood about him, "Turn, and kill the priests of Yahweh; because their hand also is with David, and because they knew that he fled, and didn''t disclose it to me." But the servants of the king wouldn''t put forth their hand to fall on the priests of Yahweh.'),
  ('299bbee0-b256-5273-abc4-6058ae7f1175', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 18, 18, 'The king said to Doeg, "Turn and attack the priests!" Doeg the Edomite turned, and he attacked the priests, and he killed on that day eighty-five people who wore a linen ephod.'),
  ('7e446b8e-e70f-5535-a3b1-378ec277418a', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 19, 19, 'He struck Nob, the city of the priests, with the edge of the sword, both men and women, children and nursing babies, and cattle and donkeys and sheep, with the edge of the sword.'),
  ('846c3f0b-21b1-5dbd-ac33-1957378798a3', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 20, 20, 'One of the sons of Ahimelech, the son of Ahitub, named Abiathar, escaped, and fled after David.'),
  ('4eb03758-45e7-5d8f-ac54-9920e0f1bbb9', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 21, 21, 'Abiathar told David that Saul had slain Yahweh''s priests.'),
  ('fa87fb1e-fc05-5ff5-aa7d-7f7102b12799', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 22, 22, 'David said to Abiathar, "I knew on that day, when Doeg the Edomite was there, that he would surely tell Saul. I am responsible for the death of all the persons of your father''s house.'),
  ('ce5812ef-31ba-5234-a321-2d640549f6cf', '59adfb95-2fa5-57a5-aa3b-ccbc7aa9e521', NULL, 23, 23, 'Stay with me, don''t be afraid; for he who seeks my life seeks your life. For with me you shall be in safeguard."'),
  ('9c7e37a3-dd63-556d-a96d-7e9663e92a69', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 1, 1, 'David was told, "Behold, the Philistines are fighting against Keilah, and are robbing the threshing floors."'),
  ('5a3e5ef0-46b8-5249-a4cb-c1a8a385ab82', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 2, 2, 'Therefore David inquired of Yahweh, saying, "Shall I go and strike these Philistines?" Yahweh said to David, "Go strike the Philistines, and save Keilah."'),
  ('fa1d0ab3-056d-5d81-a18b-0bb9b5a81e57', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 3, 3, 'David''s men said to him, "Behold, we are afraid here in Judah: how much more then if we go to Keilah against the armies of the Philistines?"'),
  ('a3541a97-f92c-508b-ac08-be50a3abe650', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 4, 4, 'Then David inquired of Yahweh yet again. Yahweh answered him, and said, "Arise, go down to Keilah; for I will deliver the Philistines into your hand."'),
  ('a47e3606-340c-5eb0-afdb-2a27d2118415', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 5, 5, 'David and his men went to Keilah, and fought with the Philistines, and brought away their livestock, and killed them with a great slaughter. So David saved the inhabitants of Keilah.'),
  ('1e062752-e440-57d4-a9a3-8a8a387b93f2', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 6, 6, 'It happened, when Abiathar the son of Ahimelech fled to David to Keilah, that he came down with an ephod in his hand.'),
  ('fabd85b5-3e64-5d63-af62-4f3a718ef8f6', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 7, 7, 'It was told Saul that David had come to Keilah. Saul said, "God has delivered him into my hand; for he is shut in, by entering into a town that has gates and bars."'),
  ('1c028676-5960-56ae-afc7-b470e50ef5bc', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 8, 8, 'Saul summoned all the people to war, to go down to Keilah, to besiege David and his men.'),
  ('a2ca334e-95a3-5b01-ab75-a3bd113dacc8', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 9, 9, 'David knew that Saul was devising mischief against him; and he said to Abiathar the priest, "Bring the ephod here."'),
  ('49a599ed-09fd-52e1-a6a5-fdae94589db3', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 10, 10, 'Then David said, "O Yahweh, the God of Israel, your servant has surely heard that Saul seeks to come to Keilah, to destroy the city for my sake.'),
  ('99165544-f79c-5d97-a367-ff8f87abc0da', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 11, 11, 'Will the men of Keilah deliver me up into his hand? Will Saul come down, as your servant has heard? Yahweh, the God of Israel, I beg you, tell your servant." Yahweh said, "He will come down."'),
  ('5eb8c436-eb94-5e36-a6c0-5e98555d10f8', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 12, 12, 'Then David said, "Will the men of Keilah deliver me and my men into the hand of Saul?" Yahweh said, "They will deliver you up."'),
  ('2725a016-ee2a-58c2-a91e-3ec619a8ac87', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 13, 13, 'Then David and his men, who were about six hundred, arose and departed out of Keilah, and went wherever they could go. It was told Saul that David was escaped from Keilah; and he gave up going there.'),
  ('13ddeda2-3b83-5ffb-acb0-9f655f70f1ad', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 14, 14, 'David stayed in the wilderness in the strongholds, and remained in the hill country in the wilderness of Ziph. Saul sought him every day, but God didn''t deliver him into his hand.'),
  ('cf790c8e-4594-525a-a4e5-b81b5e510647', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 15, 15, 'David saw that Saul had come out to seek his life. David was in the wilderness of Ziph in the wood.'),
  ('5e22e561-a058-5d49-a893-b130376c64c5', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 16, 16, 'Jonathan, Saul''s son, arose, and went to David into the woods, and strengthened his hand in God.'),
  ('902a7d20-4b16-5642-a25a-51f62436ebd9', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 17, 17, 'He said to him, "Don''t be afraid; for the hand of Saul my father shall not find you; and you shall be king over Israel, and I shall be next to you; and that also Saul my father knows."'),
  ('8813e68d-fab6-501e-a8ae-ca0ccd24d237', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 18, 18, 'They both made a covenant before Yahweh: and David stayed in the woods, and Jonathan went to his house.'),
  ('4a27b67c-90e7-5c8d-a72f-a8b7bd74c8e3', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 19, 19, 'Then the Ziphites came up to Saul to Gibeah, saying, "Doesn''t David hide himself with us in the strongholds in the wood, in the hill of Hachilah, which is on the south of the desert?'),
  ('6b8c3ef2-1c37-5777-af7e-c5c3b9081da0', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 20, 20, 'Now therefore, O king, come down, according to all the desire of your soul to come down; and our part shall be to deliver him up into the king''s hand."'),
  ('91665bc0-0666-5490-a40e-fccf2548ed05', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 21, 21, 'Saul said, "You are blessed by Yahweh; for you have had compassion on me.'),
  ('7e6c740c-c4d1-5e0b-a825-49bcb339281f', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 22, 22, 'Please go make yet more sure, and know and see his place where his haunt is, [and] who has seen him there; for it is told me that he deals very subtly.'),
  ('408582b8-079d-59c9-aebe-c2f4fc1ee5bd', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 23, 23, 'See therefore, and take knowledge of all the lurking places where he hides himself, and come again to me with certainty, and I will go with you: and it shall happen, if he is in the land, that I will search him out among all the thousands of Judah."'),
  ('9a65c5fc-b875-5ccc-a7b3-a6e287e59a4e', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 24, 24, 'They arose, and went to Ziph before Saul: but David and his men were in the wilderness of Maon, in the Arabah on the south of the desert.'),
  ('5c31a884-8f4b-5d75-af43-32791636b605', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 25, 25, 'Saul and his men went to seek him. When David was told, he went down to the rock, and stayed in the wilderness of Maon. When Saul heard [that], he pursued after David in the wilderness of Maon.'),
  ('c8d68980-371f-5b85-a0b6-18d986451f89', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 26, 26, 'Saul went on this side of the mountain, and David and his men on that side of the mountain: and David made haste to get away for fear of Saul; for Saul and his men surrounded David and his men to take them.'),
  ('7dec0755-4450-500e-a3c8-604fafb3a2fe', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 27, 27, 'But a messenger came to Saul, saying, "Hurry and come; for the Philistines have made a raid on the land!"'),
  ('e73776e4-8547-571e-a81a-bf3f0a6ce84b', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 28, 28, 'So Saul returned from pursuing after David, and went against the Philistines: therefore they called that place Sela Hammahlekoth.'),
  ('958832ec-174a-5dc4-a64d-1564366b0280', '2ace50ab-d781-5440-a81e-cea6ed3460bb', NULL, 29, 29, 'David went up from there, and lived in the strongholds of En Gedi.'),
  ('69194cca-3a17-5cfc-ad97-14b5116c6b4c', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 1, 1, 'It happened, when Saul was returned from following the Philistines, that it was told him, saying, "Behold, David is in the wilderness of En Gedi."'),
  ('573622c3-9ad8-5755-a0a4-ba8c8a321165', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 2, 2, 'Then Saul took three thousand chosen men out of all Israel, and went to seek David and his men on the rocks of the wild goats.'),
  ('4db5d7bc-b1ff-55c9-ae3c-4b1e93d67fd3', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 3, 3, 'He came to the sheep pens by the way, where there was a cave; and Saul went in to relieve himself. Now David and his men were abiding in the innermost parts of the cave.'),
  ('e556e65d-03f8-5d30-afd2-a07f7fccd81f', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 4, 4, 'The men of David said to him, "Behold, the day of which Yahweh said to you, ''Behold, I will deliver your enemy into your hand, and you shall do to him as it shall seem good to you.''" Then David arose, and cut off the skirt of Saul''s robe secretly.'),
  ('15fa6d96-79b4-5e19-a484-4aa6b935bbf0', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 5, 5, 'It happened afterward, that David''s heart struck him, because he had cut off Saul''s skirt.'),
  ('1d072576-d4f5-5f80-a3fa-860956ce1f3a', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 6, 6, 'He said to his men, "Yahweh forbid that I should do this thing to my lord, Yahweh''s anointed, to put forth my hand against him, since he is Yahweh''s anointed."'),
  ('edbc1908-88cd-5ba2-accb-0c924d406a2f', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 7, 7, 'So David checked his men with these words, and didn''t allow them to rise against Saul. Saul rose up out of the cave, and went on his way.'),
  ('02daab03-ac3b-5182-a1c3-9774e501c7d3', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 8, 8, 'David also arose afterward, and went out of the cave, and cried after Saul, saying, "My lord the king!" When Saul looked behind him, David bowed with his face to the earth, and did obeisance.'),
  ('a730465c-b06d-5e9a-a9a9-03d015b51828', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 9, 9, 'David said to Saul, "Why do you listen to men''s words, saying, ''Behold, David seeks your hurt?'''),
  ('f253ddc8-cb36-5e0c-a092-76a6b519fbcb', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 10, 10, 'Behold, this day your eyes have seen how that Yahweh had delivered you today into my hand in the cave. Some urged me to kill you; but I spared you; and I said, I will not put forth my hand against my lord; for he is Yahweh''s anointed.'),
  ('f787ca35-5f1d-54fd-a50f-674d8735426a', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 11, 11, 'Moreover, my father, behold, yes, see the skirt of your robe in my hand; for in that I cut off the skirt of your robe, and didn''t kill you, know and see that there is neither evil nor disobedience in my hand, and I have not sinned against you, though you hunt for my life to take it.'),
  ('b0485351-2e84-564e-a42f-d9eca469db35', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 12, 12, 'May Yahweh judge between me and you, and may Yahweh avenge me of you; but my hand shall not be on you.'),
  ('e67d802a-b6c7-56f2-a8d7-bc3c323044cf', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 13, 13, 'As the proverb of the ancients says, ''Out of the wicked comes forth wickedness;'' but my hand shall not be on you.'),
  ('f9d89933-a15f-5fad-adc4-8fa1bb676177', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 14, 14, 'Against whom has the king of Israel come out? Whom do you pursue? A dead dog? A flea?'),
  ('947e76fa-1519-5754-a35a-002838255cb1', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 15, 15, 'May Yahweh therefore be judge, and give sentence between me and you, and see, and plead my cause, and deliver me out of your hand."'),
  ('3b7b3ae6-73a2-55f4-af48-6859165d2d16', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 16, 16, 'It came to pass, when David had made an end of speaking these words to Saul, that Saul said, "Is this your voice, my son David?" Saul lifted up his voice, and wept.'),
  ('89ebc237-d616-5772-a540-0360750db847', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 17, 17, 'He said to David, "You are more righteous than I; for you have done good to me, whereas I have done evil to you.'),
  ('15e462c1-26e4-53e4-a2c6-28381b02624e', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 18, 18, 'You have declared this day how you have dealt well with me, because when Yahweh had delivered me up into your hand, you didn''t kill me.'),
  ('0e69b564-c98f-5b3a-ad29-13f9a4c3c96d', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 19, 19, 'For if a man finds his enemy, will he let him go away unharmed? Therefore may Yahweh reward you good for that which you have done to me this day.'),
  ('1e645b3b-1a41-5230-ac00-167f77600feb', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 20, 20, 'Now, behold, I know that you shall surely be king, and that the kingdom of Israel shall be established in your hand.'),
  ('c23c46bb-3e1c-5c0a-ac06-435c1dd81132', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 21, 21, 'Swear now therefore to me by Yahweh, that you will not cut off my seed after me, and that you will not destroy my name out of my father''s house."')
